let motionObserver=null,motionStage=null,motionStageVisible=true,sceneEventTimer=null,sceneEventNode=null,sceneEventKind='',sceneEventStarted=0,sceneEventDuration=0,sceneEventRun=null;const motionPhases=new Map();
function applyVisualMode(){document.body?.classList.toggle('motion-light',visualMode==='light');document.body?.classList.toggle('visual-fine',visualMode==='fine');}
applyVisualMode();

function captureSceneMotion(){for(const el of document.querySelectorAll('[data-motion]'))for(const a of el.getAnimations?.()||[])if(a.animationName&&typeof a.currentTime==='number')motionPhases.set(el.dataset.motion+':'+a.animationName,a.currentTime);}
function syncSceneMotion(){motionStage?.classList.toggle('motion-paused',document.hidden||!motionStageVisible||!!$('#dialog').open);}
function bindSceneMotion(){motionObserver?.disconnect();motionObserver=null;motionStage=$('.cultivation-stage')||$('.profile-stage');motionStageVisible=true;if(!motionStage)return;const rect=motionStage.getBoundingClientRect?.();if(rect)motionStageVisible=rect.bottom>0&&rect.top<(window.innerHeight||Infinity);for(const el of document.querySelectorAll('[data-motion]'))for(const a of el.getAnimations?.()||[]){const t=motionPhases.get(el.dataset.motion+':'+a.animationName);if(t!==undefined)a.currentTime=t;}if(typeof IntersectionObserver!=='undefined'){const stage=motionStage;motionObserver=new IntersectionObserver(entries=>{if(stage!==motionStage)return;motionStageVisible=entries.some(e=>e.isIntersecting);syncSceneMotion();},{threshold:0});motionObserver.observe(stage);}restoreSceneEvent();syncSceneMotion();}
function clearSceneEvent(){clearTimeout(sceneEventTimer);sceneEventTimer=null;sceneEventKind='';sceneEventStarted=0;sceneEventDuration=0;sceneEventRun=null;if(sceneEventNode){sceneEventNode.classList.remove('scene-event-gain','scene-event-breakthrough','scene-event-enter');sceneEventNode=null;}}
function restoreSceneEvent(){if(!sceneEventKind)return;const elapsed=Date.now()-sceneEventStarted;if(screen!=='game'||tab!=='home'||sceneEventRun!==state?.runId||elapsed>=sceneEventDuration||document.hidden||$('#dialog').open||!motionStageVisible){clearSceneEvent();return;}const node=$('.cultivation-stage');if(!node){clearSceneEvent();return;}sceneEventNode=node;node.classList.add('scene-event-'+sceneEventKind);for(const el of document.querySelectorAll('.stage-event-light i, .stage-event-light'))for(const a of el.getAnimations?.()||[])a.currentTime=Math.max(0,elapsed);}
