function motionLabel(){return visualMode==='light'?'轻省':window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'静态':'已开';}
function savedText(){return blocked?'保存失败，请导出备份':state?.savedAt?'已保存 '+new Date(state.savedAt).toLocaleTimeString('zh-CN',{hour12:false}):'尚未保存';}
function saveUiPosition(){if(screen!=='game')return;uiPrefs.tab=tab;uiPrefs.scrolls[tab]=Math.max(0,window.scrollY||0);try{localStorage.setItem('wenshan-ui-v9',JSON.stringify(uiPrefs));}catch{}}
