function sync(){if(blocked)return;try{const r=readSave(localStorage,lastRaw);if(r.state&&r.raw!==lastRaw&&(r.state.runId!==state?.runId||r.state.revision>=state?.revision)){state=r.state;lastRaw=r.raw;}if(r.blocked){blocked=true;if(r.recoveryPending)storageError='有未完成的恢复操作，请在本机存档中选择恢复方式；备份已保留';}}catch{blocked=true;}}
function locked(fn){return navigator.locks?.request?navigator.locks.request(KEY,fn):Promise.resolve(fn());}
function toast(t,tone='info'){if(!t||document.hidden)return;const node=$('#dialog').open?$('#dialog-status'):$('#toast');for(const q of ['#toast','#dialog-status']){const n=$(q);n.classList.remove('show');n.textContent='';}node.textContent=t;node.dataset.tone=tone;node.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{for(const q of ['#toast','#dialog-status'])$(q).classList.remove('show');},4500);}
