function showLootFeedback(items){if(!items?.length||document.hidden||screen!=='game')return;const rows=Object.entries(itemCounts(items)),total=rows.reduce((n,[,count])=>n+count,0),first=rows.slice(0,2).map(([id,n])=>itemInfo(state,id).displayName+' ×'+n).join('、'),more=rows.length>2?'\n另有 '+(rows.length-2)+' 种，完整清单见挂机汇总':'';const node=$('.bottom-nav [data-go="bag"]');if(node){clearTimeout(lootTimer);node.classList.add('loot-arrived');node.dataset.lootCount=total>99?'99+':String(total);pulseElement(node);lootTimer=setTimeout(()=>{node.classList.remove('loot-arrived');delete node.dataset.lootCount;},3000);}if(!$('#dialog').open)toast('装备入袋 · '+total+'件\n'+first+more,'loot');}

function modal(html,kind='',preserveScroll=false){if(!preserveScroll)viewSerial++;const disclosures=preserveScroll?new Map(Array.from(document.querySelectorAll('#dialog-body details'),d=>[d.dataset.detail||d.querySelector('summary')?.textContent,d.open])):null;importReadSerial++;if(kind!=='importPreview'){pendingImport=null;pendingImportRunId=null;}if(kind!=='restorePreview')pendingRestore=null;modalRunId=state?.runId||null;activeModal=kind;const dialog=$('#dialog');$('#dialog-body').innerHTML=html+'<p id="dialog-context-warning" class="warning" hidden>当前仙途已变化，请关闭面板后重新核对。</p>';if(disclosures)for(const d of document.querySelectorAll('#dialog-body details')){const key=d.dataset.detail||d.querySelector('summary')?.textContent;if(disclosures.has(key))d.open=disclosures.get(key);}if(!dialog.open)dialog.showModal();syncSceneMotion();clearSceneEvent();if(!preserveScroll){dialog.scrollTop=0;$('#dialog-status').classList.remove('show');}refreshModalAvailability();}
function refreshModalAvailability(){if(!state||!$('#dialog').open)return;const stale=modalRunId!==state.runId;if(activeModal==='corePreview'&&pendingCore){const v=corePreview(state),staleCore=stale||v.signature!==pendingCore.signature;const el=$('[data-ui="confirmCore"]');if(el)el.dataset.unavailable=String(staleCore||!v.ready);if($('#core-status'))$('#core-status').textContent=staleCore?'状态已变化，请关闭后重新预览':v.reason;}if(activeModal==='presetPreview'&&pendingPreset){const p=pendingPreset,changed=stale||p.signature!==presetSignature(state,p.key,p.mode),confirm=$('[data-ui="confirmPreset"]');if(confirm)confirm.dataset.unavailable=String(changed||!presetPreview(state,p.mode==='save'?capturePreset(state):state.presets?.[p.key]).ok);if($('#preset-stale-warning'))$('#preset-stale-warning').hidden=!changed;}if(activeModal==='craftPreview'&&pendingCraft){const c=craftInfo(state,pendingCraft.tier,pendingCraft.slot),changed=stale||!c||c.signature!==pendingCraft.signature;const el=$('[data-ui="confirmCraft"]');if(el)el.dataset.unavailable=String(changed||!c?.available);if($('#craft-current-status'))$('#craft-current-status').textContent=changed?'炉方或配装已变化，请重新预览':c?.available?'材料齐备，确认后制作1件':c?.reason||'炉方无效';}if(activeModal==='specialtyPreview'&&pendingSpecialty){const v=specializationPreview(state,pendingSpecialty.id),changed=stale||state.sect!==pendingSpecialty.sect||!v.ok||v.signature!==pendingSpecialty.signature;const el=$('[data-ui="confirmSpecialty"]');if(el)el.dataset.unavailable=String(changed);if($('#specialty-status'))$('#specialty-status').textContent=changed?'宗门、专修或属性已变化，请重新预览':'脱战可免费改换，仅当前宗门专修生效';}if(activeModal==='bonuses'&&!stale&&bonusViewSignature!==bonusStatusSignature()){showBonuses(true);return;}if(activeModal==='treasures'&&!stale&&treasureViewSignature!==treasureStatusSignature()){showTreasures(true);return;}if($('#dialog-context-warning'))$('#dialog-context-warning').hidden=!stale;for(const el of document.querySelectorAll('#dialog [data-battle-lock]'))el.disabled=stale||!!combatBusy()||blocked||el.dataset.unavailable==='true';for(const el of document.querySelectorAll('#dialog [data-battle-notice]'))el.hidden=!combatBusy();if(activeModal==='recovery'){const rest=$('#dialog [data-action="rest"]');if(rest)rest.disabled=stale||blocked||!!combatBusy()||state.herbs<2||state.hp>=stats(state).hp;}if(activeModal==='foundationPicker'&&pendingFoundation){const p=pendingFoundation,changing=p.mode==='change',stale=p.runId!==state.runId||!changing&&(state.level!==10||p.type!==(state.extreme?'heaven':'normal')),unavailable=!p.path||!changing&&!afford(state,{stones:400,jade:12})||stale,el=$('[data-ui="confirmFoundation"]');if(el){el.dataset.unavailable=String(unavailable);el.disabled=unavailable||!!combatBusy()||blocked;}if($('#foundation-cost-warning'))$('#foundation-cost-warning').hidden=changing||afford(state,{stones:400,jade:12});if(stale&&$('#foundation-error'))$('#foundation-error').textContent='当前仙途或根基已变化，请关闭面板后重新打开核对。';}updateFarmPreview();}
function close(){viewSerial++;pendingCore=null;pendingCraft=null;pendingSpecialty=null;pendingPreset=null;pendingDismantle=null;pendingRecommendation=null;pendingFarm=null;pendingFarmRunId=null;pendingReceipt=null;pendingReceiptRunId=null;importReadSerial++;pendingImport=null;pendingImportRunId=null;pendingRestore=null;activeModal='';gearDetail=null;pendingFoundation=null;gearRenderSignature='';clearTimeout(gearRefreshTimer);$('#dialog').close();syncSceneMotion();}
const button=(label,action,extra='',disabled=false,cls='')=>`<button class="${cls}" data-action="${action}" ${['combat','flee','toggleAuto','autoPills'].includes(action)?`data-tower-run-id="${esc(state?.battle?.towerRunId||'')}" data-battle-floor="${state?.battle?.id||''}"`:''} ${extra.includes('data-run-id=')?'':`data-run-id="${esc(state?.runId||'')}"`} ${extra} ${disabled?'disabled':''}>${label}</button>`;
function bar(value,max,label,cls=''){return `<div class="bar ${cls}" role="progressbar" aria-label="${label}" aria-valuenow="${value}" aria-valuemin="0" aria-valuemax="${max}"><i style="width:${pct(value,max)}%"></i></div>`;}
function head(title,sub=''){return `<div class="section-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div></div>`;}
function menu(){return `<main class="main-menu"><div class="menu-top"><span class="volume">${chapterLabel(state)}</span><button class="text" data-ui="help">玩法说明</button></div><div class="menu-title"><span class="seal">问</span><h1>问山</h1><p>一息入道，万里山河</p></div><div class="menu-actions">${state?`<button class="primary large" data-ui="continue">继续仙途<small>${esc(state.name)} · ${levelName(state)}</small></button>`:''}<button class="${state?'secondary':'primary'} large" data-ui="new" ${blocked?'disabled':''}>${state?'另起新卷':'展开新卷'}</button>${legacy?`<div class="legacy-note"><b>你的旧仙途仍在</b><p>旧版进度独立保留；当前仙途可从炼气修至金丹初期。</p><a href="legacy/index.html">回到旧卷</a><button class="text" data-export="legacy">导出旧存档</button></div>`:''}${storageError?`<p class="warning">${esc(storageError)}</p>`:''}<button class="text" data-ui="saves">本机存档</button></div><div class="menu-foot">山河有尽 · 修行无涯<br><small>炼气 · 筑基 · 金丹初期，极境均为可选</small></div></main>`;}
function creator(){return `<main class="creation"><div class="page-top"><button class="text" data-ui="menu">返回</button><span class="volume">落笔成形</span></div><h1>以何身问道</h1><p class="muted">形貌不影响属性，随心而选</p><div class="segmented" aria-label="选择性别">${['male','female'].map(g=>`<button data-gender="${g}" class="${gender===g?'selected':''}" aria-pressed="${gender===g}">${g==='male'?'男':'女'}</button>`).join('')}</div><div class="portrait-choices">${PORTRAITS.filter(p=>p.gender===gender).map(p=>`<button class="portrait-choice ${p.id===portrait?'selected':''}" data-portrait="${p.id}" aria-pressed="${p.id===portrait}"><img src="portraits-v54/${p.id}-seated-thumb.webp" width="320" height="320" decoding="async" alt="${p.name}，盘坐修行"><span>${p.name}</span>${p.id===portrait?'<i>已选</i>':''}</button>`).join('')}</div><form id="character-form"><label for="character-name">道号</label><input id="character-name" name="name" maxlength="12" placeholder="为自己取一个名字" value="${esc(draftName)}" autocomplete="off" required><small>1–12 个字，之后也可在存档中查看</small><button class="primary large" type="submit">入山修行</button></form></main>`;}
function resourceHeader(){return `<header class="game-header"><div class="identity"><button class="brand" data-ui="menu">问山<span>${chapterLabel(state)}</span></button><div class="identity-person"><button class="profile-entry" data-ui="profile" aria-label="打开${esc(state.name)}的人物主页"><span><b>${esc(state.name)}</b><i>人物</i></span><small>${levelName(state)}</small></button></div><div class="header-tools"><button class="text" data-ui="stats">属性</button><button class="text" data-ui="saves">存档</button><details class="header-more" data-detail="header-more"><summary aria-label="展开画面与入门选项">更多</summary><div><button class="text" data-ui="visualSettings">画面设置</button><button class="text" data-ui="help" aria-label="打开教程与说明">入门指引</button></div></details></div></div><div class="resources">${['stones','ore','herbs','jade'].map(k=>`<button data-resource="${k}" aria-label="${RES[k]} ${fmt(state[k])}，查看用途"><span>${RES[k]}</span><strong title="${fmt(state[k])}">${compact(state[k])}</strong></button>`).join('')}</div></header>`;}
function guide(){if(!state.tutorial.active)return '';const i=state.tutorial.step,g=GUIDE[i],done=guideDone(state,g.id);return `<aside class="guide ${guideOpen?'expanded':'compact'}"><div class="guide-title"><span>入门 ${i+1}/6</span><button class="guide-title-button" data-ui="guideToggle" aria-expanded="${guideOpen}">${g.title}<small>${guideOpen?'收起':'查看说明'}</small></button>${done?`<button class="text" data-guide="next">${i===5?'完成':'下一步'}</button>`:`<button class="text" data-go="${g.tab}" data-highlight="${g.id}">带我去</button>`}</div>${guideOpen?`<p>${g.text}</p><div class="guide-actions"><button class="text" data-guide="skip">跳过教程</button><button class="small ${done?'primary':'secondary'}" data-guide="next" ${!done?'disabled':''}>${done?i===5?'完成指引':'已完成，下一步':'完成后继续'}</button></div>`:''}</aside>`;}
function rewardText(r){return ['stones','ore','herbs','jade','sigils'].filter(k=>r[k]).map(k=>`${RES[k]} +${fmt(r[k])}`).join(' · ');}
function itemCounts(items){const out={};if(Array.isArray(items))for(const id of items)out[id]=(out[id]||0)+1;else Object.assign(out,items||{});return out;}
function itemRewardList(items){return Object.entries(itemCounts(items)).map(([id,n])=>`${itemInfo(state,id)?.displayName||id} ×${n}`).join('、');}
function offline(){const r=state.offline;if(!r)return '';return `<aside class="offline"><button class="text float" data-action="dismissOffline">收起</button><b>归山所得 · ${time(r.credited)}</b><p>修为 +${fmt(r.exp)} · 挂机 ${r.rounds} 轮</p><p>${rewardText(r)||'本次没有材料收益'}</p>${r.items?.length?`<details><summary>所得装备 ${r.items.length} 件</summary><p>${itemRewardList(r.items)}</p></details>`:''}<small>${r.capped?'已按上限结算 8 小时':'离线单次最多结算 8 小时'}。收益已入袋，收起不会再次发放。</small><button class="text" data-ui="farmReport">查看完整挂机汇总</button></aside>`;}
function goalPanel(){const g=nextGoal(state);return `<aside class="goal-mini"><div><span>当前目标</span><b>${g.title}</b></div><button class="text" data-ui="followGoal">前往</button><details><summary>为什么做这件事</summary><p>${g.reason}</p></details></aside>`;}
function battleReport(type=null,id=null){const r=state.lastBattle;if(!r||type&&(r.type!==type||r.id!==id))return '';return `<section class="result-panel ${r.won?'won':'lost'}"><div class="result-heading"><b>${r.won?'胜':'败'} · ${esc(r.enemy)}</b><span>${r.turns} 回合</span></div><p>${r.won?(r.areaTrial||r.specialtyTrial||r.type==='core')&&!r.rewards.items.length&&!r.rewards.stones?'支线重访完成 · 本次仅练习，无重复奖励':rewardText(r.rewards):'未损失物品。'+esc(r.reason)}${r.areaTrial?'<br><span class="small-note">支线试炼不推进普通掉落轮数，也不影响挂机</span>':''}</p>${r.won&&r.rewards.items.length?`<div class="battle-loot" aria-label="本场所得装备">${Object.entries(itemCounts(r.rewards.items)).map(([id,n])=>{const g=itemInfo(state,id);return `<button class="loot-chip quality-${g.quality}" data-gear="${id}"><span>${g.treasure?'法宝':QUALITY[g.quality]}</span><b>${esc(g.displayName)} ×${n}</b></button>`;}).join('')}</div>`:''}<div class="button-pair">${button(r.specialtyTrial?state.specialtyTrials?.[r.specialtyTrial]?'重访专修 · 无奖励':'重试专修试炼':r.areaTrial?state.areaTrials?.[r.id]?'再次练习 · 无奖励':'重试支线挑战':'再次自动挑战','repeatBattle','',!!state.battle||state.hp<stats(state).hp*.25,'primary')}${button('调息 · 2 灵草','rest','',state.herbs<2||state.hp>=stats(state).hp,'secondary')}</div>${state.hp<stats(state).hp*.25?'<p class="warning small-note">先调息，或等自然恢复后重试</p>':''}<details data-detail="battle-result"><summary>战况与复盘</summary><div class="report-metrics"><span>造成伤害 <b>${r.dealt}</b></span><span>承受伤害 <b>${r.taken}</b></span><span>抵消伤害 <b>${r.blocked}</b></span><span>成功闪避 <b>${r.dodges}</b></span></div>${r.history.map(x=>`<p>${esc(x)}</p>`).join('')}</details></section>`;}
function encounterPanel(){if(!state.encounter||state.battle)return '';const e=areaEvent(state.encounter.area);return `<section class="encounter"><span class="volume">${AREAS.find(a=>a.id===state.encounter.area).name} · 山中缘事</span><h3>${e.title}</h3><p>${e.text}</p><div class="button-pair">${e.choices.map(c=>`<button class="secondary" data-encounter="${c.id}">${c.label}<small>${Object.entries(c.rewards).map(([k,n])=>(RES[k]||{exp:'修为',pills:'回春丹'}[k])+' +'+n).join(' · ')}</small></button>`).join('')}</div><button class="text" data-action="skipEncounter">继续赶路</button></section>`;}
function breakthroughChecklist(){if(state.level===20)return coreChecklist();if(state.level>=23)return '<section id="breakthrough-checklist" class="progress-checklist"><h3>金丹初期 · 三层</h3><p>本次境界开放到这里，完成初试即可收束小卷。修为可继续积累，不再扣除破境资源。</p><button class="secondary" data-source-route="core">前往金丹初试</button></section>';const circle=state.level===10||state.level===20,b=breakthroughInfo(state),extreme=state.level===20&&state.foundationExtreme,requirements=state.level===10?{stones:400,jade:12}:state.level===20?{stones:12000,jade:400}:b.cost,title=state.level===10?(state.extreme?'天道筑基准备':'普通筑基准备'):state.level===20?'可选 · 筑基极境':'下一层 · '+stageName(state.level+1);if(extreme)return '<section id="breakthrough-checklist" class="progress-checklist"><h3>筑基极境已成</h3><p>本卷境界已圆满，继续修炼仍会积累修为。</p></section>';return `<section id="breakthrough-checklist" class="progress-checklist"><h3>${title}</h3>${state.level===10?'<p class="small-note">筑基不扣修为，所有积累保留；极境条件另列在下方。</p>':`<div class="requirement-row"><span>修为</span><b>${fmt(state.exp)} / ${fmt(needExp(state))}</b><small class="${state.exp>=needExp(state)?'met':'unmet'}">${state.exp>=needExp(state)?'已达标':'还需 '+fmt(Math.max(0,Math.round((needExp(state)-state.exp)*10)/10))}</small></div>`}${Object.entries(requirements).map(([k,n])=>`<div class="requirement-row"><span>${RES[k]}</span><b>${fmt(state[k])} / ${fmt(n)}</b><small class="${state[k]>=n?'met':'unmet'}">${state[k]>=n?'已备齐':'还差 '+fmt(n-state[k])}</small>${state[k]<n?`<button class="text" data-resource-hunt="${k}">获取${RES[k]}</button>`:''}</div>`).join('')}${!circle&&b.area?`<div class="requirement-row"><span>历练</span><b>${AREAS.find(a=>a.id===b.area).name}</b><small class="${b.cleared?'met':'unmet'}">${b.cleared?'已通关':'还未通关'}</small>${!b.cleared?`<button class="text" data-source-area="${b.area}">前往历练</button>`:''}</div>`:''}</section>`;}
function showRecovery(){const st=stats(state);modal(`<h2>先养足气血</h2><p>打开时气血：${fmt(state.hp)} / ${fmt(st.hp)}</p><p>脱战每10秒恢复5%最大气血。等待时修炼与已开启的地图挂机照常继续，关闭页面也会按离线上限结算。</p><p>${state.herbs>=2?'已有足够灵草，可消耗2株立即调息回满。':'调息需要2灵草。可等待恢复，或到已通关的地图挂机取得灵草。'}</p>${button('调息 · 2灵草','rest','',!!state.battle||state.herbs<2||state.hp>=st.hp,'primary large')}<button class="secondary large" data-resource-hunt="herbs">查看灵草来源</button><p class="small-note">气血达到上限25%即可进场；当前目标建议恢复到65%再探索，减少连续落败。</p>`,'recovery');}
function characterArt(pose,id=state.portrait){return `portraits-v54/${id}-${pose}-${visualMode==='fine'?'large':'small'}.webp`;}
function cultivationView(){const c=cultivation(state),st=stats(state),b=breakthroughInfo(state),foundation=state.level>=11,circle=state.level===10||state.level===20,extreme=foundation?state.foundationExtreme:state.extreme,path=foundationChoice(state),full=state.exp>=needExp(state),stored=state.level>=23||circle&&extreme;return `<section class="meditation ${state.cultivating?'is-active':''}"><div class="cultivation-stage">${atmosphere('cultivation')}<div class="realm-line"><span class="vertical-note">${state.level>=21?'丹息初成':foundation?'凝元筑道':'吐纳天地'}</span><div><h1>${levelName(state)}</h1><p>${state.sect?SECTS.find(x=>x.id===state.sect).name+' · '+RANKS[rank(state)].name:'尚未拜入宗门'}</p></div><button class="text" data-ui="stats">战力 ${fmt(st.power)}</button></div><div class="portrait-stage">${cultivationMotion()}<div class="mountain-mist" data-motion="old-mist" aria-hidden="true"></div><div class="spirit-orbit" data-motion="spirit-orbit" aria-hidden="true"><i></i><i></i><i></i></div><div class="qi-aura" data-motion="qi-aura"></div><div class="qi-ring ring-one" data-motion="ring-one"></div><div class="qi-ring ring-two" data-motion="ring-two"></div><div class="qi-streams" aria-hidden="true"><i></i><i></i><i></i></div><img class="cultivator" data-motion="seated-breath" src="${characterArt('seated')}" data-character="${state.portrait}" data-pose="seated" width="600" height="600" decoding="async" fetchpriority="high" alt="${PORTRAITS.find(p=>p.id===state.portrait).name}盘坐吐纳"><div class="qi-dust" aria-hidden="true"><i></i><i></i><i></i><i></i></div><span class="portrait-caption">${state.cultivating?'灵息流转 · 修为积累中':'心静如水'}</span></div><div class="cultivation-controls"><div class="progress-label"><span>${stored?'储存修为':circle?'修为 · 极境可选':'修为'} ${b.ready?'<em class="ready-tag">可突破</em>':''}</span><b>${fmt(state.exp)}${stored?'':` <small class="threshold">/ ${fmt(needExp(state))}</small>`}</b></div>${stored?'':bar(Math.min(state.exp,needExp(state)),needExp(state),'修为进度，满后仍持续积累')}<div class="tick-row"><span>每 <b>${fmt(c.interval)}</b> 秒 · 修为 <b>+${fmt(c.gain)}</b></span><span id="tick-count">${state.cultivating?time(Math.max(0,c.interval-state.cultCarry))+'后运功':'尚未开始'}</span></div><div class="breath-track"><i id="tick-fill" style="width:${state.cultivating?pct(state.cultCarry,c.interval):0}%"></i></div><div class="main-actions">${button(state.cultivating?'暂停修炼':'开始修炼','cultivate','',false,state.cultivating?'secondary':'primary')}${state.level>=23?'<button class="secondary" data-source-route="core">金丹初试</button>':state.level===20?'<button class="primary" data-ui="corePrepare">准备结丹</button>':!circle?button(b.ready?'突破 · '+stageName(state.level+1):'破境条件未齐','breakthrough','',!b.ready,'primary'):!foundation?'<button class="primary" data-ui="ascend">选择道基并筑基</button>':!extreme?button('凝练筑基极境','extreme','',!full||!afford(state,{stones:12000,jade:400}),'primary'):'<button class="secondary" data-ui="bonuses">功法与法宝加成</button>'}</div><div class="stage-utility-row"><button class="text" data-ui="bonuses">修炼加成</button><button class="text" data-ui="visualSettings">动效 · ${motionLabel()}</button><button class="text" data-ui="breakthroughChecklist">${b.ready?'条件已齐':'查看缺什么'}</button></div></div></div><div class="cultivation-information"><p class="cultivation-rate">修炼时约 ${fmt(c.perMinute)} 修为 / 分钟${c.interval===10?' · 已达10秒间隔下限':''}</p>${foundation?`<button class="foundation-path-entry" data-ui="foundationPath"><span>${state.foundationType==='heaven'?'天道筑基':'普通筑基'}</span><b>${path?path.name:'尚未选择道基'}</b><small>${path?'查看 / 改换':'点击选择，不消耗资源'}</small></button>`:''}${!circle&&state.level<23&&!b.ready?`<p class="small-note breakthrough-hint">${b.reason} · <button class="text" data-ui="breakthroughChecklist">查看缺什么</button>${b.area&&!b.cleared?` · <button class="text" data-source-area="${b.area}">前往历练</button>`:''}</p>`:''}<details class="cultivation-notes" data-detail="cultivation-notes"><summary>破境清单与修炼加成</summary>${breakthroughChecklist()}${state.level!==20&&!stored&&!full?`<p class="small-note">按当前功法，${state.cultivating?'约':'开始修炼后约'} ${time(Math.max(0,Math.ceil((needExp(state)-state.exp)/c.gain)*c.interval-state.cultCarry))} 达到修为需求；历练和材料条件另计。</p>`:''}<p class="small-note accumulation-note">修为持续累计，手动突破只扣所需，余下保留。不会自动跳过境界。</p>${state.level===10&&!state.extreme?`<section class="optional-extreme"><h3>可选 · 先炼气极境</h3><p>2400 修为、600 灵石、30 灵髓。成就后战斗属性 +20%，再突破将成为天道筑基。</p>${button('先凝练炼气极境','extreme','',!full||!afford(state,{stones:600,jade:30}),'secondary large')}<p class="small-note">也可以不经极境，直接选择道基成为普通筑基。</p></section>`:''}${state.level===20?`<p>筑基圆满可完成全部问基三试，不要求极境。${state.foundationExtreme?'筑基极境额外战斗属性 +20% 已生效。':'可选极境需要80000修为、12000灵石、400灵髓，额外战斗属性 +20%。'}</p><button class="secondary large" data-source-route="foundation">前往筑基终章</button>${!state.foundationExtreme?button('可选 · 凝练筑基极境','extreme','',!full||!afford(state,{stones:12000,jade:400}),'secondary large'):''}<p class="small-note">筑基极境的20%战斗加成会永久保留。结丹后无法补炼筑基极境，请在预览中确认；圆满直接结丹也能完成金丹初卷。</p>`:''}${state.extreme?'<p class="small-note">炼气极境的20%战斗属性保留，只计一次，不会在筑基时重复叠加。</p>':''}<button class="text bonus-link" data-ui="bonuses">查看功法叠加 ${Math.round(c.gainBonus*100)}% 增益 / ${Math.round(c.speed*100)}% 减时</button>${foundation?'<button class="text" data-ui="foundationHelp">筑基入门说明</button>':''}</details></div></section>`;}

function battleView(){const b=state.battle,st=stats(state),intent=enemyIntent(b),cp=combatProfile(state),f=state.lastCombat;return `<section class="battle battle-compact"><div class="battle-title"><h3>${b.name}</h3><span>${b.auto?'自动斗法':'手动斗法'} · ${b.turn} 回合</span></div><div class="progress-label"><span>对手</span><b>${b.hp} / ${b.maxHp}</b></div>${bar(b.hp,b.maxHp,'对手气血','enemy')}<div class="progress-label"><span>自己 · 真气 ${state.qi}/3</span><b>${state.hp} / ${st.hp}</b></div>${bar(state.hp,st.hp,'你的气血')}<p class="compact-intent ${intent.charged?'warning':''}">下一招：${intent.name} · ${intent.detail}</p>${f?`<p class="exchange-line">${esc(f.skill)} · 伤害 ${f.damage}${f.taken?' / 承伤 '+f.taken:''}${f.healed?' / 回复 '+f.healed:''}</p>`:''}<div class="battle-switches">${button(b.auto?'改为手动':'开启自动','toggleAuto','',false,'secondary small')}${button('撤退','flee','',false,'text')}<button class="text" data-ui="loadout">主辅功法</button></div>${!b.auto?`<div class="battle-actions">${button('出剑','combat','data-move="strike"',false,'primary')}${button(cp.skill+' · '+cp.cost+' 真气','combat','data-move="skill"',state.qi<cp.cost)}${button('守势 · 回 2 真气','combat','data-move="guard"')}${button('闪避步 · '+Math.round(cp.dodge*100)+'%','combat','data-move="dodge"',state.qi<1)}${button('服丹 · 回复 50%','combat','data-move="pill"',!state.pills)}</div>`:''}<details data-detail="battle-log"><summary>斗法记录与自动策略</summary><p class="small-note">自动优先击杀、应对蓄势、运用主修技能。支线中会按气血压制回潮、交替招式并消解星压。离开页面会暂停自动斗法。连续闯塔需回来点继续；已开启的地图挂机仍可离线结算。</p>${button('自动服丹：'+(b.usePills?'开启':'关闭'),'autoPills','',false,'small secondary')}<ul class="combat-log">${b.log.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details></section>`;}
function activity(){if(state.towerRun?.active)return `<button class="activity" data-ui="battleLocation">连续闯塔${state.towerRun.paused?'已暂停':'进行中'} · 已过${state.tower}层 · 查看进度</button>`;if(!state.farm)return '';const a=AREAS.find(x=>x.id===state.farm);return `<div class="activity"><div><span class="tiny-seal">巡</span><b>${a.name} · 挂机中</b><small id="farm-count">${time(a.seconds-state.farmCarry)}后归来</small></div><button class="text" data-ui="farmReport">收益汇总</button></div>`;}
function backupReminder(){return state.level>=3&&(!state.lastExportAt||Date.now()-state.lastExportAt>86400000)?'<div class="backup-reminder"><span>本机进度，建议定期备份</span><button class="text" data-export="current">导出存档</button></div>':'';}
function home(){const g=nextGoal(state);return `${cultivationView()}<div class="home-activity">${state.battle?`<button class="activity battle-resume" data-ui="battleLocation">${state.battle.auto?'自动':'手动'}斗法进行中 · 查看当前地点</button>`:activity()}</div><div class="home-quick-links"><button class="text" data-ui="presets">配装</button><button class="text" data-go="techniques">功法</button><button class="text" data-go="market">坊市</button></div><button class="next-step-line" data-ui="followGoal"><span>下一步</span><div><b>${g.title}</b><small>${g.reason}</small></div></button><details class="home-notebook" data-detail="home-notebook"><summary>挂机、收益与修行手札${state.offline?' · 有离线收获':''}</summary>${state.offline?'<button class="return-summary" data-ui="offlineDetails">离线收益已入袋 · 点此查看</button>':''}${goalPanel()}${backupReminder()}<details class="quiet-details" data-detail="journal"><summary>修行手札与最近战报</summary>${battleReport()}${state.history.slice(0,8).map(x=>`<p>${esc(x)}</p>`).join('')||'<p>先开启吐纳，再去青溪渡历练。</p>'}</details></details>`;}

function paneButtons(kind,current,options){return `<div class="section-tabs">${options.map(([id,n])=>`<button data-${kind}="${id}" class="${current===id?'active':''}" aria-pressed="${current===id}">${n}</button>`).join('')}</div>`;}
function dropPreview(a){const d=dropStatus(state,a.id),firstTreasures=Object.entries(TREASURES).filter(([,t])=>t.area===a.id);return `<section class="drop-preview drop-visible"><div class="drop-heading"><h3>此地装备掉落</h3><span>${d.cleared?'再 '+d.remaining+' 轮，主掉落1件＋轮换部位1件':'首次通关必得1件主掉落'}</span></div>${firstTreasures.map(([id,t])=>`<section class="first-clear-treasure"><b>首通法宝 · ${GEAR[id].name}</b><p>${d.cleared?'已完成首通，可在法宝录直接激活':'首次主动通关额外获得1件'}；重访和挂机不重复掉落。</p><button class="text" data-gear="${id}">查看法宝与共鸣</button></section>`).join('')}<p class="drop-section-label">主掉落 · 兵器 / 法衣 / 灵饰</p><div class="drop-grid">${a.loot.map(id=>{const g=itemInfo(state,id);return `<button data-gear="${id}">${gearIcon(g.slot)}<b>${g.name}</b><small>${QUALITY[g.quality]} · ${SLOTS[g.slot]}</small></button>`;}).join('')}</div><p class="drop-guarantee">${d.cleared?`已累计 ${d.count} 轮 · ${state.farm===a.id?d.planReachesDrop?'继续当前计划，约 '+time(d.seconds)+' 后掉落':'当前计划会先结束，续挂后累计满 '+d.remaining+' 轮才掉落':'挂机 '+d.remaining+' 轮约 '+time(d.seconds)}`:'击败守关者后，开启挂机即可持续刷装备'}</p><p class="drop-section-label">额外轮换 · 道冠 / 靴履 / 腰带</p><div class="drop-grid">${a.accessories.map(id=>{const g=itemInfo(state,id);return `<button data-gear="${id}" class="${id===d.nextAccessory?'next-accessory':''}">${gearIcon(g.slot)}<b>${g.name}</b><small>${id===d.nextAccessory?'下次额外掉落':QUALITY[g.quality]+' · '+SLOTS[g.slot]}</small></button>`;}).join('')}</div><p class="drop-guarantee">再累计 ${d.accessoryRemaining} 轮，额外获得${GEAR[d.nextAccessory].name}。连续15轮覆盖三类，不挤占主掉落。</p><details class="quiet-details" data-detail="drop-${a.id}"><summary>完整掉落规则</summary><p>首通必得1件主掉落，此后本图累计轮数到5的倍数，主掉落1件，并额外轮换1件道冠、靴履或腰带。主动挑战与挂机共用计数。</p><p>主掉落从上面${a.loot.length}种中等概率选1件，各约${fmt(100/a.loot.length)}%，带1条小幅词条。额外三部位按道冠、靴履、腰带循环，使用固定基础属性，不另加随机词条。</p><p>已有轮数照常接着计算，不重置、不补发。坊市仍可直接购买三部位；独立法宝另有地图首通、问心塔与两卷终章来源，见法宝录；不混入重复刷取的主掉落池。</p></details></section>`;}


function mapView(){const selected=state.uiMap?.area||'brook',pane=['regions','tower','finale','foundation','core'].includes(state.uiMap?.pane)?state.uiMap.pane:'regions',rawChapter=pane==='core'?'core':pane==='foundation'?'foundation':pane==='finale'?'qi':state.uiMap?.chapter||realmChapter(AREAS.find(a=>a.id===selected)?.gate||1),chapter=['qi','foundation','core'].includes(rawChapter)?rawChapter:'qi',areas=AREAS.filter(a=>realmChapter(a.gate)===chapter),finale=chapter==='core'?'core':chapter==='foundation'?'foundation':'finale';return `<div class="map-topline">${head('山河图')}<button class="text" data-ui="farmGoals">挂机目标</button></div><div class="map-chapters">${[['qi','炼气山河',1],['foundation','筑基仙路',11],['core','金丹初境',21]].map(([id,name,gate])=>`<button data-map-chapter="${id}" class="${chapter===id?'active':''}">${name}${state.level<gate?' · 待开启':''}</button>`).join('')}</div>${paneButtons('map-pane',pane,[['regions','区域历练'],['tower','问心塔'],[finale,chapter==='core'?'金丹初试':chapter==='foundation'?'筑基终章':'炼气终章']])}${pane==='regions'?`<details class="map-destinations" data-detail="map-destinations"><summary><span>当前地点 · ${(areas.find(a=>a.id===selected)||areas[0]).name}</span><b>切换地区</b></summary><div class="region-selector foundation-regions">${areas.map(a=>`<button data-area="${a.id}" class="${selected===a.id?'selected':''}" ${state.battle?'disabled':''}><b>${a.name}</b><small>${state.level>=a.gate?state.cleared.includes(a.id)?'已通关':'可挑战':stageName(a.gate)+'开放'}</small></button>`).join('')}</div></details>${regionView(areas.find(a=>a.id===selected)||areas[0])}`:pane==='tower'?towerView():pane==='core'?coreFinaleView():pane==='foundation'?foundationFinaleView():finaleView()}`;}



function fieldTrialPanel(a){const t=areaTrialInfo(state,a.id);if(!t)return '';const gear=GEAR[t.gear.base],stat={atk:'攻伐',def:'护体',hp:'气血'}[t.gear.stat];return `<details class="field-trial" data-detail="field-trial-${a.id}"><summary><span>支线 · ${t.name}</span><b>${t.done?'已完成':t.available?'可挑战':stageName(t.gate)}</b></summary><p>${t.done?t.ending:t.story}</p><div class="field-trial-rule"><b>这一战怎么应对</b><p>${t.rule}</p><p>${t.counter}</p></div><p class="small-note">${t.enemy} · 气血 ${t.hp} / 攻伐 ${t.atk} / 基础护体 ${t.def}</p><p><b>首次胜利</b><br>${gear.name} · 固定${stat} +${t.gear.value}<br>${rewardText(t.rewards)}</p><p class="small-note">固定词条装备只发1件，仍可正常换装、分解和保存预设；重访不重复发奖。普通历练与挂机照常掉落，不掉支线固定奖励，不要求极境或套装。</p><p class="${t.available?'small-note':'warning'}">${t.reason}</p><div class="button-pair">${button(t.done?'重访练习 · 无奖励':'自动挑战支线','areaTrial',`data-id="${a.id}"`,!t.available||!!state.battle,'primary')}<button class="secondary" data-ui="presets">检查配装预设</button></div></details>`;}

function regionView(a){const open=state.level>=a.gate,cleared=state.cleared.includes(a.id),active=state.battle?.type==='area'&&state.battle.id===a.id;return `<article class="region-panel" id="area-${a.id}"><div class="region-title"><h2>${a.name}</h2><span>${state.farm===a.id?'挂机中':cleared?'已通关':'未通关'}</span></div><p class="muted">${a.desc}</p>${!active?sceneBanner('travel-river','云海山河与蜿蜒古道'):''}${a.chapter==='foundation'||a.chapter==='core'?`<p class="region-tactic"><b>${enemyIntent({type:'area',id:a.id,turn:3}).name}</b> · ${enemyIntent({type:'area',id:a.id,turn:3}).detail}</p>`:''}${!open?`<p class="region-locked">${stageName(a.gate)}开放此地</p>`:active?battleView():`${battleReport('area',a.id)}${!state.lastBattle||state.lastBattle.type!=='area'||state.lastBattle.id!==a.id||state.lastBattle.areaTrial?`<button class="primary large" data-action="autoChallenge" data-id="${a.id}" ${state.battle?'disabled':''}>${cleared?'自动挑战':'首次自动挑战'}</button>`:''}<div class="region-tools">${cleared?state.farm===a.id?button('停止挂机','farm','data-id="stop"',false,'secondary'):`<button class="secondary" data-farm-config="${a.id}" ${state.battle?'disabled':''}>在此挂机</button>`:'<span class="small-note">通关一次后，即可持续挂机</span>'}<button class="text" data-ui="loadout">主辅功法</button></div>`}${state.farm===a.id?`<p class="active-hint" id="map-farm-count">${time(a.seconds-state.farmCarry)}后完成本轮 · ${farmPlanText()}</p>`:''}<details class="quiet-details"><summary>对手与资源</summary><p>${a.enemy} · 气血 ${a.hp} / 攻伐 ${a.atk} / 护体 ${a.def}</p><p>蓄势招：${enemyIntent({type:'area',id:a.id,turn:3}).name}</p><p>每轮 ${a.seconds} 秒：${a.stones} 灵石、${a.ore} 玄铁、${a.herbs} 灵草、${a.jade} 灵髓</p></details>${dropPreview(a)}${fieldTrialPanel(a)}${state.encounter?.area===a.id&&!state.battle?`<details class="quiet-details"><summary>山中缘事 · ${areaEvent(a.id).title}</summary>${encounterPanel()}</details>`:''}</article>`;}
function towerView(){const cap=towerCap(state),r=state.towerRun;return `<section class="tower-section"><h2>问心塔</h2><p class="muted">已过 ${state.tower} / 15 层 · 当前开放至 ${cap} 层 · 塔印 ${state.sigils}</p>${towerRunPanel()}${state.battle?.type==='tower'?battleView():state.lastBattle?.type==='tower'?battleReport('tower',state.lastBattle.id):''}${!state.battle?sceneBanner('tower-journey','云雾高崖上的问心古塔'):''}<details class="quiet-details" data-detail="tower-rules"><summary>连续规则与首通奖励</summary><p>从下一未通关层出发，获胜自动继续。到当前开放上限、失利、气血不足25%或手动停止时结束；不自动回刷，不自动调息，不默认消耗丹药。</p><p>切后台、回主菜单或重新打开会暂停，回来点继续。闯塔不计算离线战斗，原修炼与地图挂机照常结算。</p><p>炼气三层开放前10层。五层首通得山河钟，十层得一线天。筑基一、三、五、七、九层依次开放第11–15层；第15层首通另得40灵髓。单层重访只得1塔印及灵石。</p></details><h3 class="tower-single-heading">单层挑战 / 重访</h3><div class="tower-floors">${Array.from({length:15},(_,i)=>i+1).map(f=>{const gate=f<=10?3:11+(f-11)*2;return `<button data-action="autoTower" data-floor="${f}" class="${f<=state.tower?'cleared':''}" ${state.battle||r?.active||state.level<gate||f>state.tower+1?'disabled':''}>${f}<small>${state.level<gate?stageName(gate):f<=state.tower?'重访':f===state.tower+1?'挑战':'未至'}</small></button>`;}).join('')}</div>${button('30 塔印换 10 灵髓','exchange','',state.sigils<30||!!state.battle||r?.active,'secondary')}</section>`;}
function towerRunPanel(){const r=state.towerRun,cap=towerCap(state),open=state.tower<cap;return `<section class="tower-run-panel" aria-label="连续闯塔">${r?.active?`<div class="tower-run-heading"><h3>连续闯塔 · ${r.paused?'已暂停':'进行中'}</h3><b>第 ${state.battle?.type==='tower'?state.battle.id:r.lastWon+1} 层</b></div><p>${r.paused?r.reason||'点击继续，接着当前对手':state.battle?'获胜后自动挑战下一层':'本层奖励已入袋，即将继续下一层'}</p><div class="button-pair">${button(r.paused?'继续闯塔':'暂停闯塔',r.paused?'resumeTowerRun':'pauseTowerRun',`data-tower-run-id="${esc(r.id)}"`,false,'primary')}${button('停止本次闯塔','stopTowerRun',`data-tower-run-id="${esc(r.id)}"`,false,'secondary')}</div>`:`${button(open?'连续自动闯塔 · 第 '+(state.tower+1)+' 层起':state.tower>=15?'问心塔已登顶':'当前境界没有新塔层','startTowerRun',`data-floor="${state.tower+1}"`,!open||!!state.battle||state.hp<stats(state).hp*.25,'primary large')}${state.hp<stats(state).hp*.25&&open?'<p class="warning">先调息至25%以上气血，再开始闯塔。</p>':''}`} ${r?`<div class="tower-run-summary"><b>${r.active?'本次已得':'本次结束'} · 连胜 ${r.wins} 层${r.wins?'（第'+r.startFloor+'–'+r.lastWon+'层）':''}</b>${!r.active?`<p>${esc(r.reason)}</p>`:''}<p>灵石 +${fmt(r.rewards.stones)} · 塔印 +${fmt(r.rewards.sigils)}${r.rewards.jade?' · 灵髓 +'+fmt(r.rewards.jade):''}</p>${r.rewards.items.length?`<p>${itemRewardList(r.rewards.items)}</p>`:''}<small>奖励逐层自动入袋，此处只作汇总，不需再领取。</small></div>`:'<p class="small-note">从未通关层连续挑战，保留原有首通奖励规则。</p>'}</section>`;}

function foundationFinaleView(){return `<section class="finale-panel"><span class="volume">筑基卷 · 问基三试</span><h2>以何道开山</h2><p>筑基圆满即可赴试。普通筑基、天道筑基都能完成，不要求任何极境。</p>${state.battle?.type==='foundation'?battleView():state.lastBattle?.type==='foundation'?battleReport('foundation',state.lastBattle.id):''}<div class="trial-stages">${[1,2,3].map(n=>`<article><div><h3>${trialEnemy('foundation',n).name}</h3><p>${['','守住本道心','辨清眼前虚实','以道基回应山河'][n]}</p></div>${button(state.foundationFinale>=n?'重访':'自动赴试','foundationTrial',`data-stage="${n}"`,!!state.battle||state.level<20||n>state.foundationFinale+1,'secondary')}</article>`).join('')}</div>${state.foundationFinale>=3?'<p class="chapter-complete">筑基卷已完成 · 观澜镜已记入法宝录</p><button class="secondary large" data-ui="treasures">查看并激活观澜镜</button>':'<p class="small-note">第三关首次通过获得独立法宝观澜镜、3000灵石与120灵髓。重访不重复发首通奖励。</p>'}<p class="small-note">完成三试后可在修行页准备结丹。原有地图与挂机始终可用。</p>${state.level===20?'<button class="primary large" data-ui="corePrepare">查看结丹准备</button>':''}</section>`;}

function finaleView(){return `<section class="finale-panel"><span class="volume">炼气卷 · 终章</span><h2>问山三试</h2><p>圆满即可赴试，不要求极境。三关过后，这一卷才算写下自己的答案。</p>${state.battle&&['finale','extreme'].includes(state.battle.type)?battleView():state.lastBattle&&['finale','extreme'].includes(state.lastBattle.type)?battleReport(state.lastBattle.type,state.lastBattle.id):''}<div class="trial-stages">${[1,2,3].map(n=>`<article><div><h3>${trialEnemy('finale',n).name}</h3><p>${n===1?'照见来时路':n===2?'在风雷中稳住道心':'与自己的道影一战'}</p></div>${button(state.finale>=n?'重访':'自动赴试','finaleTrial',`data-stage="${n}"`,!!state.battle||state.level<10||n>state.finale+1,'secondary')}</article>`).join('')}</div>${state.finale===3?'<p class="chapter-complete">炼气卷已完成 · 首通所得神器「问山印」已入袋</p>':'<p class="small-note">最终首通奖励：神器问山印、灵石与灵髓。筑基仙路已开放，可从修行页选择道基突破。</p>'}<details class="quiet-details"><summary>可选 · 极境加试</summary><p>已经成就极境的修士，可在三试后挑战「天外一念」。不影响普通圆满结局。</p>${button(state.extremeTrial?'重访天外一念':'自动挑战天外一念','extremeTrial','',!!state.battle||!state.extreme||state.finale<3,'secondary')}<p class="small-note">${state.extremeTrial?'已获称号「极境问山人」':'首次通过：1000灵石、20灵髓、称号「极境问山人」'}</p></details></section>`;}
function farmPlanText(){const p=state.farmPlan||{mode:'unlimited'};return p.mode==='rounds'?`还剩 ${p.remainingRounds} 轮`:p.mode==='duration'?`还剩 ${time(p.remainingSeconds)}`:'持续挂机';}
function techPassive(t,n){return [['gain','单次修为'],['speed','修炼减时'],['atk','攻伐'],['def','护体'],['hp','气血']].filter(([k])=>t[k]).map(([k,label])=>label+' +'+fmt(t[k]*n*100)+'%').join(' · ');}
function techCard(t){const info=techStudyInfo(state,t.id),lv=info.level,cp=combatProfile({...state,techniques:{...state.techniques,[t.id]:Math.max(1,lv)},combatLoadout:{main:t.id,aux:null}}),role=state.combatLoadout?.main===t.id?'当前主修':state.combatLoadout?.aux===t.id?'当前辅修':'',reasons=info.max?[]:[...info.unmet,...info.missing],disabled=blocked||!info.available;return `<article class="technique-entry" id="technique-${t.id}"><div class="technique-heading"><div><span class="technique-source">${(t.gate||1)>=21?'金丹初期':(t.gate||1)>=11?'筑基':'炼气'} · ${info.source}</span><h3>${t.name}</h3></div><span class="technique-level">${lv?lv+' / '+t.max+' 重':'未学'}${role?'<small>'+role+'</small>':''}</span></div><p class="technique-passive"><b>每重被动</b>${techPassive(t,1)}${t.id==='cycle'?' · 闪避步成功率 +2个百分点（基础闪避步最高70%）':''}</p>${lv?`<p class="technique-current">已生效：${techPassive(t,lv)}${t.id==='cycle'?' · 闪避步成功率 +'+fmt(lv*2)+'个百分点（总计有上限）':''}</p>`:''}<div class="technique-study"><div><span>${info.max?'此功法已圆满':lv?'升至第 '+(lv+1)+' 重':'学会第一重'}</span><b>${info.max?'被动加成永久保留':cost(info.price)}</b>${!info.max&&t.source==='merchant'&&shopDiscount(state)?'<small>已计入当前宗门九折</small>':''}</div>${button(info.max?'已圆满':lv?'升级':'学习','learn',`data-id="${t.id}" data-level="${lv}" data-price="${Object.values(info.price)[0]}" data-run-id="${esc(state.runId)}"`,disabled,'primary')}</div>${reasons.length?'<p class="technique-requirements">'+reasons.join('<br>')+'</p>':''}${!info.max&&info.unmet.length&&t.source!=='merchant'?`<button class="text" data-tech-sect="${t.source}" data-tech-trial="${t.trial||0}">${state.sect!==t.source?'查看宗门':'查看职位与试炼'}</button>`:''}<details class="technique-combat" data-detail="technique:${t.id}"><summary>主修招式与辅修效果</summary><p><b>作主修 · ${cp.skill}</b><br>${cp.cost} 真气 · ${cp.style==='blade'?'高倍率攻伐':cp.style==='stone'?'回血与护盾':'低耗破防'}，强度随本功法重数成长。</p><p><b>作辅修</b><br>${loadoutDescription(t.id)}</p><p class="small-note">已学功法可任意配入一个战斗栏位。所有已学被动一直叠加，主辅不可重复。${t.id==='cycle'?'无论是否配入战斗栏位，小周天诀每重另加2个百分点闪避步成功率。':''}</p>${lv?'<button class="secondary" data-ui="techLoadout">配置主修与辅修</button>':''}</details></article>`;}
function refreshTechniqueControls(){for(const el of document.querySelectorAll('#root [data-action="learn"]'))el.disabled=blocked||!techStudyInfo(state,el.dataset.id)?.available;const submit=$('#tech-loadout-form [type="submit"]');if(submit)submit.disabled=blocked||!!state.battle||techDraft?.main===techDraft?.aux;const notice=$('#tech-battle-notice');if(notice)notice.hidden=!state.battle;}
function resetTechDraft(){techDraft={runId:state.runId,main:state.combatLoadout?.main||'sect',aux:state.combatLoadout?.aux||''};}
function comboLibrary(){const current=techniqueCombo(state);return `<details class="combo-library" data-detail="technique-combos"><summary>功法套组 · ${current?current.name:'当前未触发'}</summary><p class="small-note">主修与辅修按下方顺序搭配，习得第一重即可触发；一次仅生效一组。预览不会改变配法，仍需保存确认。已有被动不受影响。</p>${TECHNIQUE_COMBOS.map(group=>`<section class="combo-family"><div class="resonance-title"><h3>${group.name}</h3><span>${group.style}</span></div>${group.recipes.map(r=>{const main=TECHNIQUES.find(t=>t.id===r.main),aux=TECHNIQUES.find(t=>t.id===r.aux),ready=state.techniques[r.main]>0&&state.techniques[r.aux]>0,active=current?.id===r.id;return `<article class="combo-recipe ${active?'is-active':''}" data-recipe="${r.id}"><span class="combo-phase">${r.chapter==='qi'?'炼气搭配':'筑基搭配'} · ${active?'生效中':ready?'已学齐，可配置':'尚未学齐'}</span><p><b>主</b> ${main.name}<br><b>辅</b> ${aux.name}</p><p class="combo-effect">${r.text}</p>${[main,aux].filter(t=>!state.techniques[t.id]).map(t=>`<button class="text" data-tech-id="${t.id}">查看${t.name}的研习条件</button>`).join('')}<button class="secondary large" data-combo-recipe="${r.id}" ${!ready?'disabled':''}>${active?'查看当前配法':'预览这套配法'}</button></article>`;}).join('')}</section>`).join('')}<p class="small-note">减时和增修与功法、法宝、宗门、道基、装备加成相加。间隔最短10秒，触及下限后额外减时不再缩短；单次增修仍有效。</p></details>`;}
function previewCombo(id){const recipe=TECHNIQUE_COMBOS.flatMap(g=>g.recipes).find(r=>r.id===id);if(!recipe||!state.techniques[recipe.main]||!state.techniques[recipe.aux])return toast('先学会这套组合所需的两门功法');if($('#dialog').open)close();if(tab!=='techniques')go('techniques');techEditor=true;techDraft={runId:state.runId,main:recipe.main,aux:recipe.aux};render();$('#tech-loadout-form')?.scrollIntoView({block:'center',behavior:scrollBehavior()});}
function treasureSourceAction(t){const source=TREASURES[t.baseId];return source.area?`<button class="text" data-source-area="${source.area}">${source.source}</button>`:`<button class="text" data-source-route="${t.baseId==='bell'?'tower':t.baseId==='mountainSeal'?'finale':'foundation'}">${source.source}</button>`;}
function resonanceCards(){return treasureResonances(state).map(f=>`<section class="resonance-family" data-resonance="${f.id}"><div class="resonance-title"><div><h3>${f.name}</h3><span>${f.style}</span></div><b>${f.count} / 3 已激活</b></div><p class="resonance-next">${f.count===3?'两档共鸣均已生效':'再激活 '+((f.count<2?2:3)-f.count)+' 件，开启'+(f.count<2?'二件':'三件')+'共鸣'}${f.members.some(t=>t.known&&!t.active)?' · 有待激活藏品':''}</p><div class="resonance-tiers">${f.tiers.map(t=>`<p class="${t.active?'set-active':'muted'}"><b>${t.count}件 · ${t.active?'生效':'未达成'}</b>${t.text}</p>`).join('')}</div><div class="resonance-members">${f.members.map(t=>`<div class="resonance-member"><div><button class="text treasure-name" data-gear="${t.id}">${t.name}</button><span>${treasureProgress(state,t.id).status}</span><small class="treasure-progress">${treasureProgress(state,t.id).detail}</small>${!t.active?treasureSourceAction(t):''}</div>${button(t.active?'已激活':t.known?'激活':'未解锁','activateTreasure',`data-id="${t.id}" data-battle-lock data-unavailable="${t.active||!t.known}"`,t.active||!t.known||!!state.battle,'small '+(t.known&&!t.active?'primary':'secondary'))}</div>`).join('')}</div></section>`).join('');}
function techniqueLoadout(){if(!techDraft||techDraft.runId!==state.runId)resetTechDraft();const learned=TECHNIQUES.filter(t=>state.techniques[t.id]),draft=techDraft,valid=(draft.main==='sect'||state.techniques[draft.main])&&(!draft.aux||state.techniques[draft.aux])&&draft.main!==draft.aux,previewState=valid?{...state,combatLoadout:{main:draft.main,aux:draft.aux||null}}:state,cp=combatProfile(previewState),rate=cultivation(previewState),currentRate=cultivation(state),currentCp=combatProfile(state);return `<form id="tech-loadout-form"><label>主修<select id="tech-loadout-main"><option value="sect" ${draft.main==='sect'?'selected':''}>随当前宗门</option>${learned.map(t=>`<option value="${t.id}" ${draft.main===t.id?'selected':''}>${t.name} · ${state.techniques[t.id]}重</option>`).join('')}</select></label><label>辅修<select id="tech-loadout-aux"><option value="">暂不辅修</option>${learned.map(t=>`<option value="${t.id}" ${draft.aux===t.id?'selected':''}>${t.name} · ${state.techniques[t.id]}重</option>`).join('')}</select></label><div class="tech-loadout-preview"><b>预览 · ${cp.skill}</b><p>${cp.cost} 真气 · 攻伐倍率 ${Number((cp.scale+cp.setBurst).toFixed(2)).toLocaleString('zh-CN')} · 忽略护体 ${fmt(cp.pierce*100)}%${cp.heal+cp.setHeal?' · 技能回复'+fmt((cp.heal+cp.setHeal)*100)+'%气血':''}${cp.shield?' · 护盾为'+fmt(cp.shield*100)+'%护体':''}</p>${draft.aux?'<p>辅修：'+loadoutDescription(draft.aux)+'</p>':''}<details class="loadout-changes"><summary>战斗数值变化 · 当前与预览</summary>${[['技能真气',currentCp.cost,cp.cost,''],['攻伐倍率',currentCp.scale+currentCp.setBurst,cp.scale+cp.setBurst,'倍'],['忽略护体',currentCp.pierce*100,cp.pierce*100,'%'],['技能回血',(currentCp.heal+currentCp.setHeal)*100,(cp.heal+cp.setHeal)*100,'%气血'],['守势回血',currentCp.guardHeal*100,cp.guardHeal*100,'%气血'],['技能护盾',currentCp.shield*100,cp.shield*100,'%护体'],['闪避步',currentCp.dodge*100,cp.dodge*100,'%']].filter(([,a,b])=>Math.abs(a-b)>1e-8).map(([name,a,b,unit])=>`<p>${name}：${Number(a.toFixed(2))}${unit} → ${Number(b.toFixed(2))}${unit}</p>`).join('')||'<p>战斗数值与当前配法相同</p>'}</details><p class="combo-preview-state">${cp.combo?'套组 · '+cp.combo.name+'：'+cp.combo.text:'未触发功法套组'}</p><p>修炼预览：每 ${fmt(rate.interval)} 秒 +${fmt(rate.gain)} 修为<br>约 ${fmt(currentRate.perMinute)} → ${fmt(rate.perMinute)} 修为 / 分钟</p><small>含道基、法宝与套装。保存后生效，已学被动始终叠加；吐纳套组另计。间隔最低10秒。</small></div><p id="tech-loadout-error" class="warning" role="status">${!valid?'主辅不可重复，且只能选择已学功法。':''}</p><div class="button-pair"><button type="button" class="secondary" data-ui="techCancelLoadout">取消更改</button><button type="submit" class="primary" ${!valid||state.battle||blocked?'disabled':''}>保存配法</button></div></form>`;}
function techniquesView(){const learned=TECHNIQUES.filter(t=>state.techniques[t.id]),c=cultivation(state),cp=combatProfile(state),main=TECHNIQUES.find(t=>t.id===state.combatLoadout?.main),aux=TECHNIQUES.find(t=>t.id===state.combatLoadout?.aux),entries=TECHNIQUES.filter(t=>(techStatus==='all'||techStatus==='learned'&&state.techniques[t.id]||techStatus==='unlearned'&&!state.techniques[t.id])&&(techSource==='all'||t.source===techSource)&&(techChapter==='all'||realmChapter(t.gate||1)===techChapter)).sort((a,b)=>(a.gate||1)-(b.gate||1)||(a.source==='merchant'?-1:1)-(b.source==='merchant'?-1:1)||(a.trial||0)-(b.trial||0));return `<section class="techniques-page"><div class="techniques-topline">${techReturn?`<button class="text" data-ui="techReturn">返回${{home:'修行',map:'山河',sect:'宗门',market:'坊市',bag:'行囊',profile:'人物'}[techReturn]||'修行'}</button>`:'<span>藏经总览</span>'}<button class="text" data-go="market">坊市</button></div>${head('功法',`已学 ${learned.length} / ${TECHNIQUES.length} 门 · 学习、升级、配法都在这里`)}<div class="technique-wallet"><span>灵石 <b>${fmt(state.stones)}</b></span><span>宗门贡献 <b>${fmt(state.contribution)}</b></span></div><p class="techniques-rule">当前每 ${fmt(c.interval)} 秒获得 <b>${fmt(c.gain)}</b> 修为，约 <b>${fmt(c.perMinute)}</b> / 分钟。<br>所有已学被动同时生效，无需装备。</p><details class="technique-rule-details" data-detail="technique-rules"><summary>叠加与配法规则</summary><p>功法被动按已学重数相加；主辅决定招式和当前套组。修炼间隔最短10秒，额外增修仍有效。下方套组只是预览，保存配法后才会切换。</p><button class="text" data-ui="bonuses">查看全部修炼加成</button></details>${sceneBanner('scroll-library','山间藏经阁的书卷与静院')}${comboLibrary()}<section class="techniques-loadout"><div class="technique-heading"><h3>主辅配法</h3><button class="text" data-ui="presets">配装预设</button><button class="text" data-ui="techLoadout" aria-expanded="${techEditor}">${techEditor?'收起配置':'调整配法'}</button></div><div class="technique-slots"><div><span>主修</span><b>${main?.name||'随当前宗门'}</b></div><div><span>辅修</span><b>${aux?.name||'暂未配置'}</b></div></div><p class="saved-combo"><b>${cp.combo?'当前套组 · '+cp.combo.name:'当前未触发功法套组'}</b>${cp.combo?'<span>'+cp.combo.text+'</span>':'<span>在上方套组中查看搭配，预览后保存配法</span>'}</p>${!techEditor?`<p>${cp.skill} · ${cp.cost} 真气</p>`:techniqueLoadout()}</section><p id="tech-battle-notice" class="warning technique-battle-notice" ${state.battle?'':'hidden'}>斗法进行中，可查阅功法；结束后恢复学习与配法。<button class="text" data-ui="battleLocation">回到当前战斗</button></p><div class="technique-status" aria-label="功法学习状态">${[['all','全部'],['learned','已学'],['unlearned','未学']].map(([id,label])=>`<button data-tech-status="${id}" aria-pressed="${techStatus===id}" class="${techStatus===id?'active':''}">${label}</button>`).join('')}</div><div class="technique-filters"><label>获取来源<select id="tech-source">${[['all','全部来源'],['merchant','坊市'],...SECTS.map(x=>[x.id,x.name])].map(([id,label])=>`<option value="${id}" ${techSource===id?'selected':''}>${label}</option>`).join('')}</select></label><label>境界篇章<select id="tech-chapter">${[['all','全部篇章'],['qi','炼气'],['foundation','筑基'],['core','金丹初期']].map(([id,label])=>`<option value="${id}" ${techChapter===id?'selected':''}>${label}</option>`).join('')}</select></label></div><p class="techniques-count">当前显示 ${entries.length} 门</p><div class="techniques-list">${entries.map(techCard).join('')||'<div class="techniques-empty"><p>这个筛选下暂无功法</p><button class="secondary" data-ui="techReset">查看全部功法</button></div>'}</div></section>`;}
function openTechniques({source='all',chapter='all',id=null,editor=false}={}){if($('#dialog').open)close();techSource=source;techChapter=chapter;techStatus='all';if(editor){techEditor=true;resetTechDraft();}go('techniques');if(id){const n=$('#technique-'+id);if(n){n.classList.add('tutorial-target');n.scrollIntoView({block:'center',behavior:scrollBehavior()});}}}

function sectNav(){return `<div class="sect-tabs" aria-label="宗门事务">${[['overview','山门概览'],['techniques','宗门功法'],['missions','宗门委托'],['trials','晋升与试炼']].map(([id,n])=>`<button data-sect-pane="${id}" class="${sectPane===id?'active':''}" aria-pressed="${sectPane===id}">${n}</button>`).join('')}</div>`;}
function sectChoices(){return `<div class="sect-options">${SECTS.map(x=>`<article class="sect-option" data-sect="${x.id}">${sceneBanner('sect-'+x.id,x.name+'的水墨山门风景')}<div class="sect-option-heading"><h3>${x.name}</h3><span>${x.style==='气修'?'术修':x.style}</span></div><p>${x.desc}</p><p class="sect-bonus">入门加成：${x.bonus}</p><p class="small-note">本门功法：${TECHNIQUES.filter(t=>t.source===x.id).map(t=>t.name).join('、')}</p>${button(state.sect===x.id?'当前宗门':state.sect?'改换宗门 · 200 灵石':'拜入此宗 · 免费','join',`data-id="${x.id}"`,state.sect===x.id||!!state.battle||!!state.sect&&state.stones<200,'secondary large')}</article>`).join('')}</div>`;}
function rankRequirements(){const r=rank(state),next=RANKS[r+1];if(!next)return '<div class="rank-progress"><h3>已至当前最高职位 · 传法长老</h3><p>仍可研习功法、完成委托和重访试炼。</p></div>';return `<section class="rank-progress"><div class="rank-progress-title"><h3>下一职位 · ${next.name}</h3><span>达标自动晋升</span></div><div class="rank-requirements"><p><span>境界要求</span><b>${stageName(next.level)}</b><small class="${state.level>=next.level?'set-active':'warning'}">${state.level>=next.level?'已达成':'还需提升 '+(next.level-state.level)+' 层'}</small></p><p><span>声望要求</span><b>${fmt(state.sectRep)} / ${next.rep}</b><small class="${state.sectRep>=next.rep?'set-active':'warning'}">${state.sectRep>=next.rep?'已达成':'还差 '+(next.rep-state.sectRep)+' 声望'}</small></p></div>${bar(Math.min(state.sectRep,next.rep),next.rep,'下一职位声望')}<p class="small-note">境界和声望都达标即晋升，无需额外消耗。职位达成后，再挑战对应试炼解锁特权。</p><div class="button-pair"><button class="secondary" data-go="home">去修炼</button><button class="secondary" data-sect-pane="missions">做委托攒声望</button></div></section>`;}
function sectView(){const current=SECTS.find(x=>x.id===state.sect);if(!current)return `<section class="sect-page">${head('选择山门','首次拜入免费，已学功法会一直保留')}<p class="sect-intro">每座山门都有自己的功法与战斗流派。先看加成，再选喜欢的道路。</p>${sectChoices()}</section>`;return `<section class="sect-page" data-sect="${current.id}"><header class="sect-identity"><span class="volume">当前山门</span><div class="sect-title-row"><h2>${current.name}</h2><span class="sect-rank">${RANKS[rank(state)].name}</span></div><p>${current.desc} · ${current.style==='气修'?'术修':current.style}</p><div class="sect-metrics"><div><span>可用贡献</span><strong>${compact(state.contribution)}</strong><small>研习宗门功法时消耗</small></div><div><span>累计声望</span><strong>${compact(state.sectRep)}</strong><small>用于晋升，不随研习扣除</small></div></div></header>${sectNav()}${sectPane==='specialty'?specialtyView():sectPane==='overview'?`${sceneBanner('sect-'+current.id,current.name+'的水墨山门风景')}<section class="sect-benefits"><h3>在此修行</h3><p>${current.bonus}</p><button class="specialty-entry secondary large" data-sect-pane="specialty">宗门专修 · ${specialization(state)?.name||'查看两条道路'}</button><button class="secondary large" data-ui="loadout">配置主修与辅修</button></section>${rankRequirements()}<details class="sect-switch"><summary>更换宗门</summary><p>改换需要 200 灵石。功法、贡献、声望和各门已过试炼都会保留；宗门基础加成随新门派变化。</p>${sectChoices()}</details>`:sectPane==='missions'?missionView():sectPane==='techniques'?`<div class="sect-section-intro"><h3>藏经阁</h3><p>贡献用于研习。所有学过的被动加成都叠加，主辅决定战斗招式及当前功法套组，已学被动始终叠加。</p><button class="secondary" data-ui="loadout">配置主修与辅修</button></div><button class="primary large" data-tech-source="${current.id}">查看并研习本门功法</button>`:sectTrialView()}</section>`;}
function missionView(){const m=missionStatus(state);return `<div class="sect-section-intro"><h3>完成委托，积累声望</h3><p>一次接取一项。奖励同时增加贡献与声望。</p></div>${m?`<section class="sect-mission"><h3>${m.name}</h3><p>${m.desc}</p><div class="progress-label"><span>当前进度</span><b>${Math.min(m.need,m.progress)} / ${m.need}</b></div>${bar(Math.min(m.need,m.progress),m.need,'委托进度')}<p class="sect-reward">奖励：贡献 +${m.contribution} · 声望 +${m.contribution} · 灵石 +${m.stones}</p><div class="button-pair">${button('完成委托','claimMission','',!m.ready||!!state.battle,'primary')}${button('放下委托','cancelMission','',!!state.battle,'secondary')}</div></section>`:`<div class="sect-missions">${[['hunt','巡守山道','赢得3场区域战斗（挂机不计）',40,60],['farm','山门采办','完成10轮挂机',30,40],['herbs','药圃补给','交付10株灵草',25,30]].map(([id,n,d,rep,stones])=>`<article class="sect-mission"><h3>${n}</h3><p>${d}</p><p class="sect-reward">贡献 +${rep} · 声望 +${rep} · 灵石 +${stones}</p>${button('接取委托','acceptMission',`data-kind="${id}"`,!!state.battle,'secondary large')}</article>`).join('')}</div>`}<section class="sect-donation"><h3>日常供奉</h3><p>消耗 5 灵草、20 灵石，获得 15 贡献与 15 声望。</p>${button('供奉一次','donate','',!afford(state,{herbs:5,stones:20})||!!state.battle,'secondary large')}<p class="small-note">入门后每 2 分钟另得 1 贡献、1 声望，离线也按 8 小时上限结算。</p></section>`;}
function sectTrialView(){const won=state.sectTrials?.[state.sect]||0,r=rank(state);return `<button class="specialty-entry secondary large" data-sect-pane="specialty">宗门专修与专修试炼</button>${rankRequirements()}${state.battle?.type==='sect'?battleView():state.lastBattle?.type==='sect'?battleReport('sect',state.lastBattle.id):''}<div class="sect-section-intro"><h3>职位试炼</h3><p>职位达标后，依次通关。解锁的特权只需首通一次。</p></div>${won>=2?`<section class="sect-donation"><h3>静修台 · ${state.retreat?'已启用':'未启用'}</h3><p>启用后单次修为 +${won>=5?20:10}%，与功法和法宝加成叠加。</p>${button(state.retreat?'离开静修台':'启用静修台','retreat','',!!state.battle,'primary large')}</section>`:''}<div class="sect-trials">${[[1,'内门试炼','解锁本门秘传功法'],[2,'亲传试炼','开放静修台，修为获取 +10%'],[3,'执事试炼','坊市商品与普通功法九折'],[4,'护法试炼','解锁本门筑基秘传'],[5,'长老试炼','静修台额外增加10%单次修为']].map(([n,title,reward])=>{const req=RANKS[n],reason=state.battle?'先完成当前斗法':r<n?`需要${req.name}：${stageName(req.level)}、${req.rep}声望`:n>won+1?'先通过上一阶试炼':won>=n?'已首通 · 可以重访':'条件已满足';return `<article class="sect-trial"><div class="sect-trial-heading"><h3>${title}</h3><span>${won>=n?'已通关':r>=n&&n<=won+1?'可挑战':'未解锁'}</span></div><p>${reward}</p><p class="${r<n||n>won+1?'warning':'small-note'}">${reason}</p>${button(won>=n?'重访试炼':'自动挑战','sectTrial',`data-tier="${n}"`,!!state.battle||r<n||n>won+1,'secondary large')}</article>`;}).join('')}</div>`;}
function gearStats(g){return [['攻伐',g.atk],['护体',g.def],['气血',g.hp]].filter(([,v])=>v).map(([k,v])=>`${k} +${v}`).join(' · ');}
function gearCard(id,shop=false){const g=itemInfo(state,id),owned=state.inventory[id]||0,equipped=state.equipment[g.slot]===id,gate=g.gate||(g.quality==='epic'?6:g.quality==='rare'?2:1);return `<article class="gear-card quality-${g.quality}"><div><span class="quality-label">${QUALITY[g.quality]} · ${SLOTS[g.slot]}</span><h3>${g.name} ${!shop&&owned>1?`<small>×${owned}</small>`:''}</h3><p>${gearStats(g)}</p>${g.set?`<small>${SETS[g.set].name}套装 · ${setCounts(state)[g.set]||0} / 3 件装备中</small>`:''}${g.passive?`<strong class="artifact-effect">${g.passive}</strong>`:''}${shop?`<small>${shopPrice(state,id)} 灵石${state.level<gate?` · ${stageName(gate)}可购`:owned?' · 已有 '+owned+' 件':''}</small>`:''}</div><div class="gear-card-actions"><button class="text" data-gear="${id}">属性比较</button>${button(shop?'购买':equipped?'已装备':'装备',shop?'buy':'equip',`data-id="${id}" ${shop?'data-price="'+shopPrice(state,id)+'"':''}`,shop?!!state.battle||state.stones<shopPrice(state,id)||state.level<gate:equipped,'small '+(equipped?'secondary':'primary'))}</div></article>`;}
function gearIcon(slot,cls=''){return `<img class="equipment-icon ${cls}" src="equipment/${slot}-160.webp" width="160" height="160" decoding="async" loading="lazy" alt="">`;}
function equipmentGrid(){return `<section class="equipment-grid" aria-label="六格装备栏">${Object.entries(SLOTS).map(([slot,name])=>{const id=state.equipment[slot],g=itemInfo(state,id),lv=state.enhance[slot]||0;return `<button class="equipment-slot ${g?'quality-'+g.quality:'empty-slot'} ${selectedSlot===slot?'selected-slot':''}" data-equipment-slot="${slot}" aria-label="${name}，${g?g.name:'空栏位'}，强化 ${lv}，查看详情"><span class="slot-heading"><span>${name}</span><b>+${lv}</b></span>${gearIcon(slot)}<strong>${g?g.name:'未装备'}</strong><small>${g?QUALITY[g.quality]:'点击选择装备'}</small>${g?.affixLabel?`<small class="affix-label">${g.affixLabel}</small>`:''}${g?.set?`<span class="slot-badge">${SETS[g.set].name}套</span>`:g?.quality==='artifact'?'<span class="slot-badge">神器</span>':''}</button>`;}).join('')}</section>`;}
function itemScoreDelta(id){if(itemInfo(state,id)?.treasure)return 0;if(scoreCache.has(id))return scoreCache.get(id);const g=itemInfo(state,id);if(currentBagScore===null)currentBagScore=equipmentScore(state);const delta=equipmentScore({...state,equipment:{...state.equipment,[g.slot]:id}})-currentBagScore;scoreCache.set(id,delta);return delta;}
function inventoryTile(id){const g=itemInfo(state,id);if(g.treasure){const t=treasureInfo(state,g.baseId);return `<button class="inventory-tile quality-artifact" data-gear="${id}"><span class="tile-icon">${gearIcon('charm')}${g.locked?'<span class="locked-badge">锁</span>':''}</span><strong>${g.name}</strong><span>独立法宝</span><span class="upgrade-indicator better">${t.active?'已激活 · 加成生效':'可激活 · 无需穿戴'}</span><small>藏品 ${state.inventory[id]} 件 · 点此管理</small></button>`;}const equipped=state.equipment[g.slot]===id,score=itemScoreDelta(id);return `<button class="inventory-tile quality-${g.quality}" data-gear="${id}" aria-label="${g.displayName}，${equipped?'已穿戴':score>0?'评分提升':'查看比较'}"><span class="tile-icon">${gearIcon(g.slot)}${equipped?'<span class="worn-badge">穿戴中</span>':''}${g.locked?'<span class="locked-badge">锁</span>':''}</span><strong>${g.name}</strong><span>${QUALITY[g.quality]} · ${SLOTS[g.slot]}</span>${g.affixLabel?`<small class="affix-label">${g.affixLabel}</small>`:''}<span class="upgrade-indicator ${score>0?'better':score<0?'lower':''}">${equipped?'当前穿戴':score>0?'评分提升 +'+score:score<0?'评分较低 '+score:'评分相当'}</span><small>${state.inventory[id]>1?'持有 '+state.inventory[id]+' 件':'点此比较'}</small></button>`;}
function bagView(){const st=stats(state),items=Object.keys(state.inventory).filter(id=>state.inventory[id]>0&&(bagFilter==='all'||bagFilter==='treasures'?bagFilter==='all'||itemInfo(state,id).treasure:!itemInfo(state,id).treasure&&itemInfo(state,id).slot===bagFilter)&&(bagQuality==='all'||itemInfo(state,id).quality===bagQuality)).sort((a,b)=>itemScoreDelta(b)-itemScoreDelta(a));return `${head('行囊','装备、分解与掉落来源')}<div class="bag-command-row"><button class="primary" data-ui="dismantleHub">分解装备</button><button class="secondary" data-ui="gearHunt">去刷装备</button><button class="secondary" data-ui="recommendPreview">推荐配装</button></div>${state.dismantleUndo?`<button class="undo-banner secondary large" data-action="undoDismantle">撤销上次分解 · 归还 ${state.dismantleUndo.ore} 玄铁</button>`:''}<div class="stat-strip"><span>攻伐 <b>${st.atk}</b></span><span>护体 <b>${st.def}</b></span><span>气血 <b>${state.hp}/${st.hp}</b></span></div>${equipmentGrid()}<div class="gear-utility"><button class="preset-entry secondary" data-ui="presets">配装预设</button><button class="secondary" data-ui="crafting">定向炼器</button></div>${treasureSummary()}<p class="equipment-note">强化留在栏位，换装自动继承 · 已穿戴 ${Object.values(state.equipment).filter(Boolean).length} / 6</p><details class="set-details" data-detail="equipment-rules"><summary>装备加成、套装与评分说明</summary><div class="gear-help-links"><button class="text" data-ui="recommendRules">评分规则</button><button class="text attribute-link" data-ui="stats">完整属性与加成来源</button></div>${Object.entries(SETS).map(([id,s])=>`<p><b>${s.name} · 已装备 ${setCounts(state)[id]||0} / 3 件</b><br><span class="${(setCounts(state)[id]||0)>=2?'set-active':''}">${s.two}</span><br><span class="${(setCounts(state)[id]||0)>=3?'set-active':''}">${s.three}</span></p>`).join('')}<p>一线天为兵器神器，穿戴时攻伐额外 +18%。山河钟与问山印在独立法宝录激活后生效。</p></details>${bagCount(state)>=200?'<p class="bag-warning">行囊已超过200件整理线，全部掉落仍会保留。建议锁好珍品后整理。</p>':''}<div class="inventory-heading"><h2>随身行囊 · ${bagCount(state)} 件</h2><span>点物品比较与替换</span></div><div class="inventory-filters" role="group" aria-label="筛选装备">${[['all','全部'],...Object.entries(SLOTS),['treasures','法宝']].map(([id,n])=>`<button data-bag-filter="${id}" aria-pressed="${bagFilter===id}" class="${bagFilter===id?'selected':''}">${n}</button>`).join('')}</div><div class="inventory-tools"><label>品阶 <select id="quality-filter">${[['all','全部品阶'],...Object.entries(QUALITY)].map(([id,n])=>`<option value="${id}" ${bagQuality===id?'selected':''}>${n}</option>`).join('')}</select></label><button class="text" data-ui="dismantleDuplicates">分解所有未穿戴</button></div>${state.dismantleUndo?`<button class="text undo-dismantle" data-action="undoDismantle">撤销上次分解 · 归还 ${state.dismantleUndo.ore} 玄铁</button>`:''}<div class="inventory-grid">${items.slice(0,bagVisible).map(inventoryTile).join('')||'<p class="empty-inventory">此类装备暂未获得<br>可前往坊市选购</p>'}</div>${items.length>bagVisible?`<button class="secondary large inventory-more" data-ui="moreGear">再看 ${Math.min(24,items.length-bagVisible)} 种装备<small>已显示 ${Math.min(bagVisible,items.length)} / ${items.length} 种，全部物品均已保留</small></button>`:''}<section class="healing"><h3>调息与炼丹</h3><p>回春丹 ${state.pills} 枚，战斗中回复 50% 最大气血。</p><div class="button-pair">${button('炼丹 ×3','craftPill','',!afford(state,{herbs:6,stones:10}),'secondary')}${button('调息回满','rest','',state.herbs<2||state.hp>=st.hp,'secondary')}</div><p class="small-note">炼丹：6 灵草、10 灵石 · 调息：2 灵草<br>脱战后每 10 秒自然回复 5% 气血。</p></section>`;}
function gearSignature(){return JSON.stringify([state.runId,state.level,state.extreme,state.sect,state.techniques,state.combatLoadout,state.equipment,state.enhance,state.inventory,state.lockedItems,state.activatedTreasures,state.foundationType,state.foundationPath,state.foundationExtreme,state.stones,state.ore,state.jade,state.retreat,state.sectTrials,state.cleared,state.tower,state.finale,state.foundationFinale,state.presets,state.areaTrials,state.specializations,state.specialtyTrials,!!state.battle,!!state.towerRun?.active]);}
function refreshOpenGear(force=false){if(!gearDetail||!$('#dialog').open)return;if(!force&&(gearSignature()===gearRenderSignature||document.activeElement?.id==='dismantle-count'))return;const scroll=$('#dialog').scrollTop,q=$('#dismantle-count')?.value;showGearDetail(gearDetail.id,gearDetail.slot,true);if(q!==undefined&&$('#dismantle-count'))$('#dismantle-count').value=q;$('#dialog').scrollTop=scroll;}
function signed(n){return n>0?'+'+fmt(n):fmt(n);}
function enhancementEffect(slot){return {weapon:'每级攻伐 +4',robe:'每级护体 +2、气血 +8',charm:'每级气血 +12、攻伐 +1',head:'每级护体 +1、气血 +2',boots:'每级护体 +1、气血 +2',belt:'每级气血 +6'}[slot];}
function showGearDetail(id=null,slot=null,refresh=false){const g=itemInfo(state,id);if(g?.treasure)return showTreasureDetail(id,refresh);slot=g?.slot||slot;if(!SLOTS[slot])return;selectedSlot=slot;gearDetail={id:g?id:null,slot};const current=state.equipment[slot],lv=state.enhance[slot]||0,limit=enhancementLimit(state),c=enhancementCost(state,slot),comparison=g?gearComparison(state,id):null,equipped=id===current,owned=!!state.inventory[id],alternatives=Object.keys(state.inventory).filter(x=>!itemInfo(state,x).treasure&&itemInfo(state,x).slot===slot&&state.inventory[x]>0&&x!==id);const delta=String(comparison?.delta.power||0);if(!refresh)render();gearRenderSignature=gearSignature();modal(`<div class="gear-detail ${g?'quality-'+g.quality:''}">${gearFeedback?`<div class="detail-feedback" role="status">${gearFeedback}</div>`:''}<div class="detail-title">${gearIcon(slot)}<div><span class="quality-label">${g?QUALITY[g.quality]+' · ':''}${SLOTS[slot]}</span><h2>${g?g.name:'空栏位'}</h2>${g?.affixLabel?`<span class="affix-label">${g.affixLabel}</span>`:''}<span class="enhance-label">栏位强化 +${lv} · 换装保留</span></div></div>${g?dismantleItemControls(id):''}${g?`<div class="item-base"><b>装备属性（已含词条）</b><p>${gearStats(g)}</p></div><div class="compare-heading"><b>${equipped?'当前穿戴效果':'换装后人物属性'}</b><span>${equipped?'已计入所有加成':`对比 ${current?itemInfo(state,current).name:'空栏位'}`}</span></div><div class="comparison-table"><div class="compare-row table-labels"><span>属性</span><span>当前</span><span>换上后</span><span>变化</span></div>${[['atk','攻伐'],['def','护体'],['hp','气血上限'],['power','战力']].map(([k,n])=>`<div class="compare-row"><span>${n}</span><span>${comparison.current[k]}</span><b>${comparison.next[k]}</b><strong class="${comparison.delta[k]>0?'delta-positive':comparison.delta[k]<0?'delta-negative':'delta-neutral'}">${signed(comparison.delta[k])}</strong></div>`).join('')}</div><p class="small-note">比较包含功法、部位强化、套装触发与神器加成。</p>${owned?button(g.locked?'已锁定 · 点击解锁':'锁定这组装备','lockItem',`data-id="${id}"`,!!combatBusy(),'secondary small'):''}<p class="small-note">相同词条与数值合并成一组；锁定保护整组不被分解。</p>${g.set?`<div class="detail-set"><b>${SETS[g.set].name}套装</b><p>当前 ${comparison.currentSets[g.set]||0} 件 · 换上后 ${comparison.nextSets[g.set]||0} 件</p><p class="${comparison.nextSets[g.set]>=2?'set-active':''}">${SETS[g.set].two}</p><p class="${comparison.nextSets[g.set]>=3?'set-active':''}">${SETS[g.set].three}</p></div>`:''}${g.passive?`<div class="artifact-description"><b>神器之力</b><p>${g.passive}，装备时生效</p></div>`:''}<div class="button-pair">${button(equipped?'已穿戴':owned?'换上此装备':'尚未拥有','equip',`data-id="${id}"`,equipped||!owned||!!combatBusy(),'primary')}${equipped?button('卸下','unequip',`data-slot="${slot}"`,!!combatBusy(),'secondary'):'<button class="secondary" data-close>暂不替换</button>'}</div>`:'<p>此栏位还没有装备。点击下方已有物品查看比较，或去坊市选购。</p>'}<div class="enhance-panel"><h3>${SLOTS[slot]}栏位 · 强化 +${lv}</h3><p>${enhancementEffect(slot)}；穿戴与卸下都不丢强化。</p><p>${lv>=limit?'已至本卷上限':cost(c)}</p>${button(lv>=limit?'已至 +'+limit:'强化至 +'+(lv+1),'enhance',`data-slot="${slot}" data-level="${lv}" data-cost="${esc(JSON.stringify(c))}"`,lv>=limit||!afford(state,c)||!!combatBusy(),'secondary large')}${lv<limit&&!afford(state,c)?`<small class="warning">${Object.entries(c).filter(([k,n])=>(state[k]||0)<n).map(([k,n])=>'还差 '+fmt(n-state[k])+' '+RES[k]).join('、')}</small>`:''}</div>${alternatives.length?`<h3>可替换的${SLOTS[slot]}</h3><div class="replacement-list">${alternatives.map(x=>`<button data-gear="${x}">${gearIcon(slot)}<span><b>${itemInfo(state,x).displayName}</b><small>${QUALITY[itemInfo(state,x).quality]} · ${gearStats(itemInfo(state,x))}</small></span></button>`).join('')}</div>`:`<p class="small-note">暂无其他${SLOTS[slot]}，坊市可以买到更多装备。</p>`}<section class="gear-sources"><h3>获取途径</h3><button class="source-route" data-craft-slot="${slot}">定向炼制${SLOTS[slot]} · 查看固定炉方</button>${sourceButtons(id,slot)}</section><button class="text" data-ui="gearMarket">去坊市看看</button></div>`,'gear',refresh);}
function treasureSummary(){const names=Object.keys(TREASURES).sort((a,b)=>(GEAR[a].gate||1)-(GEAR[b].gate||1)).map(id=>treasureInfo(state,id)),active=names.filter(t=>t.active);return `<section class="treasure-summary"><div><h3>法宝 · 已激活 ${active.length} / ${names.length}</h3><p>${active.length?active.map(t=>t.name).join('、')+'的加成正在生效':'获得后点激活，无需放入装备栏'}</p></div><button class="secondary" data-ui="treasures">打开法宝录</button><small>永久激活叠加 · 集齐同系可共鸣</small></section>`;}
function treasureStatusSignature(){return JSON.stringify([state.runId,state.level,state.tower,state.finale,state.foundationFinale,Object.keys(TREASURES).map(id=>{const t=treasureInfo(state,id);return [id,t.known,t.active,t.copies]}),cultivation(state),statBreakdown(state).treasures,state.specializations,state.specialtyTrials]);}
function showTreasures(preserveScroll=false){gearDetail=null;treasureViewSignature=treasureStatusSignature();const rows=Object.keys(TREASURES).map(id=>treasureInfo(state,id)),active=rows.filter(t=>t.active),d=statBreakdown(state),c=cultivation(state);modal(`<span class="volume">独立于六格装备</span><h2>法宝录 · 共鸣</h2><p>每种法宝激活一次，永久生效。同系列的2件、3件效果同时保留；不同系列可以叠加。</p><div class="treasure-total"><b>已激活 ${active.length} / ${rows.length}</b><p class="treasure-ready">${rows.filter(t=>t.known&&!t.active).length?rows.filter(t=>t.known&&!t.active).length+' 件已解锁，点击下方“激活”即可生效':active.length===rows.length?'所有法宝已激活，共鸣永久保留':'缺件来源与开放条件见下方，点法宝名可预览实际增益'}</p><p>基础攻伐 +${d.treasures.atk} · 护体 +${d.treasures.def} · 气血 +${d.treasures.hp}</p><p>当前修炼：${fmt(c.interval)}秒 +${fmt(c.gain)}，约${fmt(c.perMinute)}修为 / 分钟</p><details><summary>已激活法宝与累计共鸣</summary>${active.map(t=>`<p>${t.name}：${t.effect}</p>`).join('')||'<p>尚未激活法宝</p>'}${treasureResonances(state,false).flatMap(f=>f.tiers.filter(t=>t.active).map(t=>`<p>${f.name} · ${t.count}件：${t.text}</p>`)).join('')}</details></div>${resonanceCards()}<p class="warning" data-battle-notice ${state.battle?'':'hidden'}>斗法结束后才能激活法宝。</p><details class="quiet-details"><summary>首通、旧进度与重复副本</summary><p>地图法宝只在首次主动通关时获得1件副本；重访和挂机不重复掉落。更新前已有相应首通记录，也可直接激活，不额外补发副本。</p><p>激活不消耗副本、不自动加锁。重复副本不会再次加成；未锁定副本仍可分解，每件50玄铁。即使分解所有副本，已激活法宝与共鸣永久保留。</p><p>旧版穿戴的山河钟或问山印继续保持激活，灵饰栏强化保留。一线天仍是兵器神器，不计入独立法宝共鸣。</p><p>减时与所有已学功法叠加，间隔最短10秒。触及下限时单次增修仍有效。</p></details>`,'treasures',preserveScroll);}

function treasurePreview(id){const p=treasureActivationPreview(state,id);if(!p||p.active)return '';const delta=n=>(n>0?'+':'')+fmt(n),rows=[['atk','攻伐'],['def','护体'],['hp','气血上限']];return `<details class="activation-preview"><summary>激活预览 · 查看属性与修炼变化</summary><h3>当前 → 激活后</h3>${rows.map(([k,n])=>`<div class="preview-stat"><span>${n}</span><b>${fmt(p.before[k])} → ${fmt(p.after[k])}<small>${delta(p.after[k]-p.before[k])}</small></b></div>`).join('')}<p>修炼间隔 ${fmt(p.currentRate.interval)} → ${fmt(p.rate.interval)} 秒<br>单次修为 ${fmt(p.currentRate.gain)} → ${fmt(p.rate.gain)}<br>每分钟约 ${fmt(p.currentRate.perMinute)} → ${fmt(p.rate.perMinute)} 修为</p>${p.combat.pierce!==p.currentCombat.pierce?`<p>技能忽略护体 ${fmt(p.currentCombat.pierce*100)}% → ${fmt(p.combat.pierce*100)}%</p>`:''}${p.tiers.map(t=>`<p class="set-active">同时开启 ${t.family} · ${t.count}件：${t.text}</p>`).join('')}<small>按当前功法与装备计算，已包含法宝本身和新共鸣；气血显示上限。${!p.known?'先完成下方来源，才能激活。':''}${p.rate.interval===10?'修炼已达10秒下限，额外减时不再缩短。':''}</small></details>`;}
function showTreasureDetail(id,refresh=false){const g=itemInfo(state,id),t=treasureInfo(state,g.baseId);gearDetail={id,slot:'charm',treasure:true};gearRenderSignature=gearSignature();if(!refresh)render();modal(`<div class="gear-detail treasure-detail quality-artifact"><div class="detail-title">${gearIcon('charm')}<div><span class="quality-label">独立法宝 · 不占装备栏</span><h2>${g.name}</h2><span class="enhance-label">${t.active?'已激活 · 永久生效':t.known?'已解锁 · 待激活':'未获得'}</span></div></div>${button(t.active?'已激活，不重复加成':t.known?'激活此法宝':'尚未获得','activateTreasure',`data-id="${id}" data-battle-lock data-unavailable="${t.active||!t.known}"`,t.active||!t.known||!!state.battle,'primary large')}${dismantleItemControls(id)}${treasureResonances(state).filter(f=>f.members.some(m=>m.baseId===g.baseId)).map(f=>`<p class="treasure-family-note">${f.name} · ${f.count}/3 已激活<br>${f.tiers.map(t=>(t.active?'已生效':'未达成')+' '+t.count+'件：'+t.text).join('<br>')}</p>`).join('')}<section class="treasure-total item-base"><b>${t.active?'已生效的加成':'激活后获得'}</b><p>${gearStats(t)}</p><p>${t.effect}</p></section>${treasurePreview(id)}<p class="small-note">激活不消耗副本，重复藏品不叠加。法宝不使用装备栏位；灵饰强化依然留在原栏位。</p><p class="small-note">这组藏品 ${state.inventory[id]||0} 件。分解副本每件得50玄铁，已经激活的永久加成保留。</p>${state.inventory[id]>0?button(g.locked?'解除手动锁定':'手动锁定副本','lockItem',`data-id="${id}"`,!!state.battle,'secondary large'):''}<section class="gear-sources"><h3>获取途径</h3>${sourceButtons(id)}</section><button class="secondary large" data-ui="treasures">返回法宝录</button></div>`,'treasure',refresh);}
function marketView(){if(marketPane==='craft')return `${head('定向炼器','固定成品，按需补齐部位')}${paneButtons('market-pane',marketPane,[['gear','装备'],['craft','炼器'],['supplies','丹药']])}${state.battle?'<p class="warning">斗法结束后可确认炼器。</p>':''}${craftingView()}${sceneBanner('mountain-forge','山中炼器炉与石台')}`;const chapter=marketChapter||realmChapter(state.level),stock=SHOP_GEAR.filter(id=>realmChapter(GEAR[id].gate||1)===chapter);return `${head('山间坊市',shopDiscount(state)?'执事试炼已过 · 九折生效':'以灵石易机缘')}${state.battle?'<p class="warning">斗法进行中，结束后可购买。<button class="text" data-ui="battleLocation">查看当前战斗</button></p>':''}<button class="market-technique-link" data-tech-source="merchant" data-tech-chapter="${chapter}"><b>功法已汇入藏经总览</b><span>在功法页直接用灵石学习与升级</span></button><div class="map-chapters"><button data-market-chapter="qi" class="${chapter==='qi'?'active':''}">炼气货架</button><button data-market-chapter="foundation" class="${chapter==='foundation'?'active':''}">筑基货架</button><button data-market-chapter="core" class="${chapter==='core'?'active':''}">金丹货架</button></div>${paneButtons('market-pane',marketPane,[['gear','装备'],['craft','炼器'],['supplies','丹药']])}${marketPane==='craft'?craftingView():marketPane!=='supplies'?stock.map(id=>gearCard(id,true)).join(''):`<div class="supply-row"><div><h3>回春丹 ×3</h3><p>${Math.ceil(35*(1-shopDiscount(state)))} 灵石</p></div>${button('购买','pills',`data-price="${Math.ceil(35*(1-shopDiscount(state)))}"`,!!state.battle||state.stones<Math.ceil(35*(1-shopDiscount(state))),'primary')}</div>`}`;}


function render(preserveTechniqueFocus=false){if(preserveTechniqueFocus&&screen==='game'&&tab==='market'&&marketPane==='craft'&&craftRenderedRunId===state?.runId&&['craft-tier','craft-slot'].includes(document.activeElement?.id)){craftRefreshPending=true;return;}craftRefreshPending=false;if(preserveTechniqueFocus&&screen==='game'&&tab==='techniques'&&techRenderedRunId===state?.runId&&['tech-source','tech-chapter','tech-loadout-main','tech-loadout-aux'].includes(document.activeElement?.id)){techRefreshPending=true;refreshTechniqueControls();return;}techRefreshPending=false;for(const d of document.querySelectorAll('#root details'))if(d.dataset.detail)openPanels.set(d.dataset.detail,d.open);const signature=JSON.stringify([state?.runId,state?.level,state?.extreme,state?.sect,state?.enhance,state?.equipment,state?.techniques,state?.combatLoadout,state?.activatedTreasures,state?.foundationType,state?.foundationPath,state?.foundationExtreme,state?.specializations,state?.specialtyTrials]);if(signature!==scoreSignature){scoreSignature=signature;scoreCache.clear();currentBagScore=null;}captureSceneMotion();motionObserver?.disconnect();motionObserver=null;motionStage=null;const y=window.scrollY||0;const root=$('#root');if(screen==='menu'){root.innerHTML=menu();return;}if(screen==='create'){root.innerHTML=creator();return;}if(!state){screen='menu';render();return;}const view={home,map:mapView,sect:sectView,bag:bagView,market:marketView,techniques:techniquesView,profile:profileView}[tab];root.innerHTML=`<div class="game-shell ${['home','profile'].includes(tab)?'scene-shell':''}" data-current-tab="${tab}" data-current-run="${esc(state.runId)}">${resourceHeader()}<main class="game-content">${storageError?`<p class="warning">${esc(storageError)}</p>`:''}${['home','profile'].includes(tab)?'':guide()}${view()}${['home','profile'].includes(tab)?guide():''}<footer><button class="text save-indicator" data-ui="saves">本机存档 · ${savedText()}</button><small>${chapterLabel(state)} · v${APP_VERSION}</small></footer></main><nav class="bottom-nav" aria-label="游戏导航">${[['home','修行','息'],['map','山河','图'],['sect','宗门','宗'],['techniques','功法','诀'],['bag','行囊','囊']].map(([id,label,glyph])=>`<button data-go="${id}" class="${tab===id?'active':''}" aria-current="${tab===id?'page':'false'}"><span>${glyph}</span>${label}</button>`).join('')}</nav></div>`;for(const d of document.querySelectorAll('#root details')){if(!d.dataset.detail)d.dataset.detail=tab+':'+(d.querySelector?.('summary')?.textContent||'');if(openPanels.has(d.dataset.detail))d.open=openPanels.get(d.dataset.detail);}if(tab==='techniques')techRenderedRunId=state.runId;if(tab==='market'&&marketPane==='craft')craftRenderedRunId=state.runId;if((window.scrollY||0)!==y)window.scrollTo({top:y,behavior:'auto'});bindSceneMotion();}
function clearEffects(){clearSceneEvent();clearTimeout(pulseTimer);clearTimeout(lootTimer);pulseTarget?.classList.remove('feedback-pulse');pulseTarget=null;for(const n of document.querySelectorAll('.loot-arrived')){n.classList.remove('loot-arrived');delete n.dataset.lootCount;}clearTimeout(combatFxTimer);$('#combat-fx').innerHTML='';clearTimeout(effectTimer);clearTimeout(gainTimer);$('#visual-fx').innerHTML='';$('#visual-fx').className='visual-fx';$('#cultivation-gain').textContent='';$('#cultivation-gain').className='cultivation-gain';}
const scrollBehavior=()=>visualMode==='light'||window.matchMedia?.('(prefers-reduced-motion: reduce)')?.matches?'auto':'smooth';
function focusContent(node){if(!node)return;const clearance=Math.ceil($('.game-header')?.getBoundingClientRect?.().height||150)+16;node.style.scrollMarginTop=clearance+'px';node.scrollIntoView({block:'start',behavior:scrollBehavior()});}
function go(t,highlight){viewSerial++;saveUiPosition();clearEffects();if(highlight==='equip'){bagFilter='all';bagQuality='all';bagVisible=24;}if(highlight==='clear'||highlight==='farm')state.uiMap={pane:'regions',area:'brook'};if(highlight==='learn'){t='techniques';techStatus='all';techSource='merchant';techChapter='qi';}if(highlight==='sect')sectPane='overview';if(!['home','map','sect','market','bag','techniques','profile'].includes(t))return;if(t==='techniques'&&tab!=='techniques')techReturn=tab;tab=t;screen='game';uiPrefs.tab=t;render();const targetScroll=Number.isFinite(uiPrefs.scrolls[t])?uiPrefs.scrolls[t]:0;window.scrollTo({top:targetScroll,behavior:'auto'});try{localStorage.setItem('wenshan-ui-v9',JSON.stringify(uiPrefs));}catch{}if(highlight){const selectors={cultivate:'[data-action="cultivate"]',clear:'[data-action="autoChallenge"]',farm:'[data-farm-config]',learn:'[data-action="learn"][data-id="breath"]',sect:'[data-action="join"]',equip:'.inventory-tile'};const node=$(selectors[highlight]);if(node){node.classList.add('tutorial-target');node.scrollIntoView({block:'center',behavior:scrollBehavior()});}}}
function showEffect(type,title,detail=''){if(document.hidden||screen!=='game'||$('#dialog').open)return;if(type==='breakthrough')sceneEvent('breakthrough');else if(type==='cultivate')sceneEvent('enter');clearTimeout(effectTimer);const node=$('#visual-fx');node.style.top=(Math.ceil($('.game-header')?.getBoundingClientRect?.().bottom||150)+12)+'px';node.style.bottom='auto';node.className=`visual-fx fx-${type}`;node.innerHTML=`<div class="effect-rings"><i></i><i></i><i></i></div><div class="effect-word"><strong>${esc(title)}</strong>${detail?`<span>${esc(detail)}</span>`:''}</div>`;effectTimer=setTimeout(()=>{node.innerHTML='';node.className='visual-fx';},2300);}
function showGain(amount){if(amount<=0||screen!=='game'||tab!=='home'||document.hidden||$('#dialog').open||!motionStageVisible)return;sceneEvent('gain');clearTimeout(gainTimer);const node=$('#cultivation-gain');node.className='cultivation-gain gain-visible';node.textContent=`修为 +${fmt(amount)}`;gainTimer=setTimeout(()=>{node.textContent='';node.className='cultivation-gain';},1700);}
async function action(type,p={}){p={...p,expectedRunId:p.expectedRunId||($('#dialog').open?modalRunId:state?.runId)};if(activeAction)return;activeAction=true;let outcome=null;try{await locked(()=>{if(p.expectedViewSerial!==undefined&&p.expectedViewSerial!==viewSerial)return;if(['startTowerRun','resumeTowerRun'].includes(type)&&(document.hidden||screen!=='game'))return;if(blocked){toast(storageError||'存档异常，请先导出备份');return;}sync();if(blocked){render();return toast('存档异常，请先导出当前进度');}if(p.expectedRunId&&p.expectedRunId!==state?.runId){outcome={ok:false,text:'当前仙途已变化，请重新打开面板核对后再操作'};render();refreshOpenGear();refreshModalAvailability();toast(outcome.text);return;}advance(state);const wasBattling=!!state.battle,deferFoundationFeedback=activeModal==='foundationPicker'&&['ascend','setFoundationPath'].includes(type),previousTiers=type==='activateTreasure'?treasureResonances(state,false).flatMap(f=>f.tiers.filter(t=>t.active).map(t=>f.id+':'+t.count)):[],towerTransaction=!!state.towerRun?.active||['startTowerRun','stopTowerRun','pauseTowerRun','resumeTowerRun'].includes(type),candidate=towerTransaction?JSON.parse(JSON.stringify(state)):state,r=act(candidate,type,p);outcome=r;if(towerTransaction&&r.ok){try{const raw=writeSave(localStorage,candidate,lastRaw);state=candidate;lastRaw=raw;}catch{blocked=true;storageError='闯塔操作未保存，已暂停；请保留页面并导出进度';outcome={ok:false,text:storageError};render();refreshModalAvailability();toast(storageError,'error');return;}}else save();if(r.ok&&['equip','enhance','unequip'].includes(type)){selectedSlot=p.slot||itemInfo(state,p.id)?.slot;gearFeedback=type==='enhance'?`${SLOTS[selectedSlot]}强化 +${state.enhance[selectedSlot]}`:type==='equip'?`${itemInfo(state,p.id).name} · 已穿戴`:'已卸下，强化仍保留';clearTimeout(gearFeedbackTimer);gearFeedbackTimer=setTimeout(()=>{gearFeedback=null;const n=$('.detail-feedback');if(n)n.remove?.();},2200);}render();refreshOpenGear(true);refreshModalAvailability();if(r.ok&&!wasBattling&&state.battle)battleLocation();if(r.ok&&type==='undoDismantle'&&$('#dialog').open)showDismantleHub();if(r.combat)showCombatFeedback(r.combat);if(r.ok&&type==='equipRecommended')showEffect('equipment','整装待发','推荐清单已穿戴，强化全部保留');if(r.ok){if(['breakthrough','extreme','ascend'].includes(type)&&!deferFoundationFeedback)showEffect('breakthrough',type==='extreme'?'极境已成':'破境',levelName(state));else if(type==='cultivate'&&state.cultivating)showEffect('cultivate','入定','灵息周天，修为渐长');else if(['equip','enhance'].includes(type)&&!$('#dialog').open)showEffect('equipment',type==='enhance'?'百炼有成':'焕然一新',gearFeedback);else if(type==='learn')showEffect('learn','融会于心','功法加成已叠加');}if(r.ok&&type==='activateTreasure'){const id=itemInfo(state,p.id).baseId,f=treasureResonances(state,false).find(f=>f.members.some(t=>t.id===id)),newTiers=f.tiers.filter(t=>t.active&&!previousTiers.includes(f.id+':'+t.count));pulseElement($('[data-resonance="'+f.id+'"]')||$('.treasure-detail'));toast(itemInfo(state,p.id).name+'已激活，永久加成生效'+(newTiers.length?'；'+newTiers.map(t=>f.name+' '+t.count+'件：'+t.text).join('、'):''),'success');}else if((!['combat','dismissOffline','tutorial'].includes(type)||!r.ok)&&!(r.ok&&deferFoundationFeedback))toast(r.text,r.ok?'success':'error');});}finally{activeAction=false;}return outcome;}
function showStats(){if(!state)return;gearDetail=null;const d=statBreakdown(state),cp=combatProfile(state),c=cultivation(state),names={atk:'攻伐',def:'护体',hp:'气血上限',gain:'单次修为',speed:'修炼减时'},pctText=n=>(Math.round(n*1000)/10)+'%';modal(`<div class="attribute-panel"><span class="volume">根基有数</span><h2>${esc(state.name)} · 属性</h2><p>${levelName(state)} · ${cp.name}</p>${state.level>=11?`<p>${foundationChoice(state)?.name||'尚未选择道基'} · 筑基类型固定，道基可脱战免费改换</p>`:''}${state.coreFinale?'<p class="earned-title">称号 · 一息成丹</p>':''}${state.extremeTrial?'<p class="earned-title">称号 · 极境问山人</p>':''}<div class="attribute-overview"><span>气血 <b>${state.hp} / ${d.final.hp}</b></span><span>战力估值 <b>${d.final.power}</b></span></div><p class="small-note">以下为打开面板时的状态。战力用于概览，不等于实际伤害。</p>${['atk','def','hp'].map(k=>`<section class="attribute-stat"><div class="attribute-heading"><h3>${names[k]}</h3><strong>${d.final[k]}</strong></div><div class="attribute-components"><span>境界基础 <b>${d.base[k]}</b></span><span>装备 <b>+${d.equipment[k]}</b></span><span>栏位强化 <b>+${d.enhancement[k]}</b></span><span>已激活法宝 <b>+${d.treasures[k]}</b></span></div><p class="formula">(${d.base[k]} + ${d.equipment[k]} + ${d.enhancement[k]} + ${d.treasures[k]}) × (1 ${d.percent[k]<0?'−':'+'} ${pctText(Math.abs(d.percent[k]))})<br>四舍五入 = <b>${d.final[k]}</b></p><details><summary>百分比来源 · ${pctText(d.percent[k])}</summary>${d.sources.filter(r=>r[k]).map(r=>`<div class="source-row"><span>${r.name}</span><b>${r[k]>0?'+':''}${pctText(r[k])}</b></div>`).join('')||'<p>尚无百分比加成</p>'}</details></section>`).join('')}<details class="attribute-items"><summary>查看装备、强化与法宝基础数值</summary>${[...d.equipmentRows,...d.enhancementRows,...d.treasureRows].map(r=>`<div class="source-row"><span>${r.name}</span><small>${['atk','def','hp'].filter(k=>r[k]).map(k=>names[k]+' +'+r[k]).join(' · ')}</small></div>`).join('')}<p>栏位强化即使卸下装备仍生效，换装不会重复计算。所有百分比相加后，仅对最终结果四舍五入一次。</p></details><section class="attribute-stat"><h3>吐纳效率</h3><p>每 ${fmt(c.interval)} 秒获得 <b>${fmt(c.gain)}</b> 修为，约 <b>${fmt(c.perMinute)}</b> / 分钟</p><p class="formula">单次 = ${c.baseGain} × (1 + ${pctText(c.gainBonus)})<br>间隔 = 30 × (1 − ${pctText(c.speed)})，最短 10 秒</p>${d.sources.filter(r=>r.gain||r.speed).map(r=>`<div class="source-row"><span>${r.name}</span><small>${r.gain?'修为 +'+pctText(r.gain):''} ${r.speed?'减时 '+pctText(r.speed):''}</small></div>`).join('')}</section><section class="attribute-stat"><h3>实际战斗规则</h3>${cp.specialization?`<p><b>宗门专修 · ${cp.specialization.name}</b><br>${cp.specialization.text}</p>`:''}${cp.combo?`<p><b>功法套组 · ${cp.combo.name}</b><br>${cp.combo.text}</p>`:''}${treasureResonances(state,false).flatMap(f=>f.tiers.filter(t=>t.active&&t.pierce).map(t=>`<p><b>${f.name} · ${t.count}件</b><br>${t.text}</p>`)).join('')}<p><b>${cp.skill}</b>：消耗 ${cp.cost} 真气<br>伤害 = max(1, round(攻伐 × ${Number((cp.scale+cp.setBurst).toFixed(2)).toLocaleString('zh-CN')}) − round(敌方护体 × ${Number((1-cp.pierce).toFixed(2)).toLocaleString('zh-CN')}))</p>${cp.heal+cp.setHeal?`<p>技能回复 ${pctText(cp.heal+cp.setHeal)} 最大气血</p>`:''}${cp.shield?`<p>技能额外护盾 = round(护体 × ${Number(cp.shield.toFixed(2)).toLocaleString('zh-CN')})</p>`:''}${cp.guardHeal?`<p>守势回复 ${pctText(cp.guardHeal)} 最大气血</p>`:''}<p>守势回复 2 真气，承伤降至护体结算后的25%。<br>闪避步消耗1真气，成功率 ${pctText(cp.dodge)}；成功免去本次伤害，失败正常承伤。</p>${cp.bell?'<p>山河钟：每场首次承伤额外护盾，数值为8%最大气血。</p>':''}<p class="small-note">技能回血不超过气血上限。闪避步成功率受小周天诀每重增加2个百分点。</p></section><details><summary>套装、神器与战力公式</summary>${Object.entries(SETS).map(([id,set])=>`<p><b>${set.name} · 穿戴 ${setCounts(state)[id]||0} 件</b><br>${set.two}<br>${set.three}</p>`).join('')}<p>山河钟：战斗属性 +12%，每场首次承伤额外护盾。<br>一线天：攻伐 +18%。仅穿戴时生效。</p><p>战力 = round(攻伐 × 5 + 护体 × 4 + 气血上限 × 0.6)</p></details></div>`);}
let pendingReceipt=null;
function showFarmReport(){gearDetail=null;pendingReceiptRunId=state.runId;const live=state.farmLedger,receipt=live?.rounds?live:state.lastFarm;pendingReceipt=live?.rounds?JSON.parse(JSON.stringify(live)):null;modal(`<span class="volume">归山记账</span><h2>挂机收益汇总</h2>${receipt?`<p>${pendingReceipt?'自上次收拢以来':'上次已收拢的记录'} · ${receipt.rounds} 轮 · 结算 ${time(receipt.elapsed)}</p><div class="report-metrics">${['stones','ore','herbs','jade'].map(k=>`<span>${RES[k]}<b>+${fmt(receipt[k])}</b></span>`).join('')}</div><h3>途经何处</h3>${Object.entries(receipt.areas).map(([id,n])=>`<div class="source-row"><span>${AREAS.find(a=>a.id===id)?.name||id}</span><b>${n} 轮</b></div>`).join('')}<h3>所得装备</h3><p>${itemRewardList(receipt.items)||'这段时间尚未触发装备掉落'}</p><p class="small-note">这些收益已经自动入袋。此处只是记录，不需要领取，也不会再次发放。关闭与刷新不会重复结算。</p>${pendingReceipt?'<button class="primary large" data-ui="ackFarm">收拢这份记录</button>':''}`:'<p>还没有新的挂机记录。先通关地图，再开启挂机，收益会自动记在这里。</p>'}<button class="text" data-ui="reportBag">去行囊整理装备</button>`);}

function presetTechnique(id){return TECHNIQUES.find(t=>t.id===id)?.name||(id==='sect'?'随当前宗门':id?'功法记录缺失':'未配置');}
function presetRules(){return '<details class="quiet-details"><summary>保存和切换规则</summary><p>先调整好装备与主辅功法，再保存当前配置。预设名称只是用途标签，不会自动挑选最优装备。切换仅更换六格装备、主辅功法和已记录的道基；栏位强化、已学被动、已激活法宝与当前修炼、挂机状态保留。</p><p>炼气时保存的预设没有道基记录，筑基后使用会保留当时道基；普通或天道筑基类型始终不变。专修按所属宗门记录，不会自动换宗；旧预设未记录专修时保持当前。相同词条装备按一组记录，只需拥有1件。手动锁定防分解，不妨碍穿戴。预设不会自动锁定或阻止分解。</p></details>';}
function showPresets(){gearDetail=null;pendingPreset=null;modal(`<span class="volume">随时核对，再切换</span><h2>配装预设</h2><p>把常用装备、主辅功法与道基一起记下。</p><p class="small-note">修炼${state.cultivating?'正在进行':'尚未开启'}，切换预设不会改变开关。</p><div class="preset-cards">${Object.entries(PRESET_NAMES).map(([key,name])=>{const p=state.presets?.[key],v=presetPreview(state,p),same=p&&v.ok&&JSON.stringify(capturePreset(state))===JSON.stringify({equipment:p.equipment,combatLoadout:p.combatLoadout,foundationPath:p.foundationPath,specialty:p.specialty||null});return `<section class="preset-card"><div class="preset-heading"><h3>${name}</h3><span>${!p?'尚未保存':same?'与当前一致':v.ok?'可以切换':'待补齐'}</span></div><p>${p?.combatLoadout?`${presetTechnique(p.combatLoadout.main)} · ${presetTechnique(p.combatLoadout.aux)}<br>${p.foundationPath?FOUNDATION_PATHS[p.foundationPath]?.name||'道基记录缺失':'道基未记录，切换时保持当前'}<br>${presetSpecialtyLabel(p.specialty)}${p.savedAt?'<br><small>保存于 '+new Date(p.savedAt).toLocaleString('zh-CN',{hour12:false})+'</small>':''}`:p?'记录不完整，可重新保存':'先搭配好装备和功法，再保存到这个位置'}</p>${p&&!v.ok?`<p class="warning small-note">${esc(v.issues.join('；'))}</p>`:''}<div class="button-pair"><button class="secondary" data-preset-save="${key}" data-battle-lock>保存当前</button><button class="primary" data-preset-preview="${key}" ${!p?'disabled':''}>预览切换</button></div></section>`;}).join('')}</div><p class="warning" data-battle-notice ${combatBusy()?'':'hidden'}>斗法或连续闯塔结束后才能保存或切换预设。</p>${presetRules()}`,'presets');}
function presetComparison(v){if(!v.ok)return '';const a=v.current,b=v.after,rows=[['攻伐',a.stats.atk,b.stats.atk,''],['护体',a.stats.def,b.stats.def,''],['气血上限',a.stats.hp,b.stats.hp,''],['修炼间隔',a.cultivation.interval,b.cultivation.interval,'秒'],['每次修为',a.cultivation.gain,b.cultivation.gain,''],['每分钟修为',a.cultivation.perMinute,b.cultivation.perMinute,'']];return `<div class="preset-comparison"><div class="preset-compare-row"><span>实际效果</span><span>当前</span><span>切换后</span></div>${rows.map(([n,x,y,u])=>`<div class="preset-compare-row"><span>${n}</span><span>${fmt(x)}${u}</span><b>${fmt(y)}${u}${x!==y?`<small>${signed(Math.round((y-x)*100)/100)}${u}</small>`:''}</b></div>`).join('')}</div><p class="small-note">间隔越短越快。气血上限降低时，当前气血会降至新上限；切换不补血。</p><details data-detail="preset-combat"><summary>招式与套装变化</summary><p>专修：${a.combat.specialization?.name||'无'} → ${b.combat.specialization?.name||'无'}<br>${a.combat.skill} → ${b.combat.skill}<br>功法套组：${a.combat.combo?.name||'无'} → ${b.combat.combo?.name||'无'}</p>${[['真气消耗',a.combat.cost,b.combat.cost],['技能攻伐倍率',a.combat.scale+a.combat.setBurst,b.combat.scale+b.combat.setBurst],['忽略护体比例',a.combat.pierce,b.combat.pierce],['技能护盾 / 护体',a.combat.shield,b.combat.shield],['技能回血 / 最大气血',a.combat.heal+a.combat.setHeal,b.combat.heal+b.combat.setHeal],['守势回血 / 最大气血',a.combat.guardHeal,b.combat.guardHeal]].map(([n,x,y])=>`<p>${n}：${Number(x.toFixed(3))} → ${Number(y.toFixed(3))}</p>`).join('')}${Object.entries(SETS).filter(([id])=>a.sets[id]||b.sets[id]).map(([id,set])=>`<p>${set.name}：${a.sets[id]||0} → ${b.sets[id]||0} 件</p>`).join('')}<p>比例0.1表示10%；使用当前学成重数、栏位强化和永久法宝重新计算。</p></details>`;}
function showPresetPreview(key,mode='apply'){if(!Object.hasOwn(PRESET_NAMES,key))return;gearDetail=null;const record=mode==='save'?capturePreset(state):state.presets?.[key],v=presetPreview(state,record);pendingPreset={key,mode,runId:state.runId,signature:presetSignature(state,key,mode)};modal(`<span class="volume">${mode==='save'?'只记录，不换装':'整套切换前核对'}</span><h2>${mode==='save'?'保存':'切换'}「${PRESET_NAMES[key]}」预设</h2>${mode==='save'?`<p>${state.presets?.[key]?'这会覆盖该位置原来的配置记录，':'将当前配置记在这个位置，'}不会移动、锁定或分解物品。</p>`:''}${record?.equipment?`<div class="preset-equipment">${Object.entries(SLOTS).map(([slot,n])=>{const id=record.equipment[slot],g=itemInfo(state,id);return `<div><span>${n} · 强化 +${state.enhance[slot]}</span><b>${esc(id?g?.displayName||'物品记录缺失':'空栏位')}</b>${id&&!(state.inventory[id]>0)?'<small class="warning">当前缺少</small>':''}</div>`;}).join('')}</div><p><b>主修</b> ${presetTechnique(record.combatLoadout?.main)}<br><b>辅修</b> ${presetTechnique(record.combatLoadout?.aux)}<br><b>道基</b> ${record.foundationPath?FOUNDATION_PATHS[record.foundationPath]?.name||'记录无效':'保持当前道基'}${state.level>=11?' · '+(state.foundationType==='heaven'?'天道':'普通')+'筑基类型保留':''}<br><b>专修</b> ${presetSpecialtyLabel(record.specialty)}</p>`:''}${v.ok?presetComparison(v):`<p class="warning">${esc(v.issues.join('；'))}<br>未满足时不会部分换装，也不会替换成其他装备。</p>`}<p id="preset-stale-warning" class="warning" hidden>配置或预设已变化，请重新核对。</p><p class="warning" data-battle-notice ${combatBusy()?'':'hidden'}>斗法或连续闯塔结束后才能确认，面板可以保留。</p><div class="button-pair"><button class="secondary" data-ui="presets">返回预设</button><button class="primary" data-ui="confirmPreset" data-battle-lock data-unavailable="${!v.ok}" ${!v.ok||combatBusy()?'disabled':''}>${mode==='save'?'确认保存当前':'确认整套切换'}</button></div><button class="text" data-preset-refresh="${key}" data-preset-mode="${mode}">重新核对当前状态</button>${mode==='apply'&&!v.ok?'<p class="small-note">若已不想找回缺件，可返回预设，重新保存现在的配置。</p>':''}${presetRules()}`,'presetPreview');}
async function confirmPreset(){if(!pendingPreset||activeAction||blocked)return;const ticket={...pendingPreset},serial=viewSerial;activeAction=true;try{await locked(()=>{if(serial!==viewSerial||activeModal!=='presetPreview'||!$('#dialog').open)return;sync();if(blocked)return;advance(state);if(serial!==viewSerial||ticket.runId!==state.runId){toast('当前仙途已变化，请重新打开预设','error');refreshModalAvailability();return;}const candidate=JSON.parse(JSON.stringify(state)),r=act(candidate,ticket.mode==='save'?'savePreset':'applyPreset',{key:ticket.key,signature:ticket.signature,expectedRunId:ticket.runId});if(!r.ok){toast(r.text,'error');refreshModalAvailability();return;}try{const raw=writeSave(localStorage,candidate,lastRaw);state=candidate;lastRaw=raw;}catch{blocked=true;storageError='预设操作未保存，原配置未改变；请导出当前进度并保留页面';render();refreshModalAvailability();toast(storageError,'error');return;}resetTechDraft();render();showPresets();toast(r.text,'success');});}finally{activeAction=false;}}
function presetDismantleNotice(items){const warnings=presetDismantleWarnings(state,items);return warnings.length?`<p class="warning preset-dismantle-warning">将使${warnings.map(w=>'「'+w.name+'」缺少 '+w.ids.map(id=>itemInfo(state,id)?.displayName||id).join('、')).join('；')}。仍可确认分解；预设记录保留，撤销分解或重新获得相同装备后可用。</p>`:'';}


function presetSpecialtyLabel(p){return !p?'专修未记录，保持当前':(SECTS.find(s=>s.id===p.sect)?.name||'宗门记录无效')+' · '+(SPECIALIZATIONS[p.sect]?.find(x=>x.id===p.id)?.name||(p.id?'专修记录无效':'暂不专修'));}
function specialtyView(){const t=specialtyInfo(state),choice=specialization(state);if(!t)return '<p>先选择宗门。</p>';return `<section class="specialty-page"><button class="text" data-sect-pane="overview">返回山门概览</button><h3>本门专修</h3><p>当前：<b>${choice?.name||'尚未选择'}</b>。两条道路只生效一条，脱战免费改换。</p><div class="specialty-options">${SPECIALIZATIONS[state.sect].map(x=>`<article class="specialty-option"><h3>${x.name}</h3><p>${x.text}</p><button class="${choice?.id===x.id?'secondary':'primary'}" data-specialty-choice="${x.id}" ${!t.done||state.battle?'disabled':''}>${choice?.id===x.id?'已选择 · 查看':'预览并选择'}</button></article>`).join('')}</div>${choice?'<button class="text" data-specialty-choice="none">预览暂不专修</button>':''}<p class="small-note">改宗时本门专修暂不生效，已学功法、专修选择与试炼记录保留；重回本宗后恢复。配装预设会记录当前专修，但不会替你换宗。</p>${state.battle?.specialtyTrial?battleView():state.lastBattle?.specialtyTrial===state.sect?battleReport('sect',3):''}<details class="specialty-trial" data-detail="specialty-trial"><summary>${t.name} · ${t.done?'已完成':'解锁专修'}</summary><p>${t.counter}</p><p>${t.enemy} · 气血 ${t.hp} / 攻伐 ${t.atk} / 护体 ${t.def}</p><p>第三回合：${t.detail}</p><p>首胜解锁本门两条专修，并获得500灵石、30玄铁、6灵髓。重访仅练习，不重复发奖，不改动原职位试炼。</p></details><p class="${t.available?'small-note':'warning'}">${t.reason}</p>${button(t.done?'重访专修试炼':'自动挑战专修试炼','specialtyTrial',`data-id="${state.sect}"`,!t.available||!!state.battle,'secondary large')}<p class="small-note">普通筑基即可，不要求天道或极境；无需为试炼消耗贡献。</p></section>`;}
function showSpecialtyPreview(id){const v=specializationPreview(state,id);if(!v.ok)return toast(v.reason,'error');gearDetail=null;pendingSpecialty={id,sect:state.sect,runId:state.runId,signature:v.signature};const preview=presetPreview(state,{...capturePreset(state),specialty:{sect:state.sect,id}});modal(`<span class="volume">只选本门一条</span><h2>${v.choice?v.choice.name:'暂不专修'}</h2><p>${v.choice?.text||'停止本门专修加成，试炼记录仍保留，可免费选回来。'}</p>${presetComparison(preview)}<p id="specialty-status" class="small-note">脱战可免费改换，仅当前宗门专修生效</p><p class="warning" data-battle-notice ${state.battle?'':'hidden'}>斗法结束后才能确认。</p><div class="button-pair"><button class="secondary" data-close>取消</button><button class="primary" data-ui="confirmSpecialty" data-battle-lock>确认选择</button></div>`,'specialtyPreview');}
function craftingView(){const tier=CRAFT_TIERS.find(t=>t.id===craftTier)||CRAFT_TIERS.filter(t=>state.level>=t.gate).at(-1)||CRAFT_TIERS[0];craftTier=tier.id;const c=craftInfo(state,craftTier,craftSlot),g=c.gear;return `<section class="crafting-page"><p>选择阶段和部位，材料换固定成品。每次1件，无随机词条。</p><div class="craft-controls"><label>炉方阶段<select id="craft-tier">${CRAFT_TIERS.map(t=>`<option value="${t.id}" ${t.id===craftTier?'selected':''}>${t.name} · ${stageName(t.gate)}</option>`).join('')}</select></label><label>装备部位<select id="craft-slot">${Object.entries(SLOTS).map(([id,n])=>`<option value="${id}" ${id===craftSlot?'selected':''}>${n}${state.equipment[id]?'':' · 空缺'}</option>`).join('')}</select></label></div><article class="craft-result"><span class="quality-label">${QUALITY[g.quality]} · ${SLOTS[craftSlot]}</span><h3>${g.name}</h3><p>${gearStats(g)}</p>${g.set?`<p>${SETS[g.set].name}套装 · 当前${setCounts(state)[g.set]||0}件</p>`:''}<p>已持有定型成品 ${c.owned} 件 · 无词条</p><p class="craft-cost"><b>消耗 ${cost(c.cost)}</b></p>${!c.available?`<p class="warning">${!c.open?c.reason:Object.entries(c.cost).filter(([k,n])=>state[k]<n).map(([k,n])=>'还差 '+fmt(n-state[k])+' '+RES[k]).join('、')}</p>`:''}<button class="primary large" data-ui="craftPreview">预览成品与换装效果</button></article><p class="small-note">制作只收入行囊，不自动换装或锁定。相同成品合并计数；不能重洗词条。炼器不享坊市折扣，玄铁也可用于栏位强化，请按需求选择。</p></section>`;}
function openCrafting(slot=null){if(slot&&Object.hasOwn(SLOTS,slot))craftSlot=slot;close();marketPane='craft';go('market');}
function showCraftPreview(){const c=craftInfo(state,craftTier,craftSlot);if(!c)return;gearDetail=null;pendingCraft={tier:craftTier,slot:craftSlot,runId:state.runId,signature:c.signature};const next={...capturePreset(state),equipment:{...state.equipment,[craftSlot]:c.id}},compareState={...state,inventory:{...state.inventory,[c.id]:Math.max(1,c.owned)}};modal(`<span class="volume">固定制作 · 成品1件</span><h2>炼制${c.gear.name}</h2><p>${gearStats(c.gear)} · ${QUALITY[c.gear.quality]} · 无词条</p><p class="craft-cost">确认消耗：<b>${cost(c.cost)}</b></p><p>制作后持有 ${c.owned+1} 件，不会自动穿戴。以下是之后手动换上时的效果：</p>${presetComparison(presetPreview(compareState,next))}<p id="craft-current-status" class="warning">${c.reason}</p><p class="warning" data-battle-notice ${state.battle?'':'hidden'}>斗法结束后才能炼器。</p><div class="button-pair"><button class="secondary" data-close>取消</button><button class="primary" data-ui="confirmCraft" data-battle-lock data-unavailable="${!c.available}" ${!c.available||state.battle?'disabled':''}>确认消耗并炼制</button></div><button class="text" data-ui="craftPreview">重新核对</button>`,'craftPreview');}
async function confirmBuildChoice(kind){const ticket=kind==='craft'?pendingCraft:pendingSpecialty,expectedModal=kind==='craft'?'craftPreview':'specialtyPreview';if(!ticket||activeAction||blocked)return;const p={...ticket},serial=viewSerial;activeAction=true;try{await locked(()=>{if(serial!==viewSerial||activeModal!==expectedModal||!$('#dialog').open)return;sync();if(blocked)return;advance(state);if(state.runId!==p.runId)return toast('当前仙途已变化，请重新预览','error');const candidate=JSON.parse(JSON.stringify(state)),r=act(candidate,kind==='craft'?'craftGear':'setSpecialization',{...p,expectedRunId:p.runId});if(!r.ok){refreshModalAvailability();return toast(r.text,'error');}try{const raw=writeSave(localStorage,candidate,lastRaw);state=candidate;lastRaw=raw;}catch{blocked=true;storageError='本次操作未保存，原配置与材料未改变；请导出进度并保留页面';render();refreshModalAvailability();toast(storageError,'error');return;}close();render();toast(r.text,'success');});}finally{activeAction=false;}}

function showDismantle(){showDismantlePreview({mode:'all',...dismantlePlan(state)});}
function showDismantlePreview(plan){gearDetail=null;pendingDismantle={expectedRunId:state.runId,mode:plan.mode||'manual',presetImpact:JSON.stringify(presetDismantleWarnings(state,plan.items)),items:plan.items.map(({id,count})=>({id,count})),...(plan.equipment?{equipment:{...plan.equipment},beforeEquipment:{...plan.beforeEquipment}}:{})};const ore=plan.items.reduce((n,r)=>n+r.count*dismantleValue(state,r.id),0),count=plan.items.reduce((n,r)=>n+r.count,0);modal(`<span class="volume">核对后才会执行</span><h2>${plan.mode==='equipRemaining'?'换上推荐，再分解其余':'确认分解装备'}</h2>${plan.equipment?`<h3>先更换这些栏位</h3>${Object.keys(SLOTS).filter(slot=>plan.beforeEquipment[slot]!==plan.equipment[slot]).map(slot=>`<div class="source-row"><span>${SLOTS[slot]} · 强化 +${state.enhance[slot]} 保留</span><small>${itemInfo(state,plan.beforeEquipment[slot])?.displayName||'空'}<br>换为 ${itemInfo(state,plan.equipment[slot])?.displayName||'空'}</small></div>`).join('')||'<p>当前穿戴已是推荐组合，无需换装。</p>'}<p class="small-note">按当前主辅功法的整套评分推荐，不保证每个敌人面前都最强。确认后先换装，再分解下面列出的装备。</p>`:''}<p>仅保留${plan.equipment?'换装后':'当前'}穿戴的1件，以及你手动锁定的物品。套装、神器、高品阶和最后1件<b>都可以分解</b>。</p>${count?`${presetDismantleNotice(plan.items)}<h3>将分解 ${count} 件</h3><div class="dismantle-preview-list">${plan.items.map(r=>`<div class="source-row"><span>${itemInfo(state,r.id).displayName} ×${r.count}<small>${QUALITY[itemInfo(state,r.id).quality]}</small></span><b>${r.count*dismantleValue(state,r.id)} 玄铁</b></div>`).join('')}</div><p class="dismantle-total">共 ${count} 件，得到 <b>${ore} 玄铁</b></p><p class="small-note">只处理此处列出的数量，预览后新获得的物品保留。可以撤销最近一次分解，需归还所得玄铁。${plan.equipment?'同时撤销换装；若之后主动换过装备，则保留后来的穿戴。':''}${state.dismantleUndo?'这次执行会替换上一条撤销记录。':''}</p><div class="button-pair"><button class="secondary" data-close>取消</button><button class="danger" data-battle-lock data-ui="confirmDismantle" ${state.battle?'disabled':''}>${plan.equipment?'确认换装并分解':'确认分解'} ${count} 件</button></div>`:`<p class="empty-inventory">没有未穿戴且未锁定的装备</p>${Object.keys(state.inventory).filter(id=>state.inventory[id]>0).map(id=>`<div class="source-row"><span>${itemInfo(state,id).displayName} ×${state.inventory[id]}</span><small>${dismantleReason(state,id)}</small></div>`).join('')}`} <p class="warning" data-battle-notice ${state.battle?'':'hidden'}>斗法结束后才能确认分解。</p><button class="text" data-ui="dismantleHub">返回装备整理</button>`);}
function showEquipDismantle(){const p=recommendationPreview(state);showDismantlePreview({mode:'equipRemaining',...dismantlePlan(state,p.equipment),equipment:p.equipment,beforeEquipment:{...state.equipment}});}
function dismantleItemControls(id){const g=itemInfo(state,id),cap=dismantleCapacity(state,id);return `<section class="item-dismantle">${Object.entries(PRESET_NAMES).filter(([key])=>Object.values(state.presets?.[key]?.equipment||{}).includes(id)).map(([,name])=>`<p class="small-note">用于「${name}」预设 · 不自动保护，可继续分解</p>`).join('')}<div><b>分解这件装备</b><small>${cap?'可分解 '+cap+' 件 · 每件 '+dismantleValue(state,id)+' 玄铁':dismantleReason(state,id)}</small></div><form id="dismantle-item-form"><label for="dismantle-count">数量<input id="dismantle-count" type="number" inputmode="numeric" min="1" max="${Math.max(1,cap)}" value="1" ${!cap||combatBusy()?'disabled':''}></label><button class="danger" type="submit" ${!cap||combatBusy()?'disabled':''}>分解</button></form>${combatBusy()?'<small>斗法或连续闯塔中暂不能分解</small>':''}${cap&&state.equipment[g.slot]===id?'<small>穿戴的1件保留，只分解多余副本</small>':''}${g.locked?`<button class="text" data-action="lockItem" data-id="${id}" ${combatBusy()?'disabled':''}>解除手动锁定</button>`:''}</section>`;}

function followGoal(){const g=nextGoal(state);if(g.target==='battle'){battleLocation();return;}if(g.target==='resources'){farmGoal=g.resource==='stones'?'stones':'materials';farmMaterial=g.resource;showFarmGoals();return;}if(g.target==='recovery'){showRecovery();return;}if(g.target==='corePrepare'){go('home');showCorePreview();return;}if(g.target==='core')state.uiMap={...state.uiMap,pane:'core',chapter:'core'};if(g.target==='ascend'){go('home');showFoundationPicker('ascend');return;}if(g.target==='foundationPath'){go('home');showFoundationPicker('change');return;}if(AREAS.some(a=>a.id===g.target))state.uiMap={pane:'regions',area:g.target};if(g.target==='foundation')state.uiMap={...state.uiMap,pane:'foundation',chapter:'foundation'};if(g.target==='finale')state.uiMap={...state.uiMap,pane:'finale'};if(g.target==='tower')state.uiMap={...state.uiMap,pane:'tower'};if(TECHNIQUES.some(t=>t.id===g.target)){openTechniques({id:g.target});return;}if(g.tab==='sect')sectPane=g.target==='mission'?'missions':'overview';go(g.tab);const selector=g.target==='progress'?'.tick-row':g.target==='mission'?'[data-action="claimMission"]':g.target==='battle'?'.battle':g.target==='sect'?'.sect-options':['finale','foundation','core'].includes(g.target)?'.finale-panel':g.target==='tower'?'.tower-section':g.target==='gear'?'.equipment-grid':AREAS.some(a=>a.id===g.target)?`#area-${g.target}`:TECHNIQUES.some(t=>t.id===g.target)?`[data-action="learn"][data-id="${g.target}"]`:`[data-action="${g.target}"]`;const n=$(selector);if(n){n.classList.add('tutorial-target');n.scrollIntoView({block:'center',behavior:scrollBehavior()});}}
function showCombatFeedback(f){if(!f||document.hidden)return;clearTimeout(combatFxTimer);const n=$('#combat-fx');n.innerHTML=`${f.damage?`<i class="combat-trace trace-${f.move}" aria-hidden="true"></i>`:''}<div class="combat-number outgoing">${f.damage?'造成 '+f.damage+' 伤害':f.evaded?'闪避成功':f.move==='dodge'?'闪避失败':esc(f.skill)}</div>${f.taken?`<div class="combat-number incoming">受到 ${f.taken} 伤害</div>`:''}${f.healed?`<div class="combat-number healing">回复 ${f.healed} 气血</div>`:''}`;combatFxTimer=setTimeout(()=>n.innerHTML='',1400);}
function matchesCurrentAdventure(expected){let disk=null;try{disk=validateSave(JSON.parse(localStorage.getItem(KEY)));}catch{}return (state?.runId||null)===expected&&(!disk||disk.runId===expected);}
function showRestorePreview(){const previousRaw=localStorage.getItem(KEY+'-previous-adventure');if(!previousRaw)return toast('暂无上一卷备份');let previous;try{previous=validateSave(JSON.parse(previousRaw));}catch{}if(!previous)return toast('上一卷无法读取，原数据仍保留，可先导出备份');pendingRestore={runId:state?.runId||null,previousRaw};modal(`<h2>恢复上一卷？</h2><p>当前：${esc(state?.name||'未读取')}<br>上一卷：${esc(previous.name)} · ${levelName(previous)}</p><p>两卷将互换，不会删除其中任何一份。</p><button class="primary" data-ui="confirmRestore">交换并恢复</button>`,'restorePreview');}
async function confirmImport(){if(importing||!pendingImport)return;const imported=pendingImport,expectedRunId=pendingImportRunId;importing=true;const button=$('[data-ui="confirmImport"]');if(button)button.disabled=true;try{await locked(()=>{try{if(localStorage.getItem(KEY+'-restore-pending'))return toast('请先在本机存档中完成恢复处理，再导入其他存档');sync();if(!matchesCurrentAdventure(expectedRunId))return toast('当前仙途已变化，请关闭面板后重新选择存档');const raw=localStorage.getItem(KEY),rescue=state?JSON.stringify(state):raw;if(raw)localStorage.setItem(KEY+'-before-import',raw);let previousValid=null;try{previousValid=validateSave(JSON.parse(rescue));}catch{}if(previousValid)localStorage.setItem(KEY+'-previous-adventure',rescue);const restored=JSON.parse(JSON.stringify(imported));restored.runId=restored.runId+'-import-'+Date.now();restored.revision++;pauseTowerRun(restored,'导入后已暂停，点击继续');const r=advance(restored);if(r.elapsed>60&&(r.exp||r.rounds))restored.offline=r;const written=writeSave(localStorage,restored,null);state=restored;lastRaw=written;blocked=false;storageError='';pendingImport=null;close();go('home');toast('存档已恢复，原进度已另存备份');}catch{toast('恢复写入失败，当前进度未替换。请保留存档文件，可稍后重试。');}});}finally{importing=false;const button=$('[data-ui="confirmImport"]');if(button)button.disabled=false;}}
async function restoreAdventure(){if(restoring)return;if(!pendingRestore)return toast('请先打开恢复预览核对两卷');const preview=pendingRestore;restoring=true;const button=$('[data-ui="confirmRestore"]');if(button)button.disabled=true;try{await locked(()=>{sync();if(!matchesCurrentAdventure(preview.runId)||localStorage.getItem(KEY+'-previous-adventure')!==preview.previousRaw)return toast('当前卷或上一卷已变化，请关闭面板后重新核对');const result=swapAdventure(localStorage,state?JSON.stringify(state):null);if(!result.ok){if(result.reason==='invalid')return toast('备份无法读取，未修改存档');blocked=true;storageError=result.reason==='pending'?'先处理上一次未完成的恢复。所有恢复备份仍保留':'恢复未完成。请导出当前进度与恢复前备份，不要清除网站数据';render();saves();return toast('恢复写入失败，两卷原始数据可在存档中导出');}state=result.state;lastRaw=result.raw;blocked=false;storageError='';const r=advance(state);if(r.elapsed>60&&(r.exp||r.rounds))state.offline=r;save();close();go('home');toast(blocked?'恢复后的保存失败，请立即导出当前进度':'已恢复上一卷');});}finally{restoring=false;const button=$('[data-ui="confirmRestore"]');if(button)button.disabled=false;}}

async function resolveRestore(which){if(restoring)return;restoring=true;try{await locked(()=>{const r=recoverAdventure(localStorage,which);if(!r.ok){toast('恢复尚未完成，备份仍保留，请先导出备份');return;}state=r.state;lastRaw=r.raw;blocked=false;storageError='';const gain=advance(state);if(gain.elapsed>60&&(gain.exp||gain.rounds))state.offline=gain;save();close();go('home');toast(blocked?'保存仍失败，请导出当前进度':'恢复完成，两卷都已保留');});}finally{restoring=false;}}

document.addEventListener('change',async e=>{if(e.target.id==='craft-tier'||e.target.id==='craft-slot'){if(e.target.id==='craft-tier')craftTier=e.target.value;else craftSlot=e.target.value;render();return;}if(e.target.id==='tech-source'){techSource=e.target.value;render();return;}if(e.target.id==='tech-chapter'){techChapter=e.target.value;render();return;}if(e.target.id==='tech-loadout-main'||e.target.id==='tech-loadout-aux'){if(!techDraft)resetTechDraft();techDraft[e.target.id==='tech-loadout-main'?'main':'aux']=e.target.value;render();return;}if(e.target.id==='farm-mode'){updateFarmPreview();return;}if(e.target.id==='quality-filter'){bagQuality=e.target.value;bagVisible=24;render();return;}if(e.target.id==='import-save'){const file=e.target.files?.[0];if(!file)return;const readSerial=++importReadSerial,expectedRunId=state?.runId||null;if(file.size>512000)return toast('存档文件过大，请选择问山导出的 JSON 文件');try{const contents=await file.text();if(readSerial!==importReadSerial||!$('#dialog').open||activeModal!=='saves')return;if((state?.runId||null)!==expectedRunId)return toast('当前仙途已变化，请重新选择存档文件');const parsed=JSON.parse(contents),valid=validateSave(parsed);if(!valid)throw new Error('invalid');pendingImport=valid;pendingImportRunId=expectedRunId;gearDetail=null;modal(`<h2>恢复这份存档？</h2><p><b>${esc(valid.name)}</b> · ${levelName(valid)}</p><p>修为 ${fmt(valid.exp)} · 灵石 ${fmt(valid.stones)} · 通关 ${valid.cleared.length} 处</p><p>当前进度会替换“上一卷备份”，再恢复这份文件。若要保留更早备份，请先导出。旧卷不受影响。</p><div class="button-pair"><button class="secondary" data-close>取消</button><button class="primary" data-ui="confirmImport">备份当前并恢复</button></div>`,'importPreview');}catch{if(readSerial!==importReadSerial||!$('#dialog').open||activeModal!=='saves')return;pendingImport=null;toast('无法读取这份存档，当前进度未修改。请选择当前仙途导出的存档；旧卷进度仍保存在旧卷入口。');}}});

function changeMap(pane,area=null,chapter=null,fromSource=false){const navigation=++viewSerial,expectedRunId=fromSource&&$('#dialog').open?modalRunId:state.runId;if(state.battle){toast('先完成当前斗法，再切换地点');return;}locked(()=>{if(navigation!==viewSerial)return;sync();if(blocked){render();return toast('存档异常，请先导出备份');}if(expectedRunId!==state.runId){render();refreshModalAvailability();return toast('当前仙途已变化，请重新查看来源');}if(state.battle){render();refreshModalAvailability();return toast('先完成当前斗法，再切换地点');}const selected=area||state.uiMap?.area||'brook';state.uiMap={pane,area:selected,chapter:chapter||(pane==='core'?'core':pane==='foundation'?'foundation':pane==='finale'?'qi':realmChapter(AREAS.find(a=>a.id===selected)?.gate||1))};save();if(fromSource){close();go('map');const node=$(pane==='regions'?'#area-'+selected:pane==='tower'?'.tower-section':'.finale-panel');focusContent(node);}else render();});}
function battleLocation(){const b=state.battle||state.lastBattle;if(b?.type==='sect'){sectPane=b.specialtyTrial?'specialty':'trials';go('sect');}else{if(b?.type==='area')state.uiMap={pane:'regions',area:b.id};else if(b?.type==='tower')state.uiMap={...state.uiMap,pane:'tower'};else if(b&&['finale','extreme','foundation','core'].includes(b.type))state.uiMap={...state.uiMap,pane:b.type==='core'?'core':b.type==='foundation'?'foundation':'finale'};go('map');}const node=$(state.battle?'.battle':'.result-panel');focusContent(node);}
function showLoadout(){openTechniques({editor:true});}

function showFarmConfig(id){pendingFarm=id;pendingFarmRunId=state.runId;gearDetail=null;const a=AREAS.find(a=>a.id===id);if(!a)return;modal(`<h2>${a.name} · 挂机计划</h2><p>每轮 ${a.seconds} 秒，收益自动入袋。离线单次最多结算8小时。</p>${state.farm===id?`<p class="small-note">正在此地挂机：${farmPlanText()}。修改计划会保留当前轮次进度。</p>`:state.farm?'<p class="warning small-note">切换地点会结束原计划，并从新地点的一轮开始计时；已入袋的收益保留。</p>':''}<form id="farm-form"><label>计划<select id="farm-mode"><option value="unlimited">持续挂机</option><option value="rounds">完成指定轮数后停止</option><option value="duration">运行指定分钟后停止</option></select></label><label id="farm-value-row" hidden><span id="farm-value-label">轮数</span><input id="farm-value" type="number" min="1" max="10000" value="10" inputmode="numeric" disabled></label><section id="farm-preview" class="farm-projection" aria-label="预计挂机收益"></section><p class="small-note">时长到点后，不足一整轮的部分不发奖励。装备按本图累计轮数发放，已有计数保留。</p><button class="primary large" type="submit" data-battle-lock data-unavailable="${!state.cleared.includes(id)||state.level<a.gate}" ${state.battle||!state.cleared.includes(id)||state.level<a.gate?'disabled':''}>${state.farm===id?'更新挂机计划':'开始计划'}</button>${!state.cleared.includes(id)?'<p class="warning">先亲自通关一次，才能在此挂机。</p>':''}<p class="warning" data-battle-notice ${state.battle?'':'hidden'}>斗法结束后才能修改挂机。</p></form><p class="small-note">行囊超过200件会提醒整理，但不会丢弃任何新掉落。</p>`,'farm');updateFarmPreview();}
function updateFarmPreview(){if(activeModal!=='farm'||!pendingFarm)return;const mode=$('#farm-mode').value||'unlimited',input=$('#farm-value'),row=$('#farm-value-row');row.hidden=mode==='unlimited';input.disabled=mode==='unlimited';input.max=mode==='duration'?'480':'10000';$('#farm-value-label').textContent=mode==='duration'?'运行分钟（1–480）':'完成轮数（1–10000）';const p=farmProjection(state,pendingFarm,mode,Number(input.value)),target=$('#farm-preview');if(!p){target.innerHTML='<p class="warning">请输入允许范围内的整数，再查看计划收益。</p>';return;}target.innerHTML=`<b>${mode==='unlimited'?'按单次离线8小时估算':'本次计划预计'} · ${p.rounds}轮</b><p>${mode==='unlimited'?'最多结算':'所需时间'} ${time(p.seconds)}${p.carry?' · 已计入当前轮进度':''}</p><p>${rewardText(p.rewards)}</p><p class="drop-guarantee">装备 ${p.items} 件（主掉落 ${p.mainItems}＋三部位 ${p.accessoryItems}）${p.items?' · 主掉落种类与词条随机，三部位依次轮换':' · 未达下一次装备轮数，累计计数保留'}</p>${p.needsReturn?`<p class="warning small-note">此计划超过8小时。一次离线最多完成 ${p.firstAbsenceRounds} 轮，需再次打开游戏后继续剩余计划。</p>`:''}`;}

function showRecommendRules(){gearDetail=null;const w=equipmentWeights(state),p=combatProfile(state),parts=equipmentScoreParts(state);modal(`<h2>按当前流派推荐</h2><p>当前配法：${p.name}。一键配装会比较整套六件组合，同时考虑两件 / 三件套、神器与主辅技能加成。</p><p class="formula">基础评分 = 攻伐 × ${w.atk} + 护体 × ${w.def} + 气血 × ${w.hp}</p><p>技能倍率、破防、闪避、回血、护盾和山河钟会调整权重。当前组合最终系数：攻伐${parts.coeff.atk.toFixed(2)}、护体${parts.coeff.def.toFixed(2)}、气血${parts.coeff.hp.toFixed(2)}。整套更换后会重新计算。我们会选出这套评分下的最高组合，<b>不代表每种敌人面前都绝对最强</b>。高评分不等于实际伤害。</p><p>它不会丢弃装备、改变强化，也不会解锁已锁定装备。平分时保留当前穿戴。词条属性不同的同名装备会分别比较。</p><button class="primary large" data-ui="recommendPreview">查看推荐结果</button>`);}

function help(){modal(`<p class="volume">入门卷</p><h2>一息一程，慢慢来</h2><ol class="help-list"><li><b>修炼与突破</b><p>先点开始修炼，基础每 30 秒 +6 修为。修为超过需求仍会持续累计。手动突破只扣本层所需，剩余修为保留，依次是一至九层、圆满。炼气圆满可直接成为普通筑基；先成极境再突破则为天道筑基，两条路都能游玩完整筑基卷，并在圆满、完成问基三试后准备结丹。金丹初卷开放一至三层，两张地图与一场初试。</p></li><li><b>功法叠加与套组</b><p>功法页可预览3类战斗套组和周天归元吐纳套组，按明确的主修、辅修顺序搭配。法宝录中同系列激活2/3件可共鸣，不同系列叠加。功法页统一学习、升级与配置主辅。所有已学被动全部同时生效。每次所得 = 境界基础 ×（1 + 总修为加成），炼气基础6、筑基基础24；间隔 = 30 ×（1 − 总减时），最短 10 秒。</p></li><li><b>历练与挂机</b><p>先自动或手动打通一关，再选择在此挂机。可设置轮数或时长，打完仍留在原地图，可直接重试。一次只挂一处，修炼同时继续。本图累计每 5 轮得1件主掉落，并额外轮换1件道冠、靴履或腰带，资源自动入袋。收益汇总只是记录，收起不会重复领取。</p></li><li><b>战斗</b><p>出剑稳定伤害；技能按钮标明当前招式与真气消耗。守势回 2 真气并大幅减伤；对手每第三回合蓄势，不同地区招式不同。闪避步消耗1真气，成功率见按钮；失败不掉物品。</p></li><li><b>装备与流派</b><p>术修低耗破防，剑修高倍率爆发，体修回血护身。听竹三件让技能回血，照月三件增加技能攻伐倍率。套装需穿戴才生效。一线天是兵器神器，仍需穿戴；山河钟、问山印是独立法宝，在行囊的法宝录激活一次后永久生效，不占六格，多件加成叠加。原佩环栏称为灵饰。强化存于部位，换装完全继承。宗门职位随境界与声望自动晋升。</p></li><li><b>筑基与道基</b><p>突破前选择锋行、厚土或灵息道基。筑基类型由炼气根基决定，不能随意切换；本道基可脱战免费改换。筑基一至九层、圆满逐步开放4处地图，关键进阶须先通关对应区域。圆满即可完成问基三试，极境可选，金丹篇尚未开放。</p></li><li><b>筑基地图支线</b><p>四地普通通关后，在对应地图展开支线。筑基二、四、七层及圆满开放四项试炼，分别有截潮、破甲、辨招、消解星压的机制。首胜奖励只发一次，重访仅练习；支线不推进普通掉落计数，不影响挂机。山中缘事仍由普通首次及每三次主动胜利触发，挂机不触发。</p></li><li><b>宗门专修与炼器</b><p>筑基一层且完成本门执事试炼，可挑战专修试炼，解锁两条互斥道路；只有当前宗门所选专修生效，脱战免费改换。行囊和坊市可定向炼制六个部位，固定材料换固定成品，确认前可看实际换装效果，无随机重洗。</p></li><li><b>配装预设</b><p>修行、行囊和功法页都能打开预设。调整好当前配置，存入修炼或闯关；切换前会比较实际属性和修炼收益。缺件时整套不会切换，预设也不会自动保护装备免于分解。普通与天道筑基类型不受切换影响。</p></li><li><b>离线与本机存档</b><p>离线单次最多 8 小时，只结算已开启的修炼和挂机。装备新掉落可能带小幅词条；锁定保护整组。一键配装考虑整套加成，分解前会展示清单。修为会超过境界需求持续累积，不会自动突破；离线最多结算 8 小时，与修为上限无关。此存档仅在当前设备和浏览器中；继续用原主屏幕入口，别清除网站数据。</p></li></ol>${state?`<button class="primary large" data-ui="replay">重新看操作指引</button>`:''}`);}
function saves(){let previous=false,recoveryCurrent=false,recoveryPrevious=false,recoveryMemory=false,beforeImport=false,recoveryPending=false,treasureBackup=false,towerBackup=false,coreBackup=false,foundationBackup=false,resonanceBackup=false,fieldBackup=false,specialtyBackup=false;try{towerBackup=!!localStorage.getItem(KEY+'-before-auto-tower');coreBackup=!!localStorage.getItem(KEY+'-before-golden-core');specialtyBackup=!!localStorage.getItem(KEY+'-before-sect-crafting');fieldBackup=!!localStorage.getItem(KEY+'-before-field-trials');resonanceBackup=!!localStorage.getItem(KEY+'-before-resonance');foundationBackup=!!localStorage.getItem(KEY+'-before-foundation-chapter');treasureBackup=!!localStorage.getItem(KEY+'-before-treasure-activation');previous=!!localStorage.getItem(KEY+'-previous-adventure');recoveryCurrent=!!localStorage.getItem(KEY+'-before-restore-current');recoveryPrevious=!!localStorage.getItem(KEY+'-before-restore-previous');beforeImport=!!localStorage.getItem(KEY+'-before-import');recoveryMemory=!!localStorage.getItem(KEY+'-before-restore-memory');recoveryPending=!!localStorage.getItem(KEY+'-restore-pending');}catch{}modal(`<h2>本机存档</h2><div class="save-stamp ${blocked?'warning':''}"><b id="save-stamp-status">${savedText()}</b><small>当前版本 v${APP_VERSION} · 仅当前设备</small>${blocked&&state?.savedAt?`<small>上次成功：${new Date(state.savedAt).toLocaleTimeString('zh-CN',{hour12:false})}</small>`:''}</div><p>当前进度仅存在这台设备的浏览器。请在换设备、清理缓存前导出一份文件。原主屏幕图标继续可用，更新不需要重新添加。</p>${!navigator.locks?.request?'<p class="warning">当前浏览器不支持多窗口互斥保存，请只保留一个游戏窗口。</p>':''}<p class="warning">不要清除网站数据，也不要使用无痕模式。更换设备不会自动同步。</p>${storageError?`<p>${esc(storageError)}</p>`:''}${recoveryPending?'<section class="recovery-alert"><h3>有未完成的恢复操作</h3><p>原两卷与恢复前页面进度都已保留。选择回到原进度，或完成原先的恢复；重试不会覆盖这些备份。</p><button class="primary large" data-ui="recoverCurrent">回到恢复前页面进度</button><button class="secondary large" data-ui="recoverPrevious">完成恢复上一卷</button></section>':''}<div class="save-actions"><label class="import-label">从文件恢复存档<input type="file" id="import-save" accept=".json,application/json" ${recoveryPending?'disabled':''}></label>${state?'<button class="primary" data-export="current">导出当前进度</button>':''}${legacy?'<button class="secondary" data-export="legacy">导出旧版进度</button><a class="button secondary" href="legacy/index.html">回到旧卷游玩</a>':''}${previous?'<button class="secondary" data-ui="restorePrevious">恢复上一卷</button>':''}${blocked?'<button data-export="raw">导出原始数据</button>':''}${recoveryCurrent?'<button class="secondary" data-export="restoreCurrent">导出恢复前的当前卷</button>':''}${recoveryMemory?'<button class="secondary" data-export="restoreMemory">导出恢复前页面进度</button>':''}${recoveryPrevious?'<button class="secondary" data-export="restorePrevious">导出恢复前的上一卷</button>':''}${beforeImport?'<button class="secondary" data-export="beforeImport">导出导入前的存档</button>':''}${treasureBackup?'<button class="secondary" data-export="beforeTreasures">导出法宝改版前备份</button>':''}${resonanceBackup?'<button class="secondary" data-export="beforeResonance">导出共鸣开放前备份</button>':''}${towerBackup?'<button class="secondary" data-export="beforeTower">导出连续闯塔更新前备份</button>':''}${coreBackup?'<button class="secondary" data-export="beforeCore">导出金丹开放前备份</button>':''}${specialtyBackup?'<button class="secondary" data-export="beforeSpecialization">导出宗门炼器更新前备份</button>':''}${fieldBackup?'<button class="secondary" data-export="beforeFieldTrials">导出筑基支线更新前备份</button>':''}${foundationBackup?'<button class="secondary" data-export="beforeFoundation">导出筑基开放前备份</button>':''}</div><p class="small-note">导入前会展示道号与境界并再次确认，当前进度另存备份。<br>展开新卷前会保留上一卷备份。旧版使用原来的独立存档，不会被新版覆盖。</p>`,'saves');}
function download(kind){try{const raw=kind==='current'&&state?JSON.stringify(state):localStorage.getItem(kind==='legacy'?LEGACY_KEY:kind==='restoreCurrent'?KEY+'-before-restore-current':kind==='restorePrevious'?KEY+'-before-restore-previous':kind==='beforeTower'?KEY+'-before-auto-tower':kind==='beforeCore'?KEY+'-before-golden-core':kind==='beforeSpecialization'?KEY+'-before-sect-crafting':kind==='beforeFieldTrials'?KEY+'-before-field-trials':kind==='beforeResonance'?KEY+'-before-resonance':kind==='beforeFoundation'?KEY+'-before-foundation-chapter':kind==='beforeTreasures'?KEY+'-before-treasure-activation':kind==='beforeImport'?KEY+'-before-import':kind==='restoreMemory'?KEY+'-before-restore-memory':KEY);if(!raw)return toast('没有可导出的存档');const blob=new Blob([raw],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`问山-${({legacy:'旧卷',restoreCurrent:'恢复前当前卷',restorePrevious:'恢复前上一卷',beforeImport:'导入前备份',beforeTreasures:'法宝改版前备份',beforeTower:'连续闯塔更新前备份',beforeCore:'金丹开放前备份',beforeSpecialization:'宗门炼器更新前备份',beforeFieldTrials:'筑基支线更新前备份',beforeResonance:'共鸣开放前备份',beforeFoundation:'筑基开放前备份',restoreMemory:'恢复前页面进度'})[kind]||chapterLabel(state)}-${new Date().toISOString().slice(0,10)}.json`;a.click();if(kind==='current'&&!blocked)action('markExport');setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出存档，请妥善保管');}catch{toast('导出失败，请保留此页面');}}
function beginNew(){if(state){modal(`<h2>另起一卷？</h2><p>当前仙途会放入“上一卷备份”，可以在本机存档中恢复。更早的上一卷备份会被替换；可先导出留存。</p><div class="button-pair"><button class="secondary" data-export="current">先导出当前卷</button><button class="primary" data-ui="confirmNew">保留备份并新建</button></div>`);}else{screen='create';render();}}
function bonusStatusSignature(){return JSON.stringify([state.runId,state.cultivating,cultivation(state),statBreakdown(state).sources.filter(r=>r.gain||r.speed)]);}
function showBonuses(preserveScroll=false){gearDetail=null;bonusViewSignature=bonusStatusSignature();const b=bonuses(state),c=cultivation(state),hour=cultivationProjection(state,3600),night=cultivationProjection(state,OFFLINE_CAP),sources=statBreakdown(state).sources.filter(r=>r.gain||r.speed);modal(`<h2>灵息如何流转</h2><div class="equation">每 ${fmt(c.interval)} 秒<br><strong>+${fmt(c.gain)} 修为</strong><br><span>约 ${fmt(c.perMinute)} 修为 / 分钟</span></div><p>当前境界基础为每 30 秒 +${c.baseGain} 修为。各来源增修相加，减时相加；间隔最低10秒。</p><p>单次修为总加成 +${fmt(b.gain*100)}% · 总减时 ${fmt(b.speed*100)}%${c.interval===10?'，已触及间隔下限':''}</p>${sources.map(r=>`<div class="source-row"><b>${r.name}</b><small>${r.gain?'单次修为 +'+fmt(r.gain*100)+'%':''}${r.gain&&r.speed?' · ':''}${r.speed?'减时 +'+fmt(r.speed*100)+'%':''}</small></div>`).join('')||'<p>尚未获得修炼加成</p>'}<section class="cultivation-forecast"><h3>保持当前配法连续修炼</h3><p>未来1小时：${fmt(hour.exp)} 修为 · ${hour.ticks} 次运功<br>未来8小时：${fmt(night.exp)} 修为 · ${night.ticks} 次运功</p><small>计入打开面板时的当前运功进度，只算完整次数；更换功法、破境或暂停会改变结果。${state.cultivating?'当前已开启修炼。':'当前未开启修炼，上述为开启后的预估。'}</small></section><p>每分钟产出按当前功法估算；修炼结算仍按整次运功进行。在线与离线使用相同效率，离线单次最多8小时。</p><p>已学功法被动一直叠加。周天归元套组只在当前主辅搭配正确时生效，法宝共鸣则按永久激活件数生效。</p><div class="button-pair"><button class="secondary" data-ui="loadout">查看功法套组</button><button class="secondary" data-ui="treasures">查看法宝共鸣</button></div>`,'bonuses',preserveScroll);}

document.addEventListener('input',e=>{if(e.target.id==='character-name')draftName=e.target.value;if(e.target.id==='farm-value')updateFarmPreview();});
document.addEventListener('focusout',e=>{if(['craft-tier','craft-slot'].includes(e.target.id)&&craftRefreshPending)setTimeout(()=>{if(craftRefreshPending)render();},0);if(['tech-source','tech-chapter','tech-loadout-main','tech-loadout-aux'].includes(e.target.id)&&techRefreshPending)setTimeout(()=>{if(techRefreshPending)render();},0);if(e.target.id==='dismantle-count'){clearTimeout(gearRefreshTimer);gearRefreshTimer=setTimeout(()=>refreshOpenGear(),0);}});
document.addEventListener('submit',async e=>{if(e.target.id==='tech-loadout-form'){e.preventDefault();const main=$('#tech-loadout-main').value,aux=$('#tech-loadout-aux').value||null,expectedRunId=techDraft?.runId;if(main===aux){$('#tech-loadout-error').textContent='主辅不可重复，请调整其中一项。';return;}const r=await action('loadout',{main,aux,expectedRunId});if(r?.ok){resetTechDraft();techEditor=false;render();}else if($('#tech-loadout-error'))$('#tech-loadout-error').textContent=r?.text||'未能保存配法';return;}if(e.target.id==='dismantle-item-form'){e.preventDefault();const id=gearDetail?.id,count=Number($('#dismantle-count').value);if(!id||!Number.isInteger(count)||count<1||count>dismantleCapacity(state,id))return toast('请输入可分解范围内的整数数量');showDismantlePreview({mode:'manual',items:[{id,count}]});return;}if(e.target.id==='farm-form'){e.preventDefault();const mode=$('#farm-mode').value,value=Number($('#farm-value').value),id=pendingFarm;if(mode!=='unlimited'&&(!Number.isInteger(value)||value<1||value>(mode==='duration'?480:10000))){toast('请输入允许范围内的整数');return;}const expectedRunId=pendingFarmRunId;close();await action('farm',{id,plan:{mode,value},expectedRunId});return;}if(e.target.id!=='character-form')return;e.preventDefault();if(creating||screen!=='create'||blocked)return;const name=$('#character-name').value.trim();if(!name)return toast('请先取一个道号');creating=true;await locked(()=>{try{preserveLegacy(localStorage);const current=localStorage.getItem(KEY);if(current)localStorage.setItem(KEY+'-previous-adventure',current);state=createState({name,gender,portrait});lastRaw=null;save();screen='game';tab='home';render();window.scrollTo(0,0);}catch{toast('无法安全保存新卷，原存档未覆盖');}finally{creating=false;}});});
document.addEventListener('click',e=>{const el=e.target.closest('button,a[data-ui]');if(!el)return;const d=el.dataset;if(el.disabled)return;if(d.close!==undefined)return close();if(d.specialtyChoice){showSpecialtyPreview(d.specialtyChoice==='none'?null:d.specialtyChoice);return;}if(d.craftSlot){openCrafting(d.craftSlot);return;}if(d.presetSave){showPresetPreview(d.presetSave,'save');return;}if(d.presetPreview){showPresetPreview(d.presetPreview);return;}if(d.presetRefresh){showPresetPreview(d.presetRefresh,d.presetMode);return;}if(d.comboRecipe){previewCombo(d.comboRecipe);return;}if(d.techId){openTechniques({id:d.techId});return;}if(d.techStatus){techStatus=d.techStatus;render();return;}if(d.techSource){openTechniques({source:d.techSource,chapter:d.techChapter||'all'});return;}if(d.techSect){sectPane=state.sect===d.techSect?'trials':'overview';go('sect');if(state.sect!==d.techSect){const n=$('.sect-switch');if(n){n.open=true;n.scrollIntoView({block:'start',behavior:scrollBehavior()});}}return;}if(d.export)return download(d.export);if(d.visualMode){visualMode=d.visualMode;try{localStorage.setItem('wenshan-visual-mode',visualMode);}catch{}applyVisualMode();clearEffects();render();showVisualSettings();return;}if(d.farmGoal){farmGoal=d.farmGoal;showFarmGoals();return;}if(d.farmMaterial){farmMaterial=d.farmMaterial;showFarmGoals();return;}if(d.sourceArea){changeMap('regions',d.sourceArea,null,true);return;}if(d.sourceRoute){changeMap(d.sourceRoute,null,null,true);return;}if(d.foundationPath){if(pendingFoundation){pendingFoundation.path=d.foundationPath;renderFoundationPicker(true);}return;}if(d.marketChapter){marketChapter=d.marketChapter;render();return;}if(d.mapChapter){changeMap('regions',d.mapChapter==='core'?'dawn':d.mapChapter==='foundation'?'reed':'brook',d.mapChapter);return;}if(d.mapPane){changeMap(d.mapPane);return;}if(d.area){changeMap('regions',d.area);return;}if(d.sectPane){if(d.sectPane==='techniques'){openTechniques({source:state.sect||'all'});return;}sectPane=d.sectPane;render();return;}if(d.marketPane){marketPane=d.marketPane;render();return;}if(d.farmConfig){showFarmConfig(d.farmConfig);return;}if(d.encounter){action('encounter',{choice:d.encounter});return;}if(d.equipmentSlot){pulseElement(el);showGearDetail(state.equipment[d.equipmentSlot],d.equipmentSlot);return;}if(d.gear){showGearDetail(d.gear);return;}if(d.bagFilter){bagFilter=d.bagFilter;bagVisible=24;render();return;}if(d.gender){gender=d.gender;portrait=PORTRAITS.find(p=>p.gender===gender).id;render();return;}if(d.portrait){portrait=d.portrait;render();return;}if(d.go){go(d.go,d.highlight);return;}if(d.guide){action('tutorial',{mode:d.guide});return;}if(d.resourceHunt){farmGoal=d.resourceHunt==='stones'?'stones':'materials';farmMaterial=d.resourceHunt;showFarmGoals();return;}if(d.resource){const info={stones:'通用货币：买装备、研习功法、强化部位。主要来自通关与挂机。',ore:'百炼材料：强化六个装备栏位。来自通关、挂机与装备分解。',herbs:'用于调息、炼回春丹、供奉宗门与结丹。主要来自通关与挂机。',jade:'用于筑基、结丹、各层破境、可选极境和高阶栏位强化。首通地图、玄铁崖起的已通关地图挂机与塔印兑换可得。'};modal(`<h2>${RES[d.resource]}</h2><p class="resource-exact">当前数量：<b>${fmt(state[d.resource])}</b></p><p>${info[d.resource]}</p>`);return;}if(d.action){action(d.action,{expectedViewSerial:['areaTrial','specialtyTrial','startTowerRun','resumeTowerRun'].includes(d.action)?viewSerial:undefined,id:d.id==='stop'?null:d.id,slot:d.slot,move:d.move,floor:d.floor?Number(d.floor):undefined,towerRunId:d.towerRunId,expectedTowerRunId:['combat','flee','toggleAuto','autoPills'].includes(d.action)?d.towerRunId:undefined,expectedBattleFloor:d.action==='combat'?d.battleFloor:undefined,stage:d.stage?Number(d.stage):undefined,tier:d.tier?Number(d.tier):undefined,kind:d.kind,expectedLevel:d.level!==undefined?Number(d.level):undefined,expectedRunId:d.runId||el.closest?.('[data-current-run]')?.dataset.currentRun||($('#dialog').open?modalRunId:state?.runId),expectedCost:d.cost?JSON.parse(d.cost):undefined,expectedPrice:d.price!==undefined?Number(d.price):undefined});return;}switch(d.ui){case 'profile':openProfile();break;case 'profileBack':go(['home','map','sect','market','bag','techniques'].includes(uiPrefs.profileReturn)?uiPrefs.profileReturn:'home');break;case 'corePrepare':showCorePreview();break;case 'confirmCore':confirmCore();break;case 'crafting':openCrafting();break;case 'craftPreview':showCraftPreview();break;case 'confirmCraft':confirmBuildChoice('craft');break;case 'confirmSpecialty':confirmBuildChoice('specialty');break;case 'presets':showPresets();break;case 'confirmPreset':confirmPreset();break;case 'breakthroughChecklist':{const n=$('[data-detail="cultivation-notes"]');if(n){n.open=true;$('#breakthrough-checklist')?.scrollIntoView({block:'center',behavior:scrollBehavior()});}break;}case 'techLoadout':if(tab!=='techniques'){showLoadout();break;}techEditor=!techEditor;if(techEditor)resetTechDraft();render();break;case 'techCancelLoadout':resetTechDraft();techEditor=false;render();break;case 'techReturn':go(techReturn||'home');break;case 'techReset':techStatus='all';techSource='all';techChapter='all';render();break;case 'foundationPath':showFoundationPicker('change');break;case 'confirmFoundation':confirmFoundation();break;case 'foundationHelp':foundationHelp();break;case 'treasures':showTreasures();break;case 'recoverCurrent':resolveRestore('current');break;case 'recoverPrevious':resolveRestore('previous');break;case 'equipDismantle':showEquipDismantle();break;case 'visualSettings':showVisualSettings();break;case 'dismantleHub':showDismantleHub();break;case 'recommendPreview':showRecommendation();break;case 'farmGoals':showFarmGoals();break;case 'gearHunt':farmGoal='gear';showFarmGoals();break;case 'moreGear':bagVisible+=24;render();break;case 'followGoal':followGoal();break;case 'farmReport':showFarmReport();break;case 'dismantle':showDismantle();break;case 'dismantleDuplicates':showDismantle('duplicates');break;case 'loadout':showLoadout();break;case 'recommendRules':showRecommendRules();break;case 'applyBest':if(pendingRecommendation){const {equipment,expectedRunId}=pendingRecommendation;close();action('equipRecommended',{equipment,expectedRunId});pendingRecommendation=null;}break;case 'battleLocation':battleLocation();break;case 'offlineDetails':gearDetail=null;modal(offline());break;case 'confirmDismantle':{const plan=pendingDismantle;close();if(plan)action('dismantle',plan);pendingDismantle=null;break;}case 'reportBag':close();go('bag');break;case 'ackFarm':{const receipt=pendingReceipt,expectedRunId=pendingReceiptRunId;close();action('ackFarm',{receipt,expectedRunId});pendingReceipt=null;break;}case 'confirmImport':confirmImport();break;case 'gearMarket':{const g=gearDetail?.id?itemInfo(state,gearDetail.id):null;marketChapter=realmChapter(g?(g.gate||1):state.level);close();marketPane='gear';go('market');break;}case 'guideToggle':guideOpen=!guideOpen;render();break;case 'menu':pauseTowerForBackground('回到主菜单后已暂停，点击继续');saveUiPosition();clearEffects();screen='menu';render();window.scrollTo(0,0);break;case 'continue':if(state.battle)battleLocation();else go(uiPrefs.tab||'home');break;case 'new':beginNew();break;case 'confirmNew':close();screen='create';render();break;case 'help':help();break;case 'saves':saves();break;case 'replay':close();guideOpen=true;action('tutorial',{mode:'replay'});go('home');break;case 'bonuses':showBonuses();break;case 'stats':showStats();break;case 'ascend':showFoundationPicker('ascend');break;case 'confirmAscend':confirmFoundation();break;case 'restorePrevious':showRestorePreview();break;case 'confirmRestore':restoreAdventure();break;}});
function live(){updateFarmPreview();if(screen!=='game'||!state)return;const c=cultivation(state),remaining=Math.max(0,c.interval-state.cultCarry);if($('#tick-count'))$('#tick-count').textContent=state.cultivating?time(remaining)+'后运功':'尚未开始';if($('#tick-fill'))$('#tick-fill').style.width=state.cultivating?pct(state.cultCarry,c.interval)+'%':'0%';if(state.farm){const a=AREAS.find(a=>a.id===state.farm);if($('#farm-count'))$('#farm-count').textContent=time(a.seconds-state.farmCarry)+'后归来';if($('#map-farm-count'))$('#map-farm-count').textContent=`${time(a.seconds-state.farmCarry)}后完成本轮 · ${farmPlanText()}`;}}
setInterval(()=>{if(!state||document.hidden||blocked)return;const queuedRun=state.runId,queuedTower=state.towerRun?.id;locked(()=>{if(document.hidden)return;sync();if(blocked){render();return;}if(queuedRun!==state.runId)return;const before=[state.exp,state.stones,state.contribution,state.hp,state.farm,state.battle?.turn],r=advance(state);let combat=null,towerSaved=false;if(screen==='game'&&state.towerRun?.active&&!state.towerRun.paused&&queuedTower===state.towerRun.id){const candidate=JSON.parse(JSON.stringify(state));combat=act(candidate,'towerStep',{now:Date.now()});if(combat?.ok){try{const raw=writeSave(localStorage,candidate,lastRaw);state=candidate;lastRaw=raw;towerSaved=true;}catch{blocked=true;storageError='闯塔保存失败，已暂停；请保留页面并导出进度';render();return;}}}else if(screen==='game'&&state.battle?.auto&&!state.towerRun?.active)combat=act(state,'autoStep',{now:Date.now()});const changed=before.some((x,i)=>x!==[state.exp,state.stones,state.contribution,state.hp,state.farm,state.battle?.turn][i]);if(!towerSaved&&(Date.now()%5000<1100||changed||combat?.ok))save();if(screen==='game'&&(changed||combat?.ok)){render(true);refreshOpenGear();refreshModalAvailability();}else live();if(r.exp)showGain(r.exp);if(r.items?.length)showLootFeedback(r.items);if(combat?.combat)showCombatFeedback(combat.combat);});},1000);
function pauseTowerForBackground(reason){const runId=state?.runId,towerId=state?.towerRun?.id;if(!state?.towerRun?.active)return;locked(()=>{sync();if(blocked||state?.runId!==runId||state?.towerRun?.id!==towerId)return;const candidate=JSON.parse(JSON.stringify(state));if(!pauseTowerRun(candidate,reason))return;try{lastRaw=writeSave(localStorage,candidate,lastRaw);state=candidate;}catch{blocked=true;storageError='暂停闯塔未保存，请保留页面并导出进度';}if(screen==='game'){render();refreshModalAvailability();}});}

document.addEventListener('visibilitychange',()=>{document.body?.classList.toggle('page-hidden',document.hidden);syncSceneMotion();if(document.hidden){pauseTowerForBackground('切到后台后已暂停，点击继续');saveUiPosition();clearEffects();clearTimeout(toastTimer);for(const q of ['#toast','#dialog-status']){$(q).classList.remove('show');$(q).textContent='';}}if(!document.hidden&&state&&!blocked)locked(()=>{sync();if(blocked){render();return;}const r=advance(state);if(r.elapsed>60&&(r.exp||r.rounds))state.offline=r;save();render();refreshOpenGear();refreshModalAvailability();});});
window.addEventListener('storage',e=>{if(e.key===KEY){sync();render(true);refreshOpenGear();refreshModalAvailability();}});
$('#dialog').addEventListener('close',()=>{syncSceneMotion();viewSerial++;pendingCraft=null;pendingSpecialty=null;pendingPreset=null;pendingDismantle=null;pendingRecommendation=null;pendingFarm=null;pendingFarmRunId=null;pendingReceipt=null;pendingReceiptRunId=null;importReadSerial++;pendingImport=null;pendingImportRunId=null;pendingRestore=null;activeModal='';gearDetail=null;pendingFoundation=null;gearRenderSignature='';gearFeedback=null;clearTimeout(gearFeedbackTimer);clearTimeout(gearRefreshTimer);});
// Let the inline loading screen paint without waiting for the full stylesheet.
const gameStyle=document.getElementById?.('game-style');
if(gameStyle&&gameStyle.media!=='all'){
 if(gameStyle.dataset.failed)window.wenshanLoadFailed?.();
 else {gameStyle.addEventListener('load',()=>render(),{once:true});gameStyle.addEventListener('error',()=>window.wenshanLoadFailed?.(),{once:true});}
}else render();
function showDismantleHub(){gearDetail=null;const plan=dismantlePlan(state);modal(`<span class="volume">按你的选择整理</span><h2>分解装备</h2><p>只保护身上穿戴的那1件和你手动锁定的物品。其他装备不论品阶、套装、神器，甚至最后1件，都能分解。</p><div class="dismantle-choices"><button class="primary large" data-ui="equipDismantle">穿上推荐，分解其余<small>先预览换装和完整分解清单</small></button><button class="danger large" data-ui="dismantle">分解所有未穿戴<small>${plan.count} 件可分解 · ${plan.ore} 玄铁</small></button></div><p>也可以回到行囊，点开任意装备，直接选择分解数量。</p><p class="small-note">收益：凡品1、良品3、灵品8、玄品18、神器50玄铁/件。手动锁定只防分解，不妨碍推荐配装穿戴。确认前不会改动任何装备。</p>${state.battle?'<p class="warning">斗法结束后才能确认分解。</p>':''}${state.dismantleUndo?`<button class="secondary large" data-action="undoDismantle" ${state.battle?'disabled':''}>撤销上次分解 · 归还${state.dismantleUndo.ore}玄铁</button>`:''}`);}

function sourceButtons(id,slot=null){if(!id)return ['head','boots','belt'].includes(slot)?'<button class="source-route" data-source-area="brook">青溪渡每5轮额外轮换掉落道冠、靴履、腰带</button><button class="source-route" data-source-area="bamboo">听竹林起可刷灵品三部位</button>':'<button class="source-route" data-ui="gearHunt">查看地图刷装备路线</button>';return gearSources(state,id).map(r=>r.kind==='trial'?`<button class="source-route" data-source-area="${r.id}"><b>${r.label} · 固定词条</b><small>${r.done?'奖励已领取；重访和挂机不重复掉落':!r.open?stageName(r.gate)+'开放':!r.cleared?'先完成本图普通通关':'展开地图支线即可挑战'}。分解后可用最近一次撤销恢复。</small></button>`:r.kind==='map'?`<button class="source-route" data-source-area="${r.id}"><b>${r.label}${r.bonus?' · 三部位轮换':''}</b><small>${r.firstClear?r.cleared?'已通关，可在法宝录直接激活；重访不再补发副本':r.open?'首次主动通关获1件法宝；挂机不重复掉落':stageName(r.gate)+'开放':r.cleared?'已通关，可挂机刷取':r.open?'通关一次后可挂机':stageName(r.gate)+'开放'}</small></button>`:r.kind==='shop'?'<button class="source-route" data-ui="gearMarket">坊市购买 · 无词条定型装备</button>':['tower','finale','foundation'].includes(r.kind)?`<button class="source-route" data-source-route="${r.kind}">${r.label}</button>`:`<p class="small-note">${r.label}</p>`).join('')||'<p>先选择一件装备查看来源</p>';}
function showFarmGoals(){gearDetail=null;const options=farmOptions(state,farmGoal,farmMaterial),materialName=RES[farmMaterial],available=AREAS.find(a=>a.gate<=state.level&&!state.cleared.includes(a.id));modal(`<span class="volume">想要什么，就往哪里去</span><h2>挂机目标</h2><div class="section-tabs">${[['stones','灵石'],['materials','材料'],['gear','装备']].map(([id,n])=>`<button data-farm-goal="${id}" class="${farmGoal===id?'active':''}">${n}</button>`).join('')}</div>${farmGoal==='materials'?`<div class="section-tabs">${['ore','herbs','jade'].map(k=>`<button data-farm-material="${k}" class="${farmMaterial===k?'active':''}">${RES[k]}</button>`).join('')}</div>`:''}<p class="small-note">${farmGoal==='gear'?'仅推荐已通关且境界已开放的地图。按装备阶段与品阶优先、掉落速度其次排序；收集指定套装可点装备查看来源。':'仅推荐已通关且境界已开放的地图，按'+(farmGoal==='stones'?'灵石':materialName)+'每小时产出排序。'}</p>${options.length?options.map((x,i)=>`<article class="farm-option"><div><h3>${i===0?'推荐 · ':''}${x.area.name}</h3><p>${farmGoal==='gear'?`${x.area.loot.map(id=>GEAR[id].name).join(' / ')}<br>另含：${x.area.accessories.map(id=>GEAR[id].name).join(' / ')}<br>每${time(x.area.seconds*5)} 2件，长期约${fmt(x.rate)}件/小时`:`约 ${fmt(x.rate)} ${farmGoal==='stones'?'灵石':materialName}/小时 · 每轮${x.area.seconds}秒`}</p></div><button class="primary" data-farm-config="${x.area.id}" ${state.battle?'disabled':''}>设置挂机</button><button class="text" data-source-area="${x.area.id}">查看地图</button></article>`).join(''):`<p class="empty-inventory">还没有符合目标的已通关地图</p><p>${!state.cleared.length?'先通关青溪渡，才能开始挂机刷装备和材料。':farmGoal==='materials'&&farmMaterial==='jade'?'灵髓挂机从炼气四层的玄铁崖开始，先提升境界并通关。':'可提升境界，解锁并通关更多区域。'}</p><button class="primary large" data-source-area="${farmGoal==='materials'&&farmMaterial==='jade'?'cliff':available?.id||'brook'}">查看可推进的地图</button>`}${state.battle?'<p class="warning">先结束当前斗法，再修改挂机计划。</p>':''}<p class="small-note">收益自动入袋，一次只挂一处。离线最多8小时，修炼可同时进行；不会因行囊整理线丢掉装备。</p>`);}
function showRecommendation(){gearDetail=null;const p=recommendationPreview(state);pendingRecommendation={...p,expectedRunId:state.runId};modal(`<span class="volume">先比较，再换装</span><h2>推荐配装预览</h2><p>${p.style} · 按当前主辅功法比较整套组合</p><div class="recommend-summary"><span>流派评分<b>${p.scoreBefore} → ${p.score}</b><em>${signed(p.score-p.scoreBefore)}</em></span><span>战力估值<b>${p.current.power} → ${p.after.power}</b><em>${signed(p.after.power-p.current.power)}</em></span></div><div class="comparison-table"><div class="compare-row table-labels"><span>属性</span><span>当前</span><span>推荐</span><span>变化</span></div>${[['atk','攻伐'],['def','护体'],['hp','气血']].map(([k,n])=>`<div class="compare-row"><span>${n}</span><span>${p.current[k]}</span><b>${p.after[k]}</b><strong>${signed(p.after[k]-p.current[k])}</strong></div>`).join('')}</div><h3>将更换 ${p.changes.length} 个栏位</h3>${p.changes.map(r=>`<div class="source-row"><span>${SLOTS[r.slot]} · 强化 +${state.enhance[r.slot]} 保留</span><small>${itemInfo(state,r.from)?.displayName||'空'}<br>换为 ${itemInfo(state,r.to)?.displayName||'空'}</small></div>`).join('')||'<p>当前穿戴已经是本评分下的推荐组合。</p>'}<h3>套装变化</h3>${p.sets.map(x=>`<p>${x.name}：${x.before} → ${x.after} 件${x.before<2&&x.after>=2?' · 激活二件效果':''}${x.before<3&&x.after>=3?' · 激活三件效果':''}${x.before>=2&&x.after<2?' · 失去二件效果':''}${x.before>=3&&x.after<3?' · 失去三件效果':''}</p>`).join('')}<p class="small-note">推荐原因：在已拥有的装备中，使${p.style}的整套评分最高。已计入实际属性、主辅技能权重、套装和神器。某一项属性可能下降，评分不等于实际伤害，也不保证对所有敌人最优。</p><div class="button-pair"><button class="secondary" data-close>保持当前</button><button class="primary" data-battle-lock data-unavailable="${!p.changes.length}" data-ui="applyBest" ${state.battle||!p.changes.length?'disabled':''}>穿上预览这套</button></div><p class="warning" data-battle-notice ${state.battle?'':'hidden'}>斗法结束后才能换装</p><button class="text" data-ui="recommendRules">查看详细评分规则</button>`);}
function foundationEffectText(id,type){const p=FOUNDATION_PATHS[id]?.[type];if(!p)return '';return [['atk','攻伐'],['def','护体'],['hp','气血'],['gain','单次修为'],['pierce','技能额外破防'],['guardHeal','守势额外回复最大气血']].filter(([k])=>p[k]).map(([k,n])=>`${n} +${Math.round(p[k]*1000)/10}%`).join(' · ');}
function showFoundationPicker(mode='ascend'){gearDetail=null;if(!state)return;if(mode==='ascend'&&state.level!==10)return toast('先修至炼气圆满');if(mode==='change'&&state.level<11)return toast('先完成筑基');pendingFoundation={mode,path:mode==='change'?state.foundationPath:null,runId:state.runId,type:mode==='ascend'?(state.extreme?'heaven':'normal'):state.foundationType};renderFoundationPicker();}
function renderFoundationPicker(preserveScroll=false){const p=pendingFoundation;if(!p)return;const changing=p.mode==='change',type=p.type,typeName=type==='heaven'?'天道筑基':'普通筑基',preview=p.path?{...state,level:changing?state.level:11,ascended:true,foundationType:type,foundationPath:p.path}:null,st=preview?stats(preview):null,c=preview?cultivation(preview):null;modal(`<span class="volume">${changing?'本道基':'筑基前，请先择道'}</span><h2>${changing?'改换道基':typeName}</h2><p>${changing?'改换不消耗资源，已有修为、功法、装备和法宝保留。':type==='heaven'?'已成炼气极境：本次为天道筑基，原20%战斗属性保留且只计算一次。':'当前为炼气圆满：本次为普通筑基。无需先成极境，完整筑基内容均可进入。'}</p><p class="small-note">筑基类型固定；选中的道基以后可脱战免费改换。天道道基的同类加成更高。</p><div class="foundation-options">${Object.entries(FOUNDATION_PATHS).map(([id,x])=>`<button type="button" data-foundation-path="${id}" class="${p.path===id?'selected':''}" aria-pressed="${p.path===id}"><strong>${x.name} · ${x.short}</strong><span>${typeName}：${foundationEffectText(id,type)}</span><small>${type==='heaven'?'普通对照：'+foundationEffectText(id,'normal'):'天道对照：'+foundationEffectText(id,'heaven')}</small></button>`).join('')}</div>${preview?`<section class="foundation-preview"><b>${changing?'改换后':'筑基后'}实际属性</b><p>攻伐 ${st.atk} · 护体 ${st.def} · 气血上限 ${st.hp}</p><p>每${fmt(c.interval)}秒获得${fmt(c.gain)}修为</p><small>已包含原有装备、强化、法宝、功法及根基，未重复叠加炼气极境。</small></section>`:'<p class="small-note">先选择一种道基，再核对实际属性。</p>'}<p>${changing?'费用：免费':'消耗：400 灵石、12 灵髓；现存修为全部保留，不另扣修为。'}</p>${!changing&&type==='normal'?'<p class="small-note">天道筑基还会保留炼气极境原有的20%战斗属性，道基加成也更高。若想先凝练极境，可取消返回修行页；确认普通筑基后，不能再改成天道。</p>':''}<p id="foundation-error" class="warning" role="status"></p><div class="button-pair"><button class="secondary" data-close>暂不决定</button><button class="primary" data-ui="confirmFoundation" data-battle-lock data-unavailable="${!p.path||!changing&&!afford(state,{stones:400,jade:12})}" ${!p.path||!!state.battle||!changing&&!afford(state,{stones:400,jade:12})?'disabled':''}>${changing?'确认改换道基':'确认筑基'}</button></div><p id="foundation-cost-warning" class="warning" ${changing||afford(state,{stones:400,jade:12})?'hidden':''}>灵石或灵髓不足，先积累材料再来。</p><p class="warning" data-battle-notice ${state.battle?'':'hidden'}>先结束斗法，再确认道基。</p>`,'foundationPicker',preserveScroll);}
async function confirmFoundation(){const p=pendingFoundation;if(!p||!p.path)return;const r=await action(p.mode==='change'?'setFoundationPath':'ascend',p.mode==='change'?{id:p.path,expectedRunId:p.runId}:{path:p.path,expectedRunId:p.runId,expectedType:p.type});if(r?.ok){close();if(p.mode==='ascend')showEffect('breakthrough','筑基已成',levelName(state));toast(r.text,'success');}else if(r)$('#foundation-error').textContent=r.text;}
function foundationHelp(){gearDetail=null;modal('<h2>筑基入门</h2><ol class="help-list"><li><b>先选本道基</b><p>锋行偏攻伐与破防，厚土偏气血与续航，灵息偏修为增长。脱战可免费改换，普通/天道类型不变。</p></li><li><b>从浮芦汀出发</b><p>通关后设为挂机，收集归潮装备与三部位。关键突破会写明需要哪一处首通，储存修为始终保留。</p></li><li><b>成长并择流派</b><p>筑基三层可进赤砾谷，六层进照影湖，九层进沉星渊；坊市、宗门有新功法。强化上限提高至15，原强化直接继承。</p></li><li><b>圆满完成问基三试</b><p>两种筑基都能完成，不要求极境。最后获得可激活法宝观澜镜。之后可准备结丹，进入金丹一至三层的小卷。</p></li></ol>');}
function showVisualSettings(){gearDetail=null;const reduced=window.matchMedia?.('(prefers-reduced-motion: reduce)').matches;modal(`<h2>画面与动效</h2><p>${reduced?'系统已开启“减少动态效果”，持续动画已停用。':visualMode==='light'?'当前为轻省模式，持续动画已停用。':'动效已开启：灵流绕身、法相呼吸、云气流动与装备微光。'}修为到账、破境与强化反馈按实际操作触发。</p><div class="visual-modes">${[['balanced','平衡','流动云气、灵流与轻量动作反馈'],['fine','精细','同样动效，加高清立绘，当前角色按需载入'],['light','轻省','保留完整画面，仅显示静态到账与操作提示']].map(([id,n,d])=>`<button data-visual-mode="${id}" class="${visualMode===id?'selected':''}"><b>${n}${visualMode===id?' · 当前':''}</b><small>${d}</small></button>`).join('')}</div><p class="small-note">系统的“减少动态效果”优先于画质设置；切到后台、打开面板或将场景滚出屏幕会暂停场景动效。设置只影响画面，不改变修炼与战斗。</p>`);}

function sceneBanner(id,alt){const newSect=['sect-jade','sect-blade','sect-stone'].includes(id),smallWidth=newSect?640:560,largeWidth=newSect?1280:1100;const label={'tower-journey':'问心高阁','scroll-library':'藏经静院','mountain-forge':'山炉有火','sect-gate':'云门清境','sect-jade':'青霄 · 云岫书院','sect-blade':'照寒 · 雪岭剑阁','sect-stone':'抱山 · 千仞石殿','travel-river':'山河行旅','golden-core':'洞府丹光'}[id];return `<figure class="scene-banner" data-scene="${id}"><img src="illustrations/${id}-small.webp" ${visualMode==='light'?'':`srcset="illustrations/${id}-small.webp ${smallWidth}w, illustrations/${id}-large.webp ${largeWidth}w"`} sizes="(max-width:600px) 92vw, 740px" width="1100" height="367" loading="lazy" decoding="async" alt="${alt}">${label?`<figcaption>${label}</figcaption>`:''}</figure>`;}
function coreChecklist(){const v=corePreview(state);return `<section id="breakthrough-checklist" class="progress-checklist"><h3>结丹准备 · 金丹初卷</h3><div class="requirement-row"><span>问基三试</span><b>${state.foundationFinale} / 3</b><small>${state.foundationFinale>=3?'已完成':'尚未完成'}</small>${state.foundationFinale<3?'<button class="text" data-source-route="foundation">前往问基三试</button>':''}</div><div class="requirement-row"><span>修为</span><b>${fmt(state.exp)} / ${fmt(v.need)}</b><small>${state.exp>=v.need?'已达标':'还需 '+fmt(v.need-state.exp)}</small></div>${Object.entries(v.cost).map(([k,n])=>`<div class="requirement-row"><span>${RES[k]}</span><b>${fmt(state[k])} / ${fmt(n)}</b><small>${state[k]>=n?'已备齐':'还差 '+fmt(n-state[k])}</small>${state[k]<n?`<button class="text" data-resource-hunt="${k}">获取${RES[k]}</button>`:''}</div>`).join('')}<p>确认结丹只扣这些资源，剩余修为保留。当前普通/天道类型与道基继续生效，不新增不可改换的选择。</p></section>`;}
function showCorePreview(){if(!state||state.level!==20)return toast('筑基圆满时可以准备结丹');const v=corePreview(state);pendingCore={runId:state.runId,signature:v.signature};gearDetail=null;modal(`<span class="volume">筑基圆满 · 结丹在即</span><h2>一息凝丹，叩开新山河</h2>${sceneBanner('golden-core','山中洞府的金色丹息')}${coreChecklist()}<section class="core-preview"><h3>结丹后的实际变化</h3>${coreStatPreview(v.next)}<p>进入金丹一层；丹霞渡、鸣金古炉与金丹初试逐步开放，本次止于金丹三层。</p><p>旧装备、栏位强化、被动功法、法宝共鸣和道基继续有效。</p></section><p class="warning">${state.foundationExtreme?'筑基极境已成，20%战斗属性会永久保留，并且只算一次。':'筑基极境尚未凝练。圆满可以直接结丹并完成本章；确认后不能返回筑基补炼极境。若想先投入极境，可取消返回修行页。'}</p><p id="core-status" role="status">${v.reason}</p><div class="button-pair"><button class="secondary" data-close>暂不结丹</button><button class="primary" data-ui="confirmCore" data-battle-lock data-unavailable="${!v.ready}" ${!v.ready||state.battle?'disabled':''}>确认结丹</button></div>`,'corePreview');}
async function confirmCore(){if(!pendingCore||activeAction||blocked)return;const p={...pendingCore},serial=viewSerial;activeAction=true;try{await locked(()=>{if(serial!==viewSerial||activeModal!=='corePreview'||!$('#dialog').open)return;sync();if(blocked)return;advance(state);if(state.runId!==p.runId)return toast('当前仙途已变化，请重新预览','error');const candidate=JSON.parse(JSON.stringify(state)),r=act(candidate,'condenseCore',{...p,expectedRunId:p.runId});if(!r.ok){refreshModalAvailability();return toast(r.text,'error');}try{const raw=writeSave(localStorage,candidate,lastRaw);state=candidate;lastRaw=raw;}catch{blocked=true;storageError='结丹未保存，原境界与材料未改变；请保留页面并导出进度';render();refreshModalAvailability();return toast(storageError,'error');}close();go('home');showEffect('breakthrough','金丹已成','丹息归一 · 原有积累全部延续');toast(r.text,'success');});}finally{activeAction=false;}}
function coreFinaleView(){const ready=state.level>=23&&state.cleared.includes('furnace');return `<section class="finale-panel"><span class="volume">金丹初卷 · 收束</span><h2>一息成丹</h2><p>在古炉余音里稳住丹息，完成金丹初期的最后一试。普通和天道均可，不要求任何极境或套装。</p>${!state.battle?sceneBanner('golden-core','金丹初成，洞府丹光渐稳'):''}${state.battle?.type==='core'?battleView():battleReport('core',1)}<p class="small-note">金丹三层并通关鸣金古炉开放。体修若40回合未能击破，可用松风剑诀作辅修补足伤害，或在气血充足时手动施放技能。首胜：5000灵石、200玄铁、100灵髓与「一息成丹」称号；称号不另加隐藏属性，重访无重复奖励。</p>${button(state.coreFinale?'重访初试 · 无奖励':'自动赴试','coreTrial','',!ready||!!state.battle,'primary large')}${!ready?'<p class="warning">先修至金丹三层，通关鸣金古炉。可在修行页查看当前目标。</p>':''}${state.coreFinale?'<p class="chapter-complete">金丹初卷已完成</p>':''}<p>本次开放到金丹三层，后续境界尚未开放。修为持续积累，地图挂机、旧章节与配装仍可继续。</p></section>`;}

function coreStatPreview(next){const a=stats(state),b=stats(next),c=cultivation(state),d=cultivation(next);return `<div class="preset-comparison"><div class="preset-compare-row"><span>实际效果</span><span>当前</span><span>结丹后</span></div>${[['攻伐',a.atk,b.atk],['护体',a.def,b.def],['气血上限',a.hp,b.hp],['修炼间隔 / 秒',c.interval,d.interval],['单次修为',c.gain,d.gain],['每分钟修为',c.perMinute,d.perMinute]].map(([n,x,y])=>`<div class="preset-compare-row"><span>${n}</span><span>${fmt(x)}</span><b>${fmt(y)}</b></div>`).join('')}</div><p class="small-note">结丹成功恢复到新气血上限；修炼间隔下限仍为10秒。</p>`;}

function openProfile(){if(!state)return;if($('#dialog').open)close();if(tab!=='profile')uiPrefs.profileReturn=tab;go('profile');}
function profileSlot(slot){const name=SLOTS[slot],id=state.equipment[slot],g=itemInfo(state,id),lv=state.enhance[slot]||0;return `<button class="profile-slot ${g?'quality-'+g.quality:'profile-slot-empty'} ${selectedSlot===slot?'profile-slot-selected':''}" data-equipment-slot="${slot}" aria-label="${name}，${g?g.displayName:'未装备'}，强化 ${lv}，查看详情" title="${g?g.displayName:'未装备'}"><span class="profile-slot-label">${name}</span><span class="gear-glint" data-motion="glint-${slot}" aria-hidden="true"></span>${gearIcon(slot)}<strong>${g?g.name:'未装备'}</strong><span class="profile-slot-meta"><small>${g?QUALITY[g.quality]:'空位'}</small><b>+${lv}</b></span></button>`;}
function profileView(){const st=stats(state),c=cultivation(state),cp=combatProfile(state),sect=SECTS.find(x=>x.id===state.sect),path=foundationChoice(state),spec=specialization(state),portrait=PORTRAITS.find(x=>x.id===state.portrait),main=TECHNIQUES.find(x=>x.id===state.combatLoadout?.main),aux=TECHNIQUES.find(x=>x.id===state.combatLoadout?.aux),active=Object.keys(activeTreasures(state)).length,origin={home:'修行',map:'山河',sect:'宗门',market:'坊市',bag:'行囊',techniques:'功法'}[uiPrefs.profileReturn]||'修行',equipped=Object.values(state.equipment).filter(Boolean).length;return `<section class="profile-page" aria-label="人物主页"><div class="profile-stage">${atmosphere('profile')}<div class="profile-toolbar"><button class="text" data-ui="profileBack">返回${origin}</button><span class="volume">人物志</span><button class="text" data-ui="stats">属性明细</button></div><header class="profile-heading"><div><h1 title="${esc(state.name)}">${esc(state.name)}</h1><p>${levelName(state)}</p></div><button class="profile-power" data-ui="stats" aria-label="战力估值 ${fmt(st.power)}，查看属性来源"><small>战力估值</small><strong>${fmt(st.power)}</strong></button></header><div class="profile-identities"><button class="text" data-go="sect">${sect?sect.name+' · '+RANKS[rank(state)].name:'散修 · 尚未入宗'}</button>${state.level>=11?`<span>${state.foundationType==='heaven'?'天道筑基':'普通筑基'}${path?' · '+path.name:' · 尚未择道基'}</span>`:`<span>${state.gender==='female'?'女修':'男修'} · ${portrait?.name||'入山修士'}</span>`}</div><div class="profile-showcase"><figure class="profile-portrait"><div class="profile-halo" data-motion="profile-halo" aria-hidden="true"></div><img data-motion="standing-breath" src="${characterArt('standing')}" data-character="${state.portrait}" data-pose="standing" width="600" height="900" decoding="async" alt="${portrait?.name||'当前角色'}，站姿人物立绘"><figcaption>${portrait?.name||'入山修士'}</figcaption></figure><div class="profile-gear-grid" role="group" aria-label="人物六格装备">${['weapon','head','robe','boots','charm','belt'].map(profileSlot).join('')}</div></div><section class="profile-vitals" aria-label="当前基本属性"><div class="profile-hp"><span>气血</span><b data-profile-stat="hp">${fmt(state.hp)} / ${fmt(st.hp)}</b>${bar(state.hp,st.hp,'当前气血')}</div><div><span>攻伐</span><b data-profile-stat="atk">${fmt(st.atk)}</b></div><div><span>护体</span><b data-profile-stat="def">${fmt(st.def)}</b></div></section></div><p class="profile-equipment-note">已穿戴 ${equipped} / 6 · 点击格子查看、替换或强化</p><div class="profile-utilities"><button class="secondary" data-ui="treasures"><b>法宝录</b><span>已激活 ${active} / ${Object.keys(TREASURES).length}</span></button><button class="secondary" data-ui="presets"><b>配装预设</b><span>修炼 / 闯关</span></button></div><p class="profile-treasure-note">法宝激活后永久叠加，不占六格装备。</p>${state.battle||state.towerRun?.active?'<p class="warning profile-battle-note">斗法或连续闯塔进行中，可以查阅；结束后再换装、强化或切预设。<button class="text" data-ui="battleLocation">查看当前斗法</button></p>':''}<details class="profile-details" data-detail="profile-cultivation"><summary>修炼与主辅功法</summary><dl><div><dt>储存修为</dt><dd>${fmt(state.exp)}</dd></div><div><dt>吐纳效率</dt><dd>每 ${fmt(c.interval)} 秒 +${fmt(c.gain)}<small>约 ${fmt(c.perMinute)} 修为 / 分钟</small></dd></div><div><dt>主修</dt><dd>${main?.name||'随当前宗门'}<small>${cp.skill}</small></dd></div><div><dt>辅修</dt><dd>${aux?.name||'暂未配置'}</dd></div><div><dt>功法套组</dt><dd>${cp.combo?cp.combo.name:'当前未触发'}</dd></div></dl><p class="small-note">所有已学被动继续叠加；主辅配置决定招式与当前套组。</p><button class="secondary" data-go="techniques">查看功法总览</button></details><details class="profile-details" data-detail="profile-foundation"><summary>根基、宗门与已获称号</summary><dl><div><dt>宗门职位</dt><dd>${sect?sect.name+' · '+RANKS[rank(state)].name:'尚未加入宗门'}</dd></div><div><dt>当前专修</dt><dd>${spec?.name||'暂无生效专修'}</dd></div><div><dt>筑基根基</dt><dd>${state.level>=11?(state.foundationType==='heaven'?'天道筑基':'普通筑基'):'尚未筑基'}${path?'<small>'+path.name+'</small>':''}</dd></div><div><dt>极境积累</dt><dd>${[state.extreme?'炼气极境 · 战斗属性 +20%':'',state.foundationExtreme?'筑基极境 · 战斗属性 +20%':''].filter(Boolean).join('<br>')||'未凝练极境，仍可正常进阶'}</dd></div>${state.extremeTrial||state.coreFinale?`<div><dt>已获称号</dt><dd>${[state.extremeTrial?'极境问山人':'',state.coreFinale?'一息成丹':''].filter(Boolean).join(' · ')}</dd></div>`:''}</dl><p class="small-note">这里展示已实际生效的身份和积累；未获得的称号不会显示。</p><button class="secondary" data-ui="stats">属性明细与加成来源</button></details></section>`;}

function combatBusy(){return !!state.battle||!!state.towerRun?.active;}
